def _eh_arquivo_cena_gerada(nome_arq):
    """Retorna True se o arquivo representa uma mídia de cena válida (.mp4/.mov/.webm/.png/.jpg/.jpeg/.webp),
    ignorando thumbnails, folhas de contato e referências de personagem."""
    fn_l = os.path.basename(str(nome_arq or "")).lower()
    if not fn_l.endswith((".mp4", ".mov", ".webm", ".png", ".jpg", ".jpeg", ".webp")):
        return False
    ignorar = ("_thumb.", "contact_sheet", "existing_reference", "all_references", "capa_thumb", "avatar_thumb", "thumb_")
    return not any(tok in fn_l for tok in ignorar)


def _indice_cena_arquivo(nome_arq):
    """Extrai o índice numérico 1-based de um arquivo de cena (ex.: `001_cena_001.mp4`, `cena_105.jpg`, `112_bloco.mp4`)."""
    bn = os.path.basename(str(nome_arq or ""))
    m = re.match(r"^(\d{1,4})(?:_cena_|_bloco_|_|-|\.)", bn, re.I)
    if m:
        return int(m.group(1))
    m2 = re.search(r"(?:cena|scene|bloco)[_\-\s]*(\d{1,4})\b", bn, re.I)
    if m2:
        return int(m2.group(1))
    return 0


def obter_pasta_downloads_darkplanner():
    """Retorna `Downloads/DarkPlanner` no Windows (`C:\\Users\\leona\\Downloads\\DarkPlanner`)
    e, no Modo Remoto/Linux onde `~/Downloads` pode ser somente-leitura, usa `data/DarkPlannerDownloads`."""
    cand_padrao = os.path.join(os.path.expanduser("~"), "Downloads", "DarkPlanner")
    if os.name == "nt":
        if not os.path.isdir(cand_padrao) and os.path.isdir(r"C:\Users\leona\Downloads\DarkPlanner"):
            return r"C:\Users\leona\Downloads\DarkPlanner"
        return cand_padrao
    pasta_pai = os.path.dirname(cand_padrao)
