ARQUIVOS_DE_VIDEOS_PADRAO = r"D:\ARQUIVOS DE VIDEOS"


def _obter_pasta_arquivos_video(titulo="", criar=True):
    """Retorna e garante a pasta centralizada `D:\\ARQUIVOS DE VIDEOS\\<NOME DO VIDEO>` (Foto 2),
    onde ficam salvos de forma organizada TODOS os arquivos gerados do vídeo:
    - 00_ROTEIRO_LIMPO.txt
    - 01_CONSISTENCY_REFERENCES.txt
    - 02_FLOW_PROMPTS.txt
    - 03_DESCRICAO_E_TAGS.txt
    - 08_PROMPT_MESTRE_DO_CANAL.md (ou 08_MASTER_PROMPT_VIDEO_REAL_V8.md)
    - 09_PROMPT_EDICAO_STUDIO.txt e 09_INSTRUCOES_IA_DARKPLANNER.txt
    - 10_PLANO_SRT_PARA_MONTAGEM.json
    - <NOME_DO_VIDEO>_THUMB.png
    - <NOME_DO_VIDEO>.mp3
    - <NOME_DO_VIDEO>_srtsynctempo.srt (SOMENTE 1 SRT — o da quebra por frases!)
    - subpastas midias/ e referencias/"""
    nome_limpo = re.sub(r'[<>:"/\\|?*]', "", (titulo or "Novo Video DarkPlanner")).strip()[:65] or "Video_DarkPlanner"
    slug_pasta = re.sub(r"[^\w\- ]", "", nome_limpo).strip() or "Video_DarkPlanner"
    base_av = ARQUIVOS_DE_VIDEOS_PADRAO
    usar_d = (os.name == "nt") or os.path.exists("D:\\") or os.path.exists(base_av)
    if usar_d:
        try:
            p_alvo = os.path.join(base_av, slug_pasta)
            if criar:
                os.makedirs(os.path.join(p_alvo, "midias"), exist_ok=True)
                os.makedirs(os.path.join(p_alvo, "referencias"), exist_ok=True)
            return p_alvo
        except Exception:
            pass
    fb = os.path.join(storage.DATA_DIR, "ARQUIVOS_DE_VIDEOS", slug_pasta)
    if criar:
        os.makedirs(os.path.join(fb, "midias"), exist_ok=True)
        os.makedirs(os.path.join(fb, "referencias"), exist_ok=True)
    return fb


def _limpar_srts_extras_na_pasta(pasta, nome_srt_oficial=""):
    """Garante que na pasta do vídeo exista SOMENTE 1 único arquivo .SRT (o `_srtsynctempo.srt` da quebra por frases),
    removendo duplicatas como `09_NARRACAO_ORIGINAL.srt`, `legenda.srt`, `srtsyncpalavra.srt`, `legendas.srt`."""
    if not pasta or not os.path.isdir(pasta):
        return
    oficial_low = (os.path.basename(nome_srt_oficial) if nome_srt_oficial else "").lower()
    try:
        arqs_srt = [f for f in os.listdir(pasta) if f.lower().endswith(".srt")]
        if not oficial_low:
            cands_tempo = [f for f in arqs_srt if "srtsynctempo" in f.lower()]
            if cands_tempo:
                oficial_low = cands_tempo[0].lower()
        if oficial_low:
            for f in arqs_srt:
                if f.lower() != oficial_low:
                    try:
                        os.remove(os.path.join(pasta, f))
                    except Exception:
                        pass
    except Exception:
        pass


def _obter_override_chat_canal(canal_nome="", canal_id=""):
    """Retorna configurações customizadas definidas pelo usuário via Chat Vinculado ao DarkPlanner para o canal."""
    a1 = str(canal_nome or "").strip().lower()
    a2 = str(canal_id or "").strip().lower()
    if not a1 and not a2:
        return {}
    try:
        db = storage.load()
        for c in (db.get("channels") or []):
            cid_c = str(c.get("id") or "").strip().lower()
            cn_c = str(c.get("nome") or "").strip().lower()
            if (a2 and cid_c == a2) or (a1 and (cid_c == a1 or cn_c == a1)):
                return c
    except Exception:
        pass
    return {}


def _canal_eh_70_video_30_imagem(canal_nome="", canal_id=""):
    """Identifica canais que seguem a fórmula CapittoFin: 70% Vídeo ([flow][iv][16:9]) e 30% Imagem ([flow][i][16:9]):
    - CapittoFin
    - Cappito Vital
    - Ou qualquer canal configurado via Chat com `modo_midia_custom == '70v_30i'` / `proporcao_midia` 70/30."""
    ch_ov = _obter_override_chat_canal(canal_nome, canal_id)
    if ch_ov:
        modo_ov = str(ch_ov.get("modo_midia_custom") or "").strip().lower()
        prop_ov = ch_ov.get("proporcao_midia")
        if modo_ov in ("100_img", "video_real", "100_video_flow"):
            return False
        if modo_ov == "70v_30i":
            return True
        if isinstance(prop_ov, dict) and int(prop_ov.get("video_pct") or 0) == 70 and int(prop_ov.get("imagem_pct") or 0) == 30:
            return True
        if isinstance(prop_ov, dict) and "video_pct" in prop_ov and int(prop_ov.get("video_pct") or 0) != 70:
            return False
    a1 = str(canal_nome or "").strip().lower()
    a2 = str(canal_id or "").strip().lower()
    if a1 in CANAIS_70_VIDEO_30_IMAGEM_IDS or a2 in CANAIS_70_VIDEO_30_IMAGEM_IDS:
        return True
    comb = f"{a1} {a2}"
    if any(k in comb for k in ("capittofin", "capitto fin", "cappito vital", "capitto vital")):
        return True
    if ch_ov:
        cn_low = (ch_ov.get("nome") or "").strip().lower()
        if any(k in cn_low for k in ("capittofin", "capitto fin", "cappito vital", "capitto vital")):
            return True
    return False


