def _garantir_regra_100_imagem_no_prompt(texto_prompt, canal_nome="", n_blocos=0):
    """Garante que o prompt final dos canais 100% Imagem termine obrigatoriamente com a diretriz de 100% Imagem."""
    txt = (texto_prompt or "").rstrip()
    bloco = _bloco_obrigatorio_final_100_imagem(canal_nome=canal_nome, n_blocos=n_blocos)
    marcador = "REGRA OBRIGATÓRIA FINAL DO CANAL"
    if marcador in txt:
        idx_m = txt.find("==================================================================\n🚨 REGRA OBRIGATÓRIA FINAL DO CANAL")
        if idx_m != -1:
            txt = txt[:idx_m].rstrip()
    return txt + bloco + "\n"


