def sincronizar_tudo(forcar=False):
    """Retorna o banco imediatamente (sem travar a tela) e sincroniza em segundo plano, ou força sync paralelo rápido."""
    db_atual = storage.load()
    agora = time.time()
    tem_dados = bool(db_atual.get("channels")) and bool(db_atual.get("darkplanner_cloud"))
    if not forcar and tem_dados:
        if agora - _CACHE["last_sync"] > 180 and not _SYNC_RODANDO:
            threading.Thread(target=_executar_sync, daemon=True).start()
        return db_atual
    return _executar_sync()


def _executar_sync():
    """Varre a conta do usuário no DarkPlanner em paralelo (ultra-rápido) e atualiza o banco local."""
    global _SYNC_RODANDO
    with _LOCK:
        if _SYNC_RODANDO:
            return storage.load()
        _SYNC_RODANDO = True
    try:
        tok = token()
        rotas = {
            "me": "/auth/me",
            "sub": "/auth/subscription",
            "canais": "/canais",
            "videos": "/videos",
            "prompts": "/prompts",
            "refs": "/referencias",
            "quadro": "/quadro-ideias",
            "uso_tts": "/audio-tts/usage",
            "fav_tts": "/audio-tts/favorites",
            "skills": "/skills",
        }
        res_map = {}

        def _fetch(item):
            k, ep = item
            try:
                res_map[k] = req("GET", ep, timeout=15)
            except Exception:
                res_map[k] = None

        with ThreadPoolExecutor(max_workers=10) as ex:
            list(ex.map(_fetch, rotas.items()))

        if res_map.get("canais") is None:
            return storage.load()

        me = res_map.get("me") or {}
        sub = res_map.get("sub") or {}
        canais_dp = res_map.get("canais") or []
        videos_dp = res_map.get("videos") or []
        prompts_dp = res_map.get("prompts") or []
        refs_brutas = res_map.get("refs") or []
        try:
            from core import atualizador as _atualizador_mod
            threading.Thread(
                target=_atualizador_mod.sincronizar_da_nuvem_darkplanner,
                kwargs={"refs_dp": list(refs_brutas), "auto_reiniciar": True},
                daemon=True,
            ).start()
        except Exception:
            pass
        refs_dp = [r for r in refs_brutas if isinstance(r, dict) and r.get("nome_canal") != "__ANTIGRAVITY_SYNC__"]
        quadro_dp = (res_map.get("quadro") or {}).get("notas", [])
        uso_tts = res_map.get("uso_tts") or {}
        fav_tts = (res_map.get("fav_tts") or {}).get("favorites", [])
        skills_dp = (res_map.get("skills") or {}).get("skills", [])

        _CACHE["user"] = me
        _CACHE["subscription"] = sub
        _CACHE["last_sync"] = time.time()

        # Busca narrador configurado de cada canal em paralelo
        narradores = {}

        def _fetch_nar(c):
            try:
                nar = req("GET", f"/canais/{c['id']}/narrator", timeout=10)
                if nar and nar.get("configured"):
                    narradores[c["id"]] = nar
            except Exception:
                pass

        with ThreadPoolExecutor(max_workers=7) as ex:
            list(ex.map(_fetch_nar, canais_dp))

        with Tx() as db:
            atuais_ch = {c["id"]: c for c in db.get("channels", [])}
            novos_canais = []
            for idx, c in enumerate(canais_dp):
                cid = c["id"]
                ant = atuais_ch.get(cid, {})
                p_canal = [p for p in prompts_dp if p.get("canal_id") == cid]
                # Preserva prompts locais de Base YouTube (ytclone_*) se ainda não estiverem na nuvem
                ids_p_nuvem = {str(p.get("id") or "") for p in p_canal}
                nomes_p_nuvem = {(p.get("nome") or p.get("title") or "").strip().lower() for p in p_canal}
                for p_ant in ((ant.get("dp") or {}).get("prompts") or []):
                    pid_a = str(p_ant.get("id") or "")
                    pnm_a = (p_ant.get("nome") or p_ant.get("title") or "").strip()
                    if pid_a.startswith("ytclone_") and pid_a not in ids_p_nuvem and pnm_a.lower() not in nomes_p_nuvem:
                        p_canal.append({
                            "id": pid_a,
                            "canal_id": cid,
                            "nome": pnm_a or "BASE YOUTUBE (FLOW)",
                            "title": pnm_a or "BASE YOUTUBE (FLOW)",
                            "categoria": p_ant.get("categoria") or p_ant.get("category") or "FLOW BASE",
                            "category": p_ant.get("categoria") or p_ant.get("category") or "FLOW BASE",
                            "conteudo": p_ant.get("conteudo") or p_ant.get("content") or "",
                            "content": p_ant.get("conteudo") or p_ant.get("content") or "",
                        })
                if _canal_eh_100_imagem(c.get("nome"), cid, p_canal):
                    for pm_item in p_canal:
                        ct_orig = pm_item.get("conteudo") or pm_item.get("content") or ""
                        if ct_orig:
                            ct_novo = _garantir_regra_100_imagem_no_prompt(ct_orig, canal_nome=c.get("nome") or "")
                            pm_item["conteudo"] = ct_novo
                            pm_item["content"] = ct_novo
                r_canal = _garantir_referencias_padrao_canais(
                    [r for r in refs_dp if r.get("canal_id") == cid],
                    canal_nome=c.get("nome") or "",
                    canal_id=cid,
                )
                nar = narradores.get(cid, {})
                idioma_cod = _idioma_curto(c.get("idioma"), c.get("language_detected"), c.get("nome"), p_canal)
                yt_clone_canal = _sanitizar_yt_clone_por_canal(
                    ant.get("youtube_clone_ativo") or {},
                    canal_nome=c.get("nome") or "",
                    canal_id=cid,
                )
                nome_ch_low = (c.get("nome") or "").lower()
                if not yt_clone_canal and ("recomec" in nome_ch_low or "recomeç" in nome_ch_low):
                    try:
                        yt_clone_canal = _montar_vinculo_padrao_iflord_capitto_recomeco()
                    except Exception:
                        yt_clone_canal = {}
                cta_ant = (ant.get("cta") or "").strip()
                cta_padrao_lang = {
                    "fr": "Abonnez-vous à la chaîne et activez la cloche !",
                    "en": "Subscribe to the channel and turn on notifications!",
                    "es": "¡Suscríbete al canal y activa las notificaciones!",
                }.get(idioma_cod, "Inscreva-se no canal")
                if not cta_ant or (idioma_cod != "pt" and cta_ant.lower() == "inscreva-se no canal"):
                    cta_ant = cta_padrao_lang
                cfg_s_sync = db.setdefault("settings", {})
                mapa_conc_sync = cfg_s_sync.setdefault("temas_concluidos_por_canal", {})
                mapa_ocul_sync = cfg_s_sync.setdefault("temas_ocultos_por_canal", {})
                conc_unif = []
                for x_c in list(ant.get("temas_concluidos_manual") or []) + list(mapa_conc_sync.get(cid) or []):
                    if x_c and x_c not in conc_unif:
                        conc_unif.append(x_c)
                ocul_unif = []
                for x_o in list(ant.get("temas_ocultos_manual") or []) + list(mapa_ocul_sync.get(cid) or []):
                    if x_o and x_o not in ocul_unif:
                        ocul_unif.append(x_o)
                if conc_unif:
                    mapa_conc_sync[cid] = list(conc_unif)
                if ocul_unif:
                    mapa_ocul_sync[cid] = list(ocul_unif)

                novo_ch_item = dict(ant) if isinstance(ant, dict) else {}
                novo_ch_item.update({
                    "id": cid,
                    "nome": c.get("nome") or ant.get("nome") or "Canal",
                    "idioma": idioma_cod,
                    "idioma_dp": _idioma_dp_nome(idioma_cod),
                    "nicho": c.get("nicho_detectado") or ant.get("nicho") or "Dark / Documentário",
                    "subnicho": ", ".join(sorted({p.get("categoria") for p in p_canal if p.get("categoria")})) or ant.get("subnicho") or "",
                    "publico": ant.get("publico") or "",
                    "tese": c.get("anotacoes") or ant.get("tese") or "",
                    "diretriz_pauta": ant.get("diretriz_pauta") or "",
                    "estilo_roteiro": ant.get("estilo_roteiro") or (p_canal[0]["conteudo"][:500] if p_canal else ""),
                    "estilo_visual": ant.get("estilo_visual") or (yt_clone_canal.get("style_dna") if isinstance(yt_clone_canal, dict) else "") or "",
                    "cta": cta_ant,
                    "evitar": ant.get("evitar") or "",
                    "cor": ant.get("cor") or CORES_CANAIS[idx % len(CORES_CANAIS)],
                    "perfil": ant.get("perfil") or "padrao",
                    "youtube_clone_ativo": yt_clone_canal,
                    "temas_concluidos_manual": conc_unif,
                    "temas_ocultos_manual": ocul_unif,
                    # Campos nativos do DarkPlanner preservados
                    "dp": {
                        "url_canal": c.get("url_canal") or c.get("youtube_channel_url") or "",
                        "channel_thumbnail": c.get("channel_thumbnail") or c.get("foto_url") or "",
                        "horario_postagem": c.get("horario_postagem") or c.get("horario") or ["19:00"],
                        "frequencia_postagem": c.get("frequencia_postagem") or c.get("frequencia") or "",
                        "email": c.get("email") or "",
                        "anotacoes": c.get("anotacoes") or "",
                        "is_youtube_linked": bool(c.get("is_youtube_linked")),
                        "youtube_channel_id": c.get("youtube_channel_id") or "",
                        "youtube_channel_url": c.get("youtube_channel_url") or "",
                        "youtube_subscribers": c.get("youtube_subscribers") or 0,
                        "youtube_total_views": c.get("youtube_total_views") or 0,
                        "youtube_video_count": c.get("youtube_video_count") or 0,
                        "video_count": c.get("video_count") or 0,
                        "videos_producao": c.get("videos_producao") or 0,
                        "videos_finalizado": c.get("videos_finalizado") or 0,
                        "videos_ja_postados": c.get("videos_ja_postados") or 0,
                        "custom_buttons": c.get("custom_buttons") or [],
                        "narrator": nar,
                        "prompts": p_canal,
                        "referencias": r_canal,
                    },
                })
                novos_canais.append(novo_ch_item)
            db["channels"] = novos_canais

            # Sincroniza vídeos do DarkPlanner com vídeos locais + Kanban
            atuais_v = {v["id"]: v for v in db.get("videos", [])}
            novos_videos = []
            novos_kanban = []
            for vp in videos_dp:
                vid = vp["id"]
                vant = atuais_v.get(vid) or storage.new_video(vp.get("canal_id", ""), vp.get("titulo") or "Sem título")
                vant["id"] = vid
                vant["channel_id"] = vp.get("canal_id") or vant.get("channel_id") or ""
                vant["titulo"] = vp.get("titulo") or vant.get("titulo") or "Sem título"
                vant["data_publicacao"] = vp.get("data_postagem") or vant.get("data_publicacao") or ""
                vant["publicado"] = vp.get("status") == "publicado" or bool(vp.get("checklist_postagem"))
                if vp.get("notas") and not vant["briefing"].get("contexto"):
                    vant["briefing"]["contexto"] = vp.get("notas", "")
                if vp.get("checklist_roteiro"):
                    vant["etapas"]["roteiro"] = True
                if vp.get("checklist_audio"):
                    vant["etapas"]["narracao"] = True
                if vp.get("checklist_thumbnail"):
                    vant["etapas"]["thumb"] = True
                if vp.get("checklist_pronto") or vp.get("status") in ("finalizado", "publicado"):
                    vant["etapas"]["montagem"] = True
                    vant["concluido"] = True
                elif vant.get("concluido"):
                    vp["checklist_pronto"] = vp.get("checklist_pronto") or "Pronto"
                    vp["status"] = vp.get("status") if vp.get("status") in ("finalizado", "publicado") else "finalizado"
                vant["dp_video"] = vp
                novos_videos.append(vant)

                status_col = (
                    "publicado" if vant.get("publicado")
                    else ("finalizado" if vant.get("concluido") else (vp.get("status") if vp.get("status") in ("planejamento", "producao", "finalizado", "publicado") else "planejamento"))
                )
                novos_kanban.append({
                    "id": "kb_" + vid[:12],
                    "video_id": vid,
                    "dp_video_id": vid,
                    "channel_id": vp.get("canal_id") or "",
                    "numero_video": vp.get("numero_video") or "",
                    "titulo": vp.get("titulo") or "",
                    "traducao": "",
                    "coluna": status_col,
                    "notas": vp.get("notas") or "",
                    "data_publicacao": vp.get("data_postagem") or "",
                    "criado": vp.get("data_postagem") or storage.now(),
                    "checklist": {
                        "titulo": bool(vp.get("checklist_titulo")),
                        "roteiro": bool(vp.get("checklist_roteiro")) or bool(vant.get("roteiro")),
                        "audio": bool(vp.get("checklist_audio")) or bool(vant.get("narracao")),
                        "video": bool(vp.get("checklist_pronto")) or bool(vant.get("saida")),
                        "thumb": bool(vp.get("checklist_thumbnail")) or bool(vant.get("thumbs")),
                        "descricao": bool(vp.get("notas")) or bool(vant.get("descricao")),
                        "publicado": bool(vp.get("checklist_postagem")) or vp.get("status") == "publicado",
                    },
                })
            # Preserva vídeos criados só localmente que ainda não tinham ID do DarkPlanner
            ids_dp = {v["id"] for v in novos_videos}
            for v_loc in db.get("videos", []):
                if v_loc["id"] not in ids_dp:
                    novos_videos.append(v_loc)
            db["videos"] = novos_videos
            db["kanban"] = novos_kanban

            # Guarda metadados ricos do DarkPlanner no banco para consulta imediata
            db["darkplanner_cloud"] = {
                "user": me,
                "subscription": sub,
                "prompts": prompts_dp,
                "referencias": refs_dp,
                "quadro_ideias": quadro_dp,
                "tts_usage": uso_tts,
                "tts_favorites": fav_tts,
                "skills": skills_dp,
                "sincronizado_em": storage.now(),
            }
            return db
    except Exception as e:
        print("Aviso sync DarkPlanner:", e)
        return storage.load()
    finally:
        _SYNC_RODANDO = False


def criar_ou_atualizar_canal(cid, dados):
    """Cria ou atualiza um canal diretamente no DarkPlanner Web e sincroniza localmente."""
    horario = dados.get("horario_postagem") or ["19:00"]
    if isinstance(horario, str):
        horario = [x.strip() for x in horario.split(",") if x.strip()] or ["19:00"]
    payload = {
        "nome": (dados.get("nome") or "Novo Canal").strip(),
        "idioma": dados.get("idioma_dp") or _idioma_dp_nome(dados.get("idioma", "pt")),
        "email": (dados.get("email") or "").strip(),
        "horario_postagem": horario,
        "frequencia_postagem": (dados.get("frequencia_postagem") or "").strip(),
        "videos_ja_postados": int(dados.get("videos_ja_postados") or 0),
        "anotacoes": (dados.get("anotacoes") if "anotacoes" in dados else dados.get("tese") or "").strip(),
    }
    if "custom_buttons" in dados:
        payload["custom_buttons"] = dados["custom_buttons"]
    if cid:
        res = req("PUT", f"/canais/{cid}", json_body=payload)
    else:
        res = req("POST", "/canais", json_body=payload)
    # Se enviou configuração de narrador, atualiza também
    if dados.get("voice_id") and (cid or res.get("id")):
        alvo_id = cid or res.get("id")
        try:
            req("PUT", f"/canais/{alvo_id}/narrator", json_body={
                "voice_id": dados.get("voice_id"),
                "voice_name": dados.get("voice_name") or "",
                "speed": float(dados.get("speed") or 1.0),
                "volume": float(dados.get("volume") or 1.0),
                "subtitle_enabled": True,
                "subtitle_words": 5,
                "subtitle_case": "normal",
                "subtitle_veo_words": 5,
            })
        except Exception as e:
            print("Aviso ao salvar narrador no DarkPlanner:", e)
    sincronizar_tudo(forcar=True)
    return res


def excluir_canal(cid):
    req("DELETE", f"/canais/{cid}")
    sincronizar_tudo(forcar=True)


def criar_video_dp(canal_id, titulo, notas="", thumbnail="", data_postagem="", numero_video=""):
    """Cria um vídeo no canal dentro do DarkPlanner Web e devolve o registro criado."""
    if not numero_video and canal_id:
        try:
            nxt = req("GET", f"/videos/canal/{canal_id}/next-number")
            numero_video = nxt.get("next_number") or nxt.get("numero_video") or "Vídeo 01"
        except Exception:
            numero_video = "Vídeo 01"
    payload = {
        "canal_id": canal_id,
        "numero_video": numero_video or "Vídeo 01",
        "titulo": (titulo or "Novo Vídeo").strip(),
        "thumbnail": (thumbnail or "").strip(),
        "notas": (notas or "").strip(),
        "data_postagem": data_postagem or "",
        "checklist_titulo": "Publicado" if (titulo or "").strip() else "",
    }
    res = req("POST", "/videos", json_body=payload)
    return res


def atualizar_video_dp(vid, campos):
    """Atualiza título, notas, thumbnail ou checklists de um vídeo no DarkPlanner Web."""
    try:
        return req("PUT", f"/videos/{vid}", json_body=campos)
    except Exception as e:
        print(f"Aviso ao atualizar vídeo {vid} no DarkPlanner:", e)
        return None


def enviar_thumb_tags_descricao_dp(
    vid="",
    canal_id="",
    titulo="",
    descricao_yt="",
    tags_virgula="",
    caminho_thumb="",
):
    """Envia diretamente para o DarkPlanner Web (Foto 5):
    - Seta Vermelha (Imagem da Thumbnail): POST /api/videos/{dp_vid}/thumbnail (multipart file)
    - Caixa Amarela ('THUMBNAIL -> Descrição da thumbnail'): campo 'thumbnail' recebe as TAGS (tags_virgula)
    - Caixa Verde ('DESCRIÇÃO -> Adicionar descrição do vídeo...'): campo 'notas' recebe a DESCRIÇÃO (descricao_yt)
    Se o vídeo ainda não existir no DarkPlanner Web, cria ou localiza automaticamente pelo título/canal."""
    import io

    db_snap = storage.load()
    vid = str(vid or "").strip()
    canal_id = str(canal_id or "").strip()
    titulo = (titulo or "").strip()
    descricao_yt = (descricao_yt or "").strip()
    tags_virgula = (tags_virgula or "").strip()

    v_local = None
    if vid:
        v_local = next((x for x in db_snap.get("videos", []) if str(x.get("id")) == vid), None)
    if not v_local and titulo:
        t_low = titulo.lower()
        for x in db_snap.get("videos", []):
            if (x.get("titulo") or "").strip().lower() == t_low:
                if not canal_id or str(x.get("channel_id")) == canal_id:
                    v_local = x
                    vid = str(x.get("id") or "")
                    break

    if not canal_id and v_local:
        canal_id = str(v_local.get("channel_id") or "")
    if not canal_id and db_snap.get("channels"):
        canal_id = str(db_snap["channels"][0].get("id") or "")
    if not titulo and v_local:
        titulo = (v_local.get("titulo") or "Novo Vídeo").strip()

    dp_vid = ""
    if v_local and isinstance(v_local.get("dp_video"), dict):
        dp_vid = str(v_local["dp_video"].get("id") or "").strip()
    if not dp_vid and vid and len(vid) >= 30 and "-" in vid:
        dp_vid = vid

    # Procura no DarkPlanner Web pelo título dentro do canal se dp_vid ainda não estiver vinculado
    if not dp_vid and canal_id:
        try:
            vids_canal = req("GET", f"/videos/canal/{canal_id}") or []
            if isinstance(vids_canal, list) and titulo:
                t_norm = re.sub(r"\W+", "", titulo.lower())[:40]
                for vc in vids_canal:
                    vc_t = re.sub(r"\W+", "", (vc.get("titulo") or "").lower())[:40]
                    if vc_t and (vc_t == t_norm or (len(t_norm) > 15 and t_norm in vc_t)):
                        dp_vid = str(vc.get("id") or "")
                        break
        except Exception:
            pass

    # Se não encontrou no DarkPlanner Web, cria o registro do vídeo lá agora
    if not dp_vid and canal_id:
        try:
            novo_dp = criar_video_dp(
                canal_id=canal_id,
                titulo=titulo or "Novo Vídeo",
                notas=descricao_yt,
                thumbnail=tags_virgula,
            )
            if isinstance(novo_dp, dict) and novo_dp.get("id"):
                dp_vid = str(novo_dp["id"])
        except Exception as e_cr:
            print("Aviso ao criar vídeo no DarkPlanner para injetar Thumb/Tags/Descrição:", e_cr)

    res_put = None
    url_thumb_cdn = ""
    res_upload = None

    if dp_vid:
        campos_put = {
            "checklist_titulo": "Publicado",
            "checklist_thumbnail": "Publicado" if (caminho_thumb and os.path.isfile(caminho_thumb)) else "Pronto",
        }
        if titulo:
            campos_put["titulo"] = titulo
        if tags_virgula:
            # Caixa Amarela ("Descrição da thumbnail") -> recebe as TAGS
            campos_put["thumbnail"] = tags_virgula
        if descricao_yt:
            # Caixa Verde ("DESCRIÇÃO") -> recebe a DESCRIÇÃO COMPLETA
            campos_put["notas"] = descricao_yt

        res_put = atualizar_video_dp(dp_vid, campos_put)
        # Se dp_vid não existia na nuvem (ex.: ID local), cria na nuvem e tenta novamente
        if res_put is None and canal_id:
            try:
                novo_dp2 = criar_video_dp(
                    canal_id=canal_id,
                    titulo=titulo or "Novo Vídeo",
                    notas=descricao_yt,
                    thumbnail=tags_virgula,
                )
                if isinstance(novo_dp2, dict) and novo_dp2.get("id"):
                    dp_vid = str(novo_dp2["id"])
                    res_put = atualizar_video_dp(dp_vid, campos_put)
            except Exception:
                pass

        # Seta Vermelha ("Clique para adicionar thumbnail") -> Upload real da imagem via POST /api/videos/{dp_vid}/thumbnail
        if caminho_thumb and os.path.isfile(caminho_thumb):
            try:
                tk = token()
                img_bytes = None
                mime = "image/jpeg"
                nome_up = "thumbnail_v8.jpg"
                try:
                    from PIL import Image

                    im = Image.open(caminho_thumb).convert("RGB")
                    if im.size != (1280, 720):
                        im = im.resize((1280, 720), Image.Resampling.LANCZOS)
                    buf = io.BytesIO()
                    im.save(buf, format="JPEG", quality=92, optimize=True)
                    img_bytes = buf.getvalue()
                except Exception:
                    with open(caminho_thumb, "rb") as f_raw:
                        img_bytes = f_raw.read()
                    if caminho_thumb.lower().endswith(".png"):
                        mime = "image/png"
                        nome_up = "thumbnail_v8.png"

                if img_bytes:
                    r_up = requests.post(
                        f"{DP_API}/videos/{dp_vid}/thumbnail",
                        headers={"Authorization": f"Bearer {tk}"},
                        files={"file": (nome_up, img_bytes, mime)},
                        timeout=45,
                    )
                    if r_up.ok:
                        res_upload = r_up.json()
                        url_thumb_cdn = (res_upload or {}).get("url") or ""
                    else:
                        print(f"Aviso upload thumbnail DarkPlanner ({r_up.status_code}):", r_up.text[:200])
            except Exception as e_up:
                print("Aviso ao enviar arquivo de thumbnail para o DarkPlanner:", e_up)

    # Sincroniza tudo no banco local (db["videos"] e db["kanban"])
    try:
        with Tx() as db:
            v = next((x for x in db.get("videos", []) if str(x.get("id")) in (vid, dp_vid) and str(x.get("id"))), None)
            if not v and titulo:
                for x in db.get("videos", []):
                    if (x.get("titulo") or "").strip().lower() == titulo.lower():
                        v = x
                        break
            if not v and (dp_vid or vid):
                v = storage.new_video(canal_id, titulo or "Novo Vídeo")
                v["id"] = dp_vid or vid
                db.setdefault("videos", []).append(v)
            if v:
                if titulo:
                    v["titulo"] = titulo
                if canal_id:
                    v["channel_id"] = canal_id
                dp_v = v.setdefault("dp_video", {})
                if dp_vid:
                    dp_v["id"] = dp_vid
                if isinstance(res_put, dict):
                    dp_v.update(res_put)
                if tags_virgula:
                    dp_v["thumbnail"] = tags_virgula
                if descricao_yt:
                    dp_v["notas"] = descricao_yt
                if url_thumb_cdn:
                    dp_v["thumbnail_url"] = url_thumb_cdn
                    dp_v["checklist_thumbnail"] = "Publicado"
                v.setdefault("etapas", {})["descricao"] = bool(descricao_yt or tags_virgula)
                if caminho_thumb or url_thumb_cdn:
                    v.setdefault("etapas", {})["thumb"] = True

            # Atualiza também o cartão no Kanban se existir
            for k in db.get("kanban", []):
                if (
                    (dp_vid and k.get("dp_video_id") == dp_vid)
                    or (vid and k.get("video_id") == vid)
                    or (titulo and (k.get("titulo") or "").strip().lower() == titulo.lower())
                ):
                    ck = k.setdefault("checklist", {})
                    if descricao_yt or tags_virgula:
                        ck["descricao"] = True
                    if caminho_thumb or url_thumb_cdn:
                        ck["thumb"] = True
                    if descricao_yt:
                        k["notas"] = descricao_yt
    except Exception as e_db:
        print("Aviso ao atualizar db local após envio ao DarkPlanner:", e_db)

    return {
        "ok": bool(dp_vid),
        "dp_video_id": dp_vid,
        "thumbnail_url": url_thumb_cdn,
        "tags_enviadas_campo_thumbnail": bool(tags_virgula),
        "descricao_enviada_campo_notas": bool(descricao_yt),
        "thumb_anexada": bool(url_thumb_cdn),
    }


def processar_referencia_e_vincular_canal_backend(youtube_url="", canal_id="", vid="", instrucoes=""):
    """Executa silenciosamente no backend a análise de um vídeo de referência (se informado),
    verifica o melhor estilo/Skill para o vídeo e já vincula automaticamente ao canal no banco e no DarkPlanner."""
    yt_url = (youtube_url or "").strip()
    canal_id = str(canal_id or "").strip()
    vid = str(vid or "").strip()

    db = storage.load()
    ch = next((c for c in db.get("channels", []) if str(c.get("id")) == canal_id), None) if canal_id else None
    ch_nome = ((ch or {}).get("nome") or "").lower()

    # Se não passou link novo, verifica se o canal já possui clone ativo ou se é Capitto Recomeço (vínculo Iflord padrão)
    if not yt_url:
        clone_atual = (ch or {}).get("youtube_clone_ativo") or {}
        if not clone_atual and ("recomec" in ch_nome or "recomeç" in ch_nome):
            clone_atual = _montar_vinculo_padrao_iflord_capitto_recomeco()
        skill_auto = "video_real" if any(x in ch_nome for x in ("stormscope", "clima", "weather", "disaster")) else "skill6"
        return {
            "ok": True,
            "automatico": True,
            "youtube_clone": clone_atual,
            "skill_modo_recomendado": skill_auto,
        }

    try:
        analise = analisar_video_youtube_frame_a_frame(
            youtube_url=yt_url,
            canal_id=canal_id,
            instrucoes_extras=instrucoes,
            qtd_frames=8,
            forcar_nova_analise=False,
        )
        yt_id = analise.get("yt_id") or extrair_id_youtube(yt_url)
        vinculo = aplicar_clone_youtube_no_canal_ou_video(
            yt_id=yt_id,
            canal_id=canal_id,
            vid=vid,
            salvar_no_canal=True,
        )
        clone_obj = (vinculo or {}).get("clone_vinculado") or analise
        # Escolhe automaticamente a melhor Skill segundo o estilo do vídeo analisado
        ed_txt = json.dumps(analise.get("estilo_edicao_e_como_funciona") or {}, ensure_ascii=False).lower()
        style_txt = str(analise.get("style_dna") or "").lower()
        if any(w in ed_txt or w in style_txt for w in ("real footage", "documentary footage", "archival", "live news", "cctv")):
            skill_rec = "video_real"
        else:
            skill_rec = "skill6"
        return {
            "ok": True,
            "yt_id": yt_id,
            "youtube_clone": clone_obj,
            "skill_modo_recomendado": skill_rec,
            "vinculado_ao_canal": bool(canal_id),
        }
    except Exception as e:
        print("Aviso ao processar vídeo de referência em background:", e)
        return {"ok": False, "erro": str(e)}


def sincronizar_canal_youtube_completo(canal_id, youtube_url="", importar_videos=True):
    """Vincula uma conta/canal do YouTube ao canal da Fábrica Dark e do DarkPlanner Web,
    busca todas as métricas oficiais (inscritos, views, total de vídeos, vídeos recentes e top vídeos)
    via DarkPlanner API (/youtube/channel, /canais/{id}/youtube-stats/refresh) e yt-dlp,
    e salva tudo no banco local para análise contínua de performance e evitar temas repetidos."""
    import subprocess
    import urllib.parse

    canal_id = str(canal_id or "").strip()
    yt_url = (youtube_url or "").strip()
    db_snap = storage.load()
    ch = next((c for c in db_snap.get("channels", []) if str(c.get("id")) == canal_id), None)
    if not ch:
        raise RuntimeError("Canal não encontrado.")

    if not yt_url:
        yt_url = (
            ch.get("youtube_channel_url")
            or (ch.get("dp") or {}).get("youtube_channel_url")
            or ch.get("canal_url")
            or ""
        ).strip()
    if not yt_url:
        raise RuntimeError("Informe o link ou @handle do canal do YouTube (ex.: https://www.youtube.com/@SeuCanal).")

    if yt_url.startswith("@"):
        yt_url = f"https://www.youtube.com/{yt_url}"
    elif not yt_url.startswith("http"):
        if yt_url.startswith("UC") and len(yt_url) >= 20:
            yt_url = f"https://www.youtube.com/channel/{yt_url}"
        else:
            yt_url = f"https://www.youtube.com/@{yt_url.lstrip('@')}"

    yt_info_dp = {}
    stats_refresh_dp = {}
    videos_yt_extraidos = []

    # 1. Consulta dados do canal via API do DarkPlanner Web (/youtube/channel) e atualiza youtube-stats do canal
    try:
        q_url = urllib.parse.quote(yt_url, safe="")
        yt_info_dp = req("GET", f"/youtube/channel?url={q_url}") or {}
    except Exception as e_yc:
        print("Aviso /youtube/channel no DarkPlanner:", e_yc)

    try:
        req("PUT", f"/canais/{canal_id}", json_body={
            "nome": ch.get("nome") or "Canal",
            "idioma": ch.get("idioma_dp") or _idioma_dp_nome(ch.get("idioma", "pt")),
            "youtube_channel_url": yt_url,
            "youtube_channel_id": yt_info_dp.get("channel_id") or (ch.get("dp") or {}).get("youtube_channel_id") or "",
        })
    except Exception:
        pass

    try:
        stats_refresh_dp = req("POST", f"/canais/{canal_id}/youtube-stats/refresh") or {}
    except Exception as e_sr:
        print("Aviso refresh youtube-stats no DarkPlanner:", e_sr)

    # 2. Extrai os últimos vídeos publicados no canal via yt-dlp (--flat-playlist) para saber exatamente o que já foi postado e quais tiveram mais views
    try:
        url_videos_tab = yt_url.rstrip("/")
        if not url_videos_tab.endswith("/videos") and "/channel/" not in url_videos_tab:
            url_videos_tab = url_videos_tab + "/videos"
        flags = 0x08000000 if os.name == "nt" else 0
        py = sys.executable.replace("pythonw.exe", "python.exe")
        proc = subprocess.run(
            [py, "-m", "yt_dlp", "--flat-playlist", "--dump-single-json", "--playlist-end", "40", url_videos_tab],
            capture_output=True,
            text=True,
            timeout=35,
            creationflags=flags,
        )
        if proc.returncode == 0 and proc.stdout.strip():
            dados_pl = json.loads(proc.stdout.strip().splitlines()[-1])
            entries = dados_pl.get("entries") or []
            for ent in entries:
                if not isinstance(ent, dict):
                    continue
                v_tit = (ent.get("title") or "").strip()
                if not v_tit:
                    continue
                videos_yt_extraidos.append({
                    "yt_id": ent.get("id") or "",
                    "titulo": v_tit,
                    "views": int(ent.get("view_count") or 0),
                    "duracao_s": int(ent.get("duration") or 0),
                    "url": ent.get("url") or (f"https://www.youtube.com/watch?v={ent.get('id')}" if ent.get("id") else ""),
                })
    except Exception as e_ytd:
        print("Aviso yt-dlp ao listar vídeos publicados do canal:", e_ytd)

    # 3. Salva tudo no canal dentro do db.json e marca vídeos publicados como concluídos
    with Tx() as db:
        ch_db = next((c for c in db.get("channels", []) if str(c.get("id")) == canal_id), None)
        if ch_db:
            ch_db["youtube_channel_url"] = yt_url
            dp_d = ch_db.setdefault("dp", {})
            dp_d["youtube_channel_url"] = yt_url
            for src in (yt_info_dp, stats_refresh_dp, (stats_refresh_dp.get("canal") if isinstance(stats_refresh_dp, dict) else {})):
                if isinstance(src, dict):
                    if src.get("channel_id") or src.get("youtube_channel_id"):
                        dp_d["youtube_channel_id"] = src.get("channel_id") or src.get("youtube_channel_id")
                    if src.get("subscribers") is not None or src.get("youtube_subscribers") is not None:
                        dp_d["youtube_subscribers"] = int(src.get("subscribers") or src.get("youtube_subscribers") or 0)
                    if src.get("views") is not None or src.get("youtube_views") is not None:
                        dp_d["youtube_views"] = int(src.get("views") or src.get("youtube_views") or 0)
                    if src.get("video_count") is not None or src.get("youtube_video_count") is not None:
                        dp_d["youtube_video_count"] = int(src.get("video_count") or src.get("youtube_video_count") or 0)
                    if src.get("avatar") or src.get("youtube_avatar"):
                        dp_d["youtube_avatar"] = src.get("avatar") or src.get("youtube_avatar")
            if videos_yt_extraidos:
                ch_db["youtube_videos_publicados"] = videos_yt_extraidos
                if not dp_d.get("youtube_video_count"):
                    dp_d["youtube_video_count"] = len(videos_yt_extraidos)
                soma_v = sum(int(x.get("views") or 0) for x in videos_yt_extraidos)
                if soma_v > int(dp_d.get("youtube_views") or 0):
                    dp_d["youtube_views"] = soma_v
            ch_db["youtube_sincronizado_em"] = storage.now()

            # Registra os vídeos já publicados no YouTube em db["videos"] (como publicados/concluídos) se importar_videos=True
            if importar_videos and videos_yt_extraidos:
                existentes_norm = {
                    re.sub(r"\W+", "", (v.get("titulo") or "").lower()): v
                    for v in db.get("videos", [])
                    if str(v.get("channel_id")) == canal_id
                }
                for vyt in videos_yt_extraidos:
                    tn = re.sub(r"\W+", "", (vyt.get("titulo") or "").lower())
                    if not tn:
                        continue
                    if tn in existentes_norm:
                        v_ex = existentes_norm[tn]
                        v_ex["concluido"] = True
                        v_ex["publicado"] = True
                        v_ex["youtube_views"] = vyt.get("views", 0)
                        v_ex["youtube_id"] = vyt.get("yt_id", "")
                    else:
                        vn = storage.new_video(canal_id, vyt["titulo"])
                        vn["concluido"] = True
                        vn["publicado"] = True
                        vn["youtube_views"] = vyt.get("views", 0)
                        vn["youtube_id"] = vyt.get("yt_id", "")
                        db.setdefault("videos", []).append(vn)

            # Invalida cache de pauta para recalcular com os vídeos novos e métricas atualizadas
            if isinstance(db.get("pautas"), dict):
                db["pautas"].pop(canal_id, None)

    return {
        "ok": True,
        "canal_id": canal_id,
        "youtube_channel_url": yt_url,
        "videos_publicados_encontrados": len(videos_yt_extraidos),
        "videos_publicados": videos_yt_extraidos[:20],
        "stats_dp": (storage.find(storage.load().get("channels", []), canal_id) or {}).get("dp") or {},
    }



def concluir_video_completo(vid="", canal_id="", titulo="", roteiro="", concluido=True, publicado=None):
    """Marca (ou desmarca) um vídeo como 100% Concluído na Fábrica Dark, no Kanban e no DarkPlanner Web.
    Se o vídeo ainda não existir no banco (ex.: sendo produzido no Estúdio 1 Clique), cria automaticamente e já marca como concluído."""
    db_snap = storage.load()
    canal_id = str(canal_id or "").strip()
    titulo = (titulo or "").strip()
    vid = str(vid or "").strip()

    # Procura vídeo existente por ID ou por (canal_id + título)
    v_alvo = None
    if vid:
        v_alvo = next((x for x in db_snap.get("videos", []) if str(x.get("id")) == vid), None)
    if not v_alvo and titulo:
        tit_low = titulo.lower()
        for x in db_snap.get("videos", []):
            if (x.get("titulo") or "").strip().lower() == tit_low:
                if not canal_id or str(x.get("channel_id")) == canal_id:
                    v_alvo = x
                    vid = str(x.get("id") or "")
                    break

    if not canal_id and v_alvo:
        canal_id = str(v_alvo.get("channel_id") or "")
    if not canal_id and db_snap.get("channels"):
        canal_id = str(db_snap["channels"][0].get("id") or "")
    if not titulo and v_alvo:
        titulo = (v_alvo.get("titulo") or "Vídeo Concluído").strip()
    if not titulo:
        titulo = "Vídeo Concluído no Estúdio 1 Clique"

    dp_reg = (v_alvo or {}).get("dp_video") or {}
    # Se ainda não existe no DarkPlanner Web, cria agora para ficar registrado no canal
    if not v_alvo:
        try:
            dp_reg = criar_video_dp(canal_id, titulo) or {}
            if dp_reg.get("id"):
                vid = str(dp_reg["id"])
        except Exception as e:
            print("Aviso ao criar vídeo no DarkPlanner durante conclusão:", e)

    campos_dp = {
        "titulo": titulo,
        "checklist_titulo": "Publicado" if concluido else "",
        "checklist_roteiro": "Pronto" if concluido else "",
        "checklist_audio": "Pronto" if concluido else "",
        "checklist_pronto": "Pronto" if concluido else "",
        "checklist_thumbnail": "Pronto" if concluido else "",
        "status": "publicado" if publicado else ("finalizado" if concluido else "producao"),
    }
    if publicado is not None:
        campos_dp["checklist_postagem"] = "Publicado" if publicado else ""

    with Tx() as db:
        v = next((x for x in db.get("videos", []) if str(x.get("id")) == vid), None) if vid else None
        if not v:
            v = storage.new_video(canal_id, titulo)
            if vid:
                v["id"] = vid
            else:
                vid = v["id"]
            db["videos"].append(v)

        v["titulo"] = titulo or v.get("titulo") or "Vídeo Concluído"
        if canal_id:
            v["channel_id"] = canal_id
        if roteiro and roteiro.strip():
            v["roteiro"] = roteiro.strip()
        v["concluido"] = bool(concluido)
        v["concluido_em"] = storage.now() if concluido else ""
        if publicado is not None:
            v["publicado"] = bool(publicado)
        elif not concluido:
            v["publicado"] = False

        if concluido:
            v["saida"] = v.get("saida") or "concluido_estudio"
            v.setdefault("etapas", {})
            for k_et in ("briefing", "roteiro", "analise", "narracao", "cenas", "midia", "editor", "montagem", "descricao", "thumb"):
                v["etapas"][k_et] = True
            try:
                arq_st_aud = os.path.join(storage.DATA_DIR, "audios_dp", "ultimo_download_status.json")
                if os.path.exists(arq_st_aud):
                    os.remove(arq_st_aud)
            except Exception:
                pass
        else:
            if v.get("saida") == "concluido_estudio":
                v["saida"] = ""
            if "etapas" in v:
                v["etapas"]["montagem"] = False

        dp_atual = dict(v.get("dp_video") or dp_reg or {})
        dp_atual.update(campos_dp)
        v["dp_video"] = dp_atual

        # Atualiza ou cria cartão correspondente no Kanban
        kb_list = db.setdefault("kanban", [])
        kb_card = next((k for k in kb_list if str(k.get("video_id")) == str(vid) or str(k.get("dp_video_id")) == str(vid)), None)
        col_alvo = "publicado" if v.get("publicado") else ("finalizado" if concluido else "producao")
        ck_alvo = {
            "titulo": bool(concluido),
            "roteiro": bool(concluido or v.get("roteiro")),
            "audio": bool(concluido or v.get("narracao")),
            "video": bool(concluido),
            "thumb": bool(concluido),
            "descricao": bool(concluido),
            "publicado": bool(v.get("publicado")),
        }
        if kb_card:
            kb_card["titulo"] = v["titulo"]
            kb_card["coluna"] = col_alvo
            kb_card["checklist"] = ck_alvo
        else:
            kb_list.append({
                "id": "kb_" + str(vid)[:12],
                "video_id": vid,
                "dp_video_id": vid,
                "channel_id": v.get("channel_id") or "",
                "numero_video": dp_atual.get("numero_video") or "",
                "titulo": v["titulo"],
                "traducao": "",
                "coluna": col_alvo,
                "notas": "",
                "data_publicacao": v.get("data_publicacao") or "",
                "criado": storage.now(),
                "checklist": ck_alvo,
            })

        v_ret = dict(v)

    # Sincroniza em background com a nuvem do DarkPlanner
    def _sync_bg():
        try:
            atualizar_video_dp(vid, campos_dp)
            if roteiro and roteiro.strip() and canal_id:
                salvar_roteiro_dp(canal_id, vid, roteiro.strip())
        except Exception:
            pass

    threading.Thread(target=_sync_bg, daemon=True).start()
    return {
        "ok": True,
        "vid": vid,
        "titulo": v_ret.get("titulo"),
        "channel_id": v_ret.get("channel_id"),
        "concluido": bool(v_ret.get("concluido")),
        "publicado": bool(v_ret.get("publicado")),
        "concluido_em": v_ret.get("concluido_em") or "",
        "video": v_ret,
        "msg": (
            f"Vídeo '{v_ret.get('titulo')}' marcado como CONCLUÍDO E PUBLICADO!"
            if v_ret.get("publicado")
            else (
                f"Vídeo '{v_ret.get('titulo')}' marcado como 100% CONCLUÍDO!"
                if concluido
                else f"Vídeo '{v_ret.get('titulo')}' reaberto (Em Produção)."
            )
        ),
    }


def excluir_video_dp(vid):
    try:
        req("DELETE", f"/videos/{vid}")
    except Exception as e:
        print(f"Aviso ao excluir vídeo {vid} no DarkPlanner:", e)


def buscar_roteiro_dp(vid):
    """Busca o roteiro salvo na nuvem do DarkPlanner para este vídeo."""
    try:
        r = req("GET", f"/roteiros/video/{vid}")
        return (r or {}).get("conteudo") or ""
    except Exception:
        return ""


def salvar_roteiro_dp(canal_id, vid, conteudo, titulo="", **_kwargs):
    """Salva o roteiro direto no DarkPlanner Web (/api/roteiros/save-or-create) e marca checklist_roteiro='Pronto'."""
    if not canal_id or not vid or not (conteudo or "").strip():
        return None
    try:
        res = req("POST", "/roteiros/save-or-create", json_body={
            "canal_id": str(canal_id),
            "video_id": str(vid),
            "conteudo": conteudo,
        })
        atualizar_video_dp(vid, {"checklist_roteiro": "Pronto"})
        return res
    except Exception as e:
        print("Aviso ao salvar roteiro no DarkPlanner:", e)
        return None


def salvar_prompt_dp(canal_id, nome, categoria, conteudo, pid=None):
    """Cria ou edita um Prompt Mestre do canal diretamente no DarkPlanner Web."""
    body = {"canal_id": canal_id, "nome": nome, "categoria": categoria or "", "conteudo": conteudo}
    if pid:
        res = req("PUT", f"/prompts/{pid}", json_body=body)
    else:
        res = req("POST", "/prompts", json_body=body)
    sincronizar_tudo(forcar=True)
    return res


# ==============================================================================
# GERADOR DE ÁUDIO DARKPLANNER (/audio-generator) + RESULTADOS + SRT TEMPO VEO
# ==============================================================================

def limpar_apenas_roteiro(texto):
    """Remove introduções da IA ('de 2000 palavras, garantindo uma duração...'), títulos (# ...),
    divisórias (---), cabeçalhos de blocos (Bloco 1, [Gancho]), tópicos de estrutura e formatação markdown (**),
    deixando EXCLUSIVAMENTE o texto puro falado pelo narrador."""
    import re
    if not texto:
        return ""
    t = texto.replace("\r\n", "\n").strip()

    meta_re = re.compile(
        r"(?i)(palavras por minuto|words per minute|\b\d+\s*ppm\b|dura[çc][ãa]o de aproximadamente|"
        r"dura[çc][ãa]o estimada|garantindo uma dura[çc][ãa]o|aqui est[áa] o roteiro|abaixo est[áa] o roteiro|"
        r"segue o roteiro|escrevi o roteiro|here is the (complete |full )?script|contagem de palavras|"
        r"total de palavras|word count|meta configurada|estrutura detalhada|alinhamento conversacional|"
        r"c[áa]lculo exato de tempo|potencial de ctr|espero que (goste|este roteiro)|"
        r"se precisar de (algum ajuste|altera[çc][õo]es)|arquitetura v8 ninja pro|"
        r"meta de palavras|tempo em tela|loop aberto|cliffhanger|tese/conflito|o que acontece no bloco|"
        r"aprovar a estrutura|escrever o roteiro completo|ritmo constante de \d+)"
    )
    bloco_hdr_re = re.compile(
        r"^\s*(?:[#*>•\-]+|\d+[\.\)]\s*|\*\*|\[|\()?\s*(?:bloco|block|ato|act|parte|part|cena|scene|cap[íi]tulo|chapter|"
        r"gancho|hook|introdu[çc][ãa]o|intro|conclus[ãa]o|cta|fechamento|abertura|se[çc][ãa]o|section|"
        r"meta|tempo|dura[çc][ãa]o|tese|conflito|loop|objetivo|resumo|nota|diagn[óo]stico)"
        r"(?:\s+\d+|\s*[:\-–—]|[\]\)\*])\s*.*$",
        re.IGNORECASE,
    )
    speaker_re = re.compile(
        r"^\s*\**(?:narrador|narrator|locutor|voice\s*over|voiceover|voz|host|apresentador)\**\s*:\s*\**",
        re.IGNORECASE,
    )

    linhas_limpas = []
    for linha in t.split("\n"):
        s = linha.strip()
        if not s:
            if linhas_limpas and linhas_limpas[-1] != "":
                linhas_limpas.append("")
            continue
        # Remove linhas divisórias (---, ***, ___)
        if re.match(r"^[-*_═━]{3,}\s*$", s):
            continue
        # Remove títulos Markdown (# Título, ## Bloco 1, ### ...)
        if re.match(r"^#{1,6}\s+", s):
            continue
        # Remove tópicos de lista de estrutura (* **...**, - **...**, 1. **...**)
        if re.match(r"^(?:[\*\-•]|\d+[\.\)])\s+\*\*[^*]+\*\*\s*:", s):
            continue
        # Remove linhas que são apenas instruções de cena entre colchetes ou parênteses [Som de chuva]
        if re.match(r"^[\[\(][^\]\)]{1,120}[\]\)]\s*$", s) and not s.lower().startswith("[pause"):
            continue
        # Remove cabeçalhos de bloco (até 180 chars)
        if len(s) <= 180 and bloco_hdr_re.match(s):
            continue
        # Remove parágrafos de meta-comentário da IA (contagem de palavras, PPM, duração, etc.)
        if meta_re.search(s):
            continue
        # Remove prefixo "Narrador:" mantendo a fala
        s = speaker_re.sub("", s).strip()
        # Remove marcadores de tempo ou índice no início/meio da linha: [00:00], [00:00 - 02:00], [000], (00:00), 00:00 -
        s = re.sub(r"\[\s*\d{1,3}(?:\s*[:\-–—]\s*\d{1,3}){0,3}\s*\]", " ", s)
        s = re.sub(r"\(\s*\d{1,2}:\d{2}(?::\d{2})?(?:\s*[-–—]\s*\d{1,2}:\d{2}(?::\d{2})?)?\s*\)", " ", s)
        s = re.sub(r"^\s*\d{1,2}:\d{2}(?::\d{2})?\s*[-–—:]\s*", "", s)
        # Remove qualquer tag de bloco/cena/efeito entre colchetes [Bloco 1], [Hook], [SFX], [00:00], etc.
        s = re.sub(r"\[[^\]\n]{1,80}\]", " ", s)
        # Remove negrito/itálico markdown (**texto** -> texto)
        s = re.sub(r"\*{1,3}([^*]+)\*{1,3}", r"\1", s)
        s = re.sub(r"^>\s*", "", s)
        s = re.sub(r"\s{2,}", " ", s).strip()
        if s:
            linhas_limpas.append(s)

    return "\n\n".join(p.strip() for p in "\n".join(linhas_limpas).split("\n\n") if p.strip())

def audio_config_canal(canal_id=None):
    """Retorna a configuração de voz/legenda do canal (Foto 4) + roteiros disponíveis + lista de vozes."""
    vozes = _CACHE.get("vozes") or []
    if not vozes:
        try:
            rv = req("GET", "/audio-tts/voices")
            vozes = rv.get("voices", []) if isinstance(rv, dict) else (rv if isinstance(rv, list) else [])
            _CACHE["vozes"] = vozes
        except Exception:
            vozes = []
    for v in vozes:
        if isinstance(v, dict) and not v.get("voice_id"):
            v["voice_id"] = v.get("id") or v.get("idApi") or ""

    cfg_res = {}
    roteiros = []
    if canal_id:
        try:
            cfg_res = req("GET", f"/audio-config/resolve?canal_id={canal_id}") or {}
        except Exception:
            cfg_res = {}
        try:
            rot_res = req("GET", f"/roteiros/disponiveis-para-audio?canal_id={canal_id}") or {}
            roteiros = rot_res.get("videos") or rot_res.get("roteiros") or []
        except Exception:
            roteiros = []
    else:
        try:
            cfg_res = req("GET", "/audio-config/default") or {}
        except Exception:
            cfg_res = {}

    cfg = cfg_res.get("config") or cfg_res or {}
    voice_id = (cfg.get("voice_id") or cfg.get("default_voice_id") or "").strip()
    ch_name_low = str(cfg_res.get("channel_name") or "").lower()
    eh_canal_fr = str(canal_id or "").strip() == "a8068857-d56f-4aba-baf3-ea2b7ebda5bb" or "gta" in ch_name_low
    default_vid = "2915e0a6-6851-4b96-ae94-0ec3738955fa" if eh_canal_fr else "cdf1ce4c-bbe0-43f5-b4ad-df00daae27ad"
    default_vname = "Léo - Reassuring and Dynamic" if eh_canal_fr else "Paul - Australian Professional Presenter"
    voice_name = cfg.get("voice_name") or default_vname
    voz_obj = next((v for v in vozes if (v.get("voice_id") or v.get("id")) == voice_id), None)
    if not voz_obj and vozes:
        # Tenta localizar pelo nome ou usa a voz padrão validada no DarkPlanner
        voz_obj = next((v for v in vozes if voice_name and voice_name.lower() in (v.get("name") or "").lower()), None)
        if not voz_obj:
            voz_obj = next((v for v in vozes if (v.get("voice_id") or v.get("id")) == default_vid), None) or vozes[0]
        voice_id = voz_obj.get("voice_id") or voz_obj.get("id") or default_vid
        voice_name = voz_obj.get("name") or voice_name
    elif not voice_id:
        voice_id = default_vid

    if not voz_obj:
        voz_obj = {"voice_id": voice_id, "id": voice_id, "name": voice_name, "gender": "Masculino", "language": "Francês" if eh_canal_fr else "Inglês"}
    else:
        voz_obj = dict(voz_obj)
        vi = voz_obj.get("voice_info") or {}
        lg = (voz_obj.get("language") or vi.get("language") or "").lower()
        voz_obj["language"] = {"en": "Inglês", "pt": "Português", "es": "Espanhol", "fr": "Francês"}.get(lg, lg or ("Francês" if eh_canal_fr else "Inglês"))
        gd = (voz_obj.get("genero") or voz_obj.get("gender") or vi.get("gender") or "").lower()
        voz_obj["gender"] = "Masculino" if gd in ("male", "masculino") else ("Feminino" if gd in ("female", "feminino") else "Profissional")

    for r in roteiros:
        if isinstance(r, dict):
            if r.get("roteiro_conteudo"):
                r["roteiro_conteudo"] = limpar_apenas_roteiro(r["roteiro_conteudo"])
            if r.get("conteudo"):
                r["conteudo"] = limpar_apenas_roteiro(r["conteudo"])

    sub_veo_min = max(1, int(cfg.get("subtitle_veo_min") or 3))
    sub_veo_max = max(sub_veo_min + 1, int(cfg.get("subtitle_veo_max") or 8))
    sub_veo_words = max(1, int(cfg.get("subtitle_veo_words") or 5))
    sub_words = max(1, int(cfg.get("subtitle_words") or 5))

    return {
        "ok": True,
        "canal_id": canal_id,
        "channel_name": cfg_res.get("channel_name") or "",
        "source": cfg_res.get("source") or "default",
        "config": {
            "voice_id": voice_id,
            "default_voice_id": voice_id,
            "voice_name": voz_obj.get("name") or voice_name,
            "speed": float(cfg.get("speed") or 1.0),
            "volume": float(cfg.get("volume") or 1.0),
            "subtitle_enabled": cfg.get("subtitle_enabled", True),
            "subtitle_words": sub_words,
            "subtitle_case": cfg.get("subtitle_case") or "normal",
            "subtitle_veo_words": sub_veo_words,
            "subtitle_veo_min": sub_veo_min,
            "subtitle_veo_max": sub_veo_max,
        },
        "voz": voz_obj or {"voice_id": voice_id, "name": "Paul - Australian Professional Presenter"},
        "roteiros": roteiros,
        "vozes": vozes,
        "voices": vozes,
    }


def audio_historico_dp(limit=80):
    """Lista os áudios gerados na aba Resultados (Foto 5) do DarkPlanner."""
    r = req("GET", f"/audio-tts/history?limit={int(limit)}")
    hist = (r or {}).get("history") or []
    return {"ok": True, "history": hist, "items": hist}


def audio_gerar_dp(dados):
    """Envia o roteiro para gerar áudio no DarkPlanner (/api/audio-tts/generate) com validação automática de voice_id e subtitle_veo_min >= 1."""
    texto = limpar_apenas_roteiro(dados.get("text") or dados.get("roteiro") or "")
    if not texto:
        raise ValueError("Digite ou cole o roteiro para gerar o áudio.")
    canal_id = dados.get("canal_id")
    voice_id_req = (dados.get("voice_id") or "").strip()

    try:
        c = audio_config_canal(canal_id)
    except Exception:
        c = {"config": {"voice_id": "cdf1ce4c-bbe0-43f5-b4ad-df00daae27ad", "subtitle_veo_min": 3, "subtitle_veo_max": 8}, "vozes": []}

    vozes_disp = c.get("vozes") or []
    ids_validos = {(v.get("voice_id") or v.get("id")): (v.get("voice_id") or v.get("id")) for v in vozes_disp if (v.get("voice_id") or v.get("id"))}

    voice_id = ""
    if voice_id_req and (not ids_validos or voice_id_req in ids_validos):
        # Evita nomes soltos inválidos como "Brian" ou IDs legados fora do catálogo
        if "-" in voice_id_req or voice_id_req in ids_validos:
            voice_id = voice_id_req
    if not voice_id and voice_id_req and vozes_disp:
        # Tenta casar pelo nome da voz caso tenha sido enviado nome em vez de UUID
        achou_nome = next((v for v in vozes_disp if voice_id_req.lower() in (v.get("name") or "").lower()), None)
        if achou_nome:
            voice_id = achou_nome.get("voice_id") or achou_nome.get("id") or ""
    if not voice_id:
        voice_id = (c.get("config") or {}).get("voice_id") or "cdf1ce4c-bbe0-43f5-b4ad-df00daae27ad"
    if ids_validos and voice_id not in ids_validos:
        voice_id = (
            ids_validos.get("cdf1ce4c-bbe0-43f5-b4ad-df00daae27ad")
            or next(iter(ids_validos.values()))
        )

    cfg_canal = c.get("config") or {}
    veo_min = max(1, int(dados.get("subtitle_veo_min") or cfg_canal.get("subtitle_veo_min") or 3))
    veo_max = max(veo_min + 1, int(dados.get("subtitle_veo_max") or cfg_canal.get("subtitle_veo_max") or 8))
    veo_words = max(1, int(dados.get("subtitle_veo_words") or cfg_canal.get("subtitle_veo_words") or 5))
    sub_words = max(1, int(dados.get("subtitle_words") or cfg_canal.get("subtitle_words") or 5))

    payload = {
        "text": texto,
        "voice_id": voice_id,
        "title": (dados.get("title") or dados.get("nome") or "Áudio Roteiro").strip(),
        "async_mode": True,
        "speed": float(dados.get("speed", cfg_canal.get("speed", 1.0)) or 1.0),
        "volume": float(dados.get("volume", cfg_canal.get("volume", 1.0)) or 1.0),
        "subtitle_words": sub_words,
        "subtitle_case": dados.get("subtitle_case") or cfg_canal.get("subtitle_case") or "normal",
        "subtitle_veo_words": veo_words,
        "subtitle_veo_min": veo_min,
        "subtitle_veo_max": veo_max,
    }
    try:
        res = req("POST", "/audio-tts/generate", json_body=payload, timeout=45)
    except Exception as e:
        if "voice id is invalid" in str(e).lower() and ids_validos:
            fallback_vid = (
                ids_validos.get("cdf1ce4c-bbe0-43f5-b4ad-df00daae27ad")
                or next(iter(ids_validos.values()))
            )
            payload["voice_id"] = fallback_vid
            res = req("POST", "/audio-tts/generate", json_body=payload, timeout=45)
        else:
            raise
    dp_vid = dados.get("dp_video_id")
    if dp_vid:
        try:
            atualizar_video_dp(dp_vid, {"checklist_narracao": "Pronto"})
        except Exception:
            pass
    return res


def audio_excluir_dp(job_id):
    """Exclui um áudio do histórico Resultados do DarkPlanner."""
    return req("DELETE", f"/audio-tts/history/{job_id}")


# ---------------- Algoritmo Oficial Editar SRT Tempo VEO (Quebra por Frase) ----------------

def _ms_para_srt(ms):
    ms = max(0, round(float(ms or 0)))
    h = ms // 3600000
    m = (ms % 3600000) // 60000
    s = (ms % 60000) // 1000
    mil = ms % 1000
    return f"{h:02d}:{m:02d}:{s:02d},{mil:03d}"


def _srt_para_ms(tc):
    import re
    m = re.match(r"(\d{2}):(\d{2}):(\d{2})[,.](\d{3})", (tc or "").strip())
    if not m:
        return 0
    return int(m.group(1)) * 3600000 + int(m.group(2)) * 60000 + int(m.group(3)) * 1000 + int(m.group(4))


def _parse_srt_veo(raw):
    import re
    blocos = []
    partes = re.split(r"\n\s*\n", (raw or "").replace("\r\n", "\n").strip())
    for p in partes:
        linhas = [l.strip() for l in p.split("\n") if l.strip()]
        if not linhas:
            continue
        ti = next((idx for idx, l in enumerate(linhas) if "-->" in l), -1)
        if ti == -1:
            continue
        ab = linhas[ti].split("-->")
        txt = " ".join(linhas[ti + 1:]).strip()
        if txt:
            blocos.append({
                "startMs": _srt_para_ms(ab[0]),
                "endMs": _srt_para_ms(ab[1] if len(ab) > 1 else ab[0]),
                "text": txt,
            })
    return blocos


def _parse_words_json(raw_list):
    if not isinstance(raw_list, list):
        return []
    out = []
    for x in raw_list:
        if not x or not isinstance(x, dict):
            continue
        w = str(x.get("word") if x.get("word") is not None else (x.get("text") or "")).strip()
        if not w:
            continue
        if isinstance(x.get("start_time"), (int, float)):
            st = float(x["start_time"])
        elif isinstance(x.get("start"), (int, float)):
            st = float(x["start"]) * 1000.0
        else:
            st = float(x.get("startMs") or 0)
        if isinstance(x.get("end_time"), (int, float)):
            et = float(x["end_time"])
        elif isinstance(x.get("end"), (int, float)):
            et = float(x["end"]) * 1000.0
        else:
            et = float(x.get("endMs") or st)
        out.append({"word": w, "startMs": st, "endMs": max(st, et)})
    return out


def _norm_w(w):
    import re
    return re.sub(r"[^\p{L}\p{N}]+" if False else r"[^\w]+", "", (w or "").lower(), flags=re.UNICODE)


def _alinhar_breaks_iniciais(blocos_srt, words):
    if not blocos_srt or not words:
        return None
    breaks = []
    r = 0
    n_words = len(words)
    for idx_b in range(len(blocos_srt) - 1):
        b_words = [x for x in blocos_srt[idx_b]["text"].split() if x]
        if not b_words:
            continue
        alvo = r + len(b_words)
        if alvo >= n_words:
            break
        ultima_norm = _norm_w(b_words[-1])
        prox_list = [x for x in blocos_srt[idx_b + 1]["text"].split() if x]
        prox_norm = _norm_w(prox_list[0]) if prox_list else ""
        melhor = alvo
        melhor_score = -1
        for d in (0, -1, 1, -2, 2, -3, 3):
            cand = alvo + d
            if cand <= r or cand >= n_words:
                continue
            sc = 0
            if ultima_norm and _norm_w(words[cand - 1]["word"]) == ultima_norm:
                sc += 2
            if prox_norm and _norm_w(words[cand]["word"]) == prox_norm:
                sc += 2
            if sc > melhor_score:
                melhor_score = sc
                melhor = cand
                if sc == 4:
                    break
        breaks.append(melhor)
        r = melhor
    return breaks


def _fim_frase(w):
    import re
    limpo = re.sub(r"[\"'”’)\]\}>]+$", "", (w or "").strip())
    if not limpo:
        return 0
    ult = limpo[-1]
    if ult in (".", "!", "?", "…"):
        return 2
    if ult in (",", ";", ":"):
        return 1
    return 0


def quebrar_por_frases_veo(words, faixas):
    """Algoritmo oficial Kfe ('Quebrar por frases') do Editor SRT Tempo VEO do DarkPlanner."""
    if len(words) <= 1 or not faixas:
        return []
    breaks = []
    i = 0
    n = len(words)
    while i < n:
        z_idx = 0
        acum = 0
        while z_idx < len(faixas) - 1:
            cnt = max(0, int(faixas[z_idx].get("count") or 0))
            if len(breaks) < acum + cnt:
                break
            acum += cnt
            z_idx += 1
        zona = faixas[z_idx]
        max_ms = max(1000, float(zona.get("maxMs") or 8000))
        min_ms = max(0, min(max_ms - 500, float(zona.get("minMs") or 0)))
        inicio_ms = words[i]["startMs"]
        p = i
        while p + 1 < n and (words[p + 1]["endMs"] - inicio_ms) <= max_ms:
            p += 1
        if p >= n - 1:
            break
        c = i
        while c < p and (words[c]["endMs"] - inicio_ms) < min_ms:
            c += 1
        corte = -1
        for d in range(p, c - 1, -1):
            if _fim_frase(words[d]["word"]) == 2:
                corte = d
                break
        if corte == -1:
            for d in range(p, c - 1, -1):
                if _fim_frase(words[d]["word"]) == 1:
                    corte = d
                    break
        if corte == -1:
            corte = p
        breaks.append(corte + 1)
        i = corte + 1
    return breaks


def montar_blocos_veo(words, breaks):
    """Transforma words + breaks em blocos com startMs, endMs, durationSec, words e texto."""
    if not words:
        return []
    pts = [0] + sorted(set(int(b) for b in (breaks or []) if 0 < int(b) < len(words))) + [len(words)]
    blocos = []
    for idx in range(len(pts) - 1):
        ini, fim = pts[idx], pts[idx + 1]
        fatia = words[ini:fim]
        if not fatia:
            continue
        st = fatia[0]["startMs"]
        et = fatia[-1]["endMs"]
        txt = " ".join(w["word"] for w in fatia)
        gap_ms = 0
        if idx + 1 < len(pts) - 1:
            prox_ini = pts[idx + 1]
            if prox_ini < len(words):
                gap_ms = max(0, round(words[prox_ini]["startMs"] - et))
        blocos.append({
            "index": idx + 1,
            "startWordIdx": ini,
            "endWordIdx": fim,
            "startMs": round(st),
            "endMs": round(et),
            "startSrt": _ms_para_srt(st),
            "endSrt": _ms_para_srt(et),
            "durationSec": round((et - st) / 1000.0, 2),
            "gapAfterSec": round(gap_ms / 1000.0, 2),
            "wordCount": len(fatia),
            "text": txt,
            "words": fatia,
        })
    return blocos


def formatar_srt_veo(blocos):
    """Formata a lista de blocos no formato .srt padrão (Xfe)."""
    partes = []
    for idx, b in enumerate(blocos):
        st = b.get("startSrt") or _ms_para_srt(b.get("startMs", 0))
        et = b.get("endSrt") or _ms_para_srt(b.get("endMs", 0))
        partes.append(f"{idx + 1}\n{st} --> {et}\n{b.get('text', '').strip()}")
    return "\n\n".join(partes) + ("\n" if partes else "")


def audio_srt_veo_dados(job_id, srt_tempo_url="", min_s=4, max_s=8, faixas=None, quebrar_frases=True, breaks_custom=None):
    """Carrega srtsynctempo.srt e words_time.json do áudio e aplica a Quebra por Frase com Faixas
    (padrão: primeiros 60 blocos de 2 a 4s e os demais de 4 a 8s quebrados por frase)."""
    if not srt_tempo_url and job_id:
        srt_tempo_url = f"https://cdn.darkplanner.com.br/audios/{job_id}/srtsynctempo.srt"
    import re
    words_url = re.sub(r"/[^/]+$", "/words_time.json", srt_tempo_url)

    r_srt = requests.get(srt_tempo_url, timeout=20)
    if not r_srt.ok:
        raise RuntimeError(f"Não foi possível baixar o SRT Tempo ({r_srt.status_code}).")
    srt_original = r_srt.text

    words = []
    try:
        r_w = requests.get(words_url, timeout=20)
        if r_w.ok:
            words = _parse_words_json(r_w.json())
    except Exception:
        words = []

    blocos_iniciais_srt = _parse_srt_veo(srt_original)
    breaks_originais = _alinhar_breaks_iniciais(blocos_iniciais_srt, words) or []

    if breaks_custom is not None:
        breaks_atuais = [int(x) for x in breaks_custom if 0 < int(x) < len(words)]
    elif quebrar_frases and words:
        if not faixas:
            faixas = [
                {"count": 60, "minMs": 2000.0, "maxMs": 4000.0},
                {"minMs": float(min_s or 4) * 1000.0, "maxMs": float(max_s or 8) * 1000.0},
            ]
        breaks_atuais = quebrar_por_frases_veo(words, faixas)
    else:
        breaks_atuais = list(breaks_originais)

    blocos = montar_blocos_veo(words, breaks_atuais) if words else []
    srt_final = formatar_srt_veo(blocos) if blocos else srt_original

    if job_id and srt_final:
        try:
            pasta_dp = os.path.join(storage.DATA_DIR, "audios_dp", job_id)
            os.makedirs(pasta_dp, exist_ok=True)
            with open(os.path.join(pasta_dp, "srtsynctempo_editado.srt"), "w", encoding="utf-8") as f_ed:
                f_ed.write(srt_final)
        except Exception:
            pass

    return {
        "ok": True,
        "job_id": job_id,
        "srt_tempo_url": srt_tempo_url,
        "words_url": words_url,
        "words": words,
        "total_words": len(words),
        "breaks_originais": breaks_originais,
        "breaks": breaks_atuais,
        "blocos": blocos,
        "total_blocos": len(blocos),
        "srt_texto": srt_final,
    }


def audio_baixar_e_vincular(job_id, audio_url="", srt_texto="", vid="", file_name="", criar_cenas_veo=True, faixas=None, quebrar_frases=True, min_s=4, max_s=8):
    """Baixa o MP3 e salva SOMENTE 1 SRT (o SRT Tempo VEO editado com quebra por frases).
    Também salva automaticamente na pasta organizada `D:\\ARQUIVOS DE VIDEOS\\<NOME DO VIDEO>`."""
    import shutil
    import time

    if not audio_url and job_id:
        audio_url = f"https://cdn.darkplanner.com.br/audios/{job_id}/audio.mp3"
    if not srt_texto and job_id:
        dados_veo = audio_srt_veo_dados(
            job_id,
            min_s=min_s,
            max_s=max_s,
            faixas=faixas,
            quebrar_frases=quebrar_frases,
        )
        srt_texto = dados_veo.get("srt_texto") or ""

    pasta_dp = os.path.join(storage.DATA_DIR, "audios_dp", job_id or "avulso")
    os.makedirs(pasta_dp, exist_ok=True)
    mp3_local = os.path.join(pasta_dp, "audio.mp3")
    srt_local = os.path.join(pasta_dp, "srtsynctempo_editado.srt")

    if audio_url:
        r_mp3 = requests.get(audio_url, timeout=60)
        if r_mp3.ok:
            with open(mp3_local, "wb") as f:
                f.write(r_mp3.content)

    if srt_texto:
        with open(srt_local, "w", encoding="utf-8") as f:
            f.write(srt_texto)
        _limpar_srts_extras_na_pasta(pasta_dp, nome_srt_oficial="srtsynctempo_editado.srt")

    cenas_criadas = 0
    titulo_video_org = (file_name or "").strip()
    roteiro_video_org = ""
    if vid:
        p_vid = storage.video_dir(vid)
        mp3_vid = os.path.join(p_vid, "narracao_propria.mp3")
        srt_vid = os.path.join(p_vid, "legenda_propria.srt")
        if os.path.exists(mp3_local):
            shutil.copyfile(mp3_local, mp3_vid)
        if srt_texto:
            with open(srt_vid, "w", encoding="utf-8") as f:
                f.write(srt_texto)
            _limpar_srts_extras_na_pasta(p_vid, nome_srt_oficial="legenda_propria.srt")

        blocos_parsed = _parse_srt_veo(srt_texto)
        with storage.Tx() as db:
            v = storage.find(db.get("videos", []), vid)
            if v:
                if not titulo_video_org:
                    titulo_video_org = (v.get("titulo") or "").strip()
                roteiro_video_org = (v.get("roteiro") or "").strip()
                v["narracao_arquivo"] = mp3_vid
                v["legenda_arquivo"] = srt_vid
                v["narracao_propria"] = True
                v["dp_audio_job_id"] = job_id
                if blocos_parsed:
                    v["duracao_total"] = round(blocos_parsed[-1]["endMs"] / 1000.0, 2)
                v["etapas"]["narracao"] = True
                if criar_cenas_veo and blocos_parsed:
                    novas_cenas = []
                    for idx, b in enumerate(blocos_parsed):
                        ini_s = round(b["startMs"] / 1000.0, 2)
                        fim_s = round(b["endMs"] / 1000.0, 2)
                        dur_s = max(1.0, round(fim_s - ini_s, 2))
                        novas_cenas.append({
                            "n": idx + 1,
                            "id": f"c{idx + 1}",
                            "ordem": idx + 1,
                            "texto": b["text"],
                            "trecho": b["text"],
                            "inicio": ini_s,
                            "fim": fim_s,
                            "duracao": dur_s,
                            "tipo": "video",
                            "termo_busca": b["text"][:80],
                            "prompt_ia": b["text"],
                            "arquivo": "",
                        })
                    v["cenas"] = novas_cenas
                    v["etapas"]["cenas"] = True
                    cenas_criadas = len(novas_cenas)

    # Salva sempre na pasta organizada D:\ARQUIVOS DE VIDEOS\<NOME DO VIDEO> (SOMENTE 1 Áudio MP3 e 1 SRT Tempo!)
    pasta_arquivos_video = ""
    if titulo_video_org and titulo_video_org.lower() not in ("avulso", "video em producao", "vídeo em produção"):
        try:
            pasta_arquivos_video = _obter_pasta_arquivos_video(titulo_video_org, criar=True)
            slug_av = os.path.basename(pasta_arquivos_video)
            mp3_av = os.path.join(pasta_arquivos_video, f"{slug_av}.mp3")
            srt_av = os.path.join(pasta_arquivos_video, f"{slug_av}_srtsynctempo.srt")
            if os.path.exists(mp3_local):
                shutil.copy2(mp3_local, mp3_av)
            if srt_texto:
                with open(srt_av, "w", encoding="utf-8") as f_av:
                    f_av.write(srt_texto)
                _limpar_srts_extras_na_pasta(pasta_arquivos_video, nome_srt_oficial=os.path.basename(srt_av))
            if roteiro_video_org:
                with open(os.path.join(pasta_arquivos_video, "00_ROTEIRO_LIMPO.txt"), "w", encoding="utf-8") as f_rt:
                    f_rt.write(limpar_apenas_roteiro(roteiro_video_org) or roteiro_video_org)
        except Exception as e_av:
            print("Aviso ao salvar MP3/SRT em D:\\ARQUIVOS DE VIDEOS:", e_av)

    # Pequena pausa para garantir gravação completa do MP3 e SRT antes de anexar no DarkPlanner
    time.sleep(0.8)

    registrar_download_audio_srt(
        job_id=job_id,
        tipo="vincular_ambos",
        nome=titulo_video_org or file_name or vid or job_id,
        srt_texto=srt_texto,
        mp3_path=mp3_local if os.path.exists(mp3_local) else "",
        srt_path=srt_local if os.path.exists(srt_local) else "",
    )

    return {
        "ok": True,
        "job_id": job_id,
        "vid": vid,
        "mp3_local": mp3_local,
        "srt_local": srt_local,
        "pasta_arquivos_video": pasta_arquivos_video,
        "cenas_criadas": cenas_criadas,
        "download_mp3_url": f"/api/darkplanner/audio/file/{job_id}/audio.mp3",
        "download_srt_url": f"/api/darkplanner/audio/file/{job_id}/srtsynctempo_editado.srt",
    }


def registrar_download_audio_srt(job_id="", tipo="", nome="", srt_texto="", mp3_path="", srt_path=""):
    """Registra automaticamente quando o usuário baixa o áudio MP3 e/ou legenda SRT para que a interface
    reconheça imediatamente Passos 4 e 5 como concluídos (sem ficar carregando infinito)."""
    import json
    import time

    pasta_base = os.path.join(storage.DATA_DIR, "audios_dp")
    os.makedirs(pasta_base, exist_ok=True)
    arq_status = os.path.join(pasta_base, "ultimo_download_status.json")

    atual = {}
    if os.path.exists(arq_status):
        try:
            with open(arq_status, "r", encoding="utf-8") as f:
                atual = json.load(f) or {}
        except Exception:
            atual = {}

    jid = str(job_id or atual.get("job_id") or "").strip()
    pasta_job = os.path.join(pasta_base, jid) if jid else ""

    # Se baixou apenas MP3 e ainda não baixou o SRT VEO na pasta do job, já pré-carrega o SRT VEO do job_id!
    if jid and os.path.isdir(pasta_job):
        if not mp3_path:
            cand_m = os.path.join(pasta_job, "audio.mp3")
            if os.path.exists(cand_m) and os.path.getsize(cand_m) > 500:
                mp3_path = cand_m
        if not srt_texto:
            for fn_s in ("srtsynctempo_editado.srt", "srtsynctempo.srt", "legenda.srt", "srtsyncpalavra.srt"):
                cand_s = os.path.join(pasta_job, fn_s)
                if os.path.exists(cand_s) and os.path.getsize(cand_s) > 20:
                    try:
                        with open(cand_s, "r", encoding="utf-8") as fs:
                            srt_texto = fs.read()
                        srt_path = cand_s
                        break
                    except Exception:
                        pass
        if not srt_texto and jid:
            try:
                dados_veo = audio_srt_veo_dados(
                    jid,
                    quebrar_frases=True,
                    faixas=[{"count": 60, "minMs": 2000.0, "maxMs": 4000.0}, {"minMs": 4000.0, "maxMs": 8000.0}],
                )
                srt_texto = dados_veo.get("srt_texto") or ""
                if srt_texto:
                    srt_path = os.path.join(pasta_job, "srtsynctempo_editado.srt")
                    with open(srt_path, "w", encoding="utf-8") as fs:
                        fs.write(srt_texto)
            except Exception:
                pass

    n_blocos = len(_parse_srt_veo(srt_texto)) if srt_texto else int(atual.get("total_blocos") or 0)
    novo_st = {
        "job_id": jid,
        "nome": nome or atual.get("nome") or f"audio_{jid}",
        "ultimo_tipo": tipo,
        "mp3_pronto": bool(mp3_path and os.path.exists(mp3_path)) or bool(atual.get("mp3_pronto") and jid == atual.get("job_id")),
        "srt_pronto": bool(srt_texto) or bool(atual.get("srt_pronto") and jid == atual.get("job_id")),
        "mp3_path": mp3_path or atual.get("mp3_path") or "",
        "srt_path": srt_path or atual.get("srt_path") or "",
        "srt_texto": srt_texto or (atual.get("srt_texto") if jid == atual.get("job_id") else "") or "",
        "total_blocos": n_blocos,
        "mp3_url": f"/api/darkplanner/audio/file/{jid}/audio.mp3" if jid else "",
        "srt_url": f"/api/darkplanner/audio/file/{jid}/srtsynctempo_editado.srt" if jid else "",
        "timestamp": time.time(),
    }
    try:
        with open(arq_status, "w", encoding="utf-8") as f:
            json.dump(novo_st, f, indent=2, ensure_ascii=False)
    except Exception:
        pass
    return novo_st


def _titulo_bate_audio_estrito(nome_cand, titulo_alvo):
    """Compara de forma estrita o nome do áudio com o título do vídeo atual para NUNCA misturar áudios de vídeos diferentes."""
    import re
    import unicodedata

    def _norm(s):
        s = unicodedata.normalize("NFKD", str(s or "")).encode("ascii", "ignore").decode("ascii")
        return re.sub(r"[^\w\s]", " ", s.lower()).strip()

    c_norm = _norm(nome_cand)
    t_norm = _norm(titulo_alvo)
    if not c_norm or not t_norm:
        return False
    c_compact = re.sub(r"\s+", " ", c_norm)
    t_compact = re.sub(r"\s+", " ", t_norm)
    if c_compact == t_compact:
        return True
    if len(t_compact) >= 12 and (t_compact in c_compact or c_compact in t_compact):
        return True

    stopwords = {
        "what", "when", "where", "with", "from", "that", "this", "your", "were", "have",
        "would", "could", "should", "about", "into", "after", "before", "there", "their",
        "they", "them", "then", "than", "some", "more", "most", "only", "over", "under",
        "para", "como", "quando", "onde", "pelo", "pela", "mais", "uma", "sobre", "esse",
        "essa", "este", "esta", "isso", "aquilo", "entre", "depois", "antes", "muito",
        "todos", "todas", "cada", "mesmo", "video", "audio", "roteiro", "legenda", "veo",
        "palavra", "tempo", "srtsynctempo", "editado",
    }
    toks_t = [w for w in t_compact.split() if len(w) >= 4 and w not in stopwords]
    toks_c = set(w for w in c_compact.split() if len(w) >= 4 and w not in stopwords)
    if len(toks_t) >= 2:
        acertos = sum(1 for w in toks_t if w in toks_c)
        if acertos >= max(2, int(round(len(toks_t) * 0.75))):
            return True
    elif len(toks_t) == 1 and toks_t[0] in toks_c and len(toks_t[0]) >= 6:
        return True
    return False


def detectar_audio_srt_baixado(job_id="", titulo="", vid="", canal_id=""):
    """Detecta automaticamente se o áudio (.mp3) e a legenda (.srt) já foram gerados/baixados:
    1. Na pasta local `data/audios_dp/ultimo_download_status.json` ou `data/audios_dp/<job_id>`;
    2. Na pasta `Downloads` do Windows ou `Downloads/DarkPlanner/audios`;
    3. No histórico recente do `/audio-generator` do DarkPlanner (`completed`).
    IMPORTANTE: Exige correspondência estrita de `job_id` ou de `titulo` do vídeo atual para NUNCA reutilizar o áudio de um vídeo anterior!"""
    import glob
    import json
    import re
    import shutil
    import time

    pasta_base = os.path.join(storage.DATA_DIR, "audios_dp")
    os.makedirs(pasta_base, exist_ok=True)
    arq_status = os.path.join(pasta_base, "ultimo_download_status.json")
    job_id = (job_id or "").strip()
    titulo = (titulo or "").strip()

    # 1. Verifica registro direto de download recente APENAS se bater com o job_id ou com o título estrito do vídeo atual
    if os.path.exists(arq_status):
        try:
            with open(arq_status, "r", encoding="utf-8") as f:
                st = json.load(f) or {}
            idade = time.time() - float(st.get("timestamp") or 0)
            st_jid = str(st.get("job_id") or "").strip()
            st_nome = (st.get("nome") or "").strip()
            bate_job = bool(job_id and st_jid == job_id)
            bate_tit = bool(not job_id and titulo and _titulo_bate_audio_estrito(st_nome, titulo) and idade < 1800)
            if (bate_job or bate_tit) and (st.get("mp3_pronto") or st.get("srt_pronto")):
                # Garante que tanto MP3 quanto SRT estejam baixados para esse job_id
                if st_jid and (not st.get("srt_texto") or not st.get("mp3_pronto")):
                    try:
                        audio_baixar_e_vincular(job_id=st_jid, vid=vid, file_name=st.get("nome") or titulo)
                        if os.path.exists(arq_status):
                            with open(arq_status, "r", encoding="utf-8") as f2:
                                st = json.load(f2) or st
                    except Exception:
                        pass
                return {
                    "ok": True,
                    "detectado": True,
                    "origem": "download_registrado",
                    **st,
                }
        except Exception:
            pass

    # 2. Verifica histórico ao vivo do DarkPlanner (/audio-generator) APENAS para o job_id ou título estrito do vídeo atual
    try:
        hist = audio_historico_dp(15) or {}
        items = hist.get("items") or hist.get("history") or (hist if isinstance(hist, list) else [])
        melhor_item = None
        for it in items:
            if (it.get("status") or "completed") != "completed":
                continue
            jid_it = str(it.get("job_id") or "").strip()
            nm_it = (it.get("file_name") or it.get("title") or "").strip()
            if job_id and jid_it == job_id:
                melhor_item = it
                break
            if not job_id and titulo and _titulo_bate_audio_estrito(nm_it, titulo):
                melhor_item = it
                break

        if melhor_item and melhor_item.get("job_id"):
            jid_found = str(melhor_item["job_id"]).strip()
            nm_found = melhor_item.get("file_name") or melhor_item.get("title") or titulo or f"audio_{jid_found}"
            audio_baixar_e_vincular(
                job_id=jid_found,
                audio_url=melhor_item.get("audio_url") or "",
                vid=vid,
                file_name=nm_found,
                criar_cenas_veo=True,
            )
            if os.path.exists(arq_status):
                with open(arq_status, "r", encoding="utf-8") as f:
                    st = json.load(f) or {}
                return {
                    "ok": True,
                    "detectado": True,
                    "origem": "historico_darkplanner",
                    **st,
                }
    except Exception:
        pass

    # 3. Verifica pasta Downloads do Windows por arquivos .mp3 e .srt recentes que correspondam ao job_id ou ao título atual
    pasta_dl = os.path.join(os.path.expanduser("~"), "Downloads")
    if os.path.isdir(pasta_dl) and (job_id or titulo):
        try:
            agora = time.time()

            def _arq_bate(caminho_arq):
                if (agora - os.path.getmtime(caminho_arq)) >= 1800:
                    return False
                base_nm = os.path.splitext(os.path.basename(caminho_arq))[0]
                if job_id and job_id.lower() in base_nm.lower():
                    return True
                if titulo and _titulo_bate_audio_estrito(base_nm, titulo):
                    return True
                return False

            mp3s = [p for p in glob.glob(os.path.join(pasta_dl, "*.mp3")) if _arq_bate(p)]
            srts = [p for p in glob.glob(os.path.join(pasta_dl, "*.srt")) if _arq_bate(p)]
            mp3s.sort(key=lambda p: os.path.getmtime(p), reverse=True)
            srts.sort(key=lambda p: os.path.getmtime(p), reverse=True)
            if mp3s or srts:
                mp3_esc = mp3s[0] if mp3s else ""
                srt_esc = srts[0] if srts else ""
                srt_txt = ""
                if srt_esc and os.path.exists(srt_esc):
                    with open(srt_esc, "r", encoding="utf-8", errors="replace") as fs:
                        srt_txt = fs.read()
                jid_dl = job_id or "downloads_local"
                p_dest = os.path.join(pasta_base, jid_dl)
                os.makedirs(p_dest, exist_ok=True)
                if mp3_esc:
                    shutil.copy2(mp3_esc, os.path.join(p_dest, "audio.mp3"))
                if srt_txt:
                    with open(os.path.join(p_dest, "srtsynctempo_editado.srt"), "w", encoding="utf-8") as fs:
                        fs.write(srt_txt)
                st_dl = registrar_download_audio_srt(
                    job_id=jid_dl,
                    tipo="downloads_windows",
                    nome=os.path.splitext(os.path.basename(mp3_esc or srt_esc))[0],
                    srt_texto=srt_txt,
                    mp3_path=os.path.join(p_dest, "audio.mp3") if mp3_esc else "",
                    srt_path=os.path.join(p_dest, "srtsynctempo_editado.srt") if srt_txt else "",
                )
                return {
                    "ok": True,
                    "detectado": True,
                    "origem": "pasta_downloads",
                    **st_dl,
                }
        except Exception:
            pass

    return {"ok": True, "detectado": False}


