def validar_srt_skill6(srt_texto):
    """Fase 1 da Skill 6 — Lê o SRT inteiro e valida índices, timestamps, start < end, durações e lacunas."""
    import re
    raw = (srt_texto or "").replace("\r\n", "\n").strip()
    if not raw:
        raise ValueError("O arquivo SRT está vazio. Gere ou carregue o SRT Tempo VEO antes de executar a Skill 6.")

    partes = re.split(r"\n\s*\n", raw)
    blocos = []
    erros_timing = 0
    avisos_limite = 0
    prev_end_ms = 0
    gaps_ms = 0

    for idx_bloco, p in enumerate(partes):
        linhas = [l.strip() for l in p.split("\n") if l.strip()]
        if not linhas:
            continue
        ti = next((i for i, l in enumerate(linhas) if "-->" in l), -1)
        if ti == -1:
            continue
        ab = linhas[ti].split("-->")
        st_str = ab[0].strip().replace(".", ",")
        et_str = (ab[1] if len(ab) > 1 else ab[0]).strip().replace(".", ",")
        st_ms = _srt_para_ms(st_str)
        et_ms = _srt_para_ms(et_str)
        txt = " ".join(linhas[ti + 1:]).strip()
        if not txt:
            txt = "..."
        if et_ms <= st_ms:
            erros_timing += 1
            et_ms = st_ms + 1500
            et_str = _ms_para_srt(et_ms)
        if st_ms < prev_end_ms:
            erros_timing += 1
        elif prev_end_ms > 0 and st_ms > prev_end_ms:
            gaps_ms += (st_ms - prev_end_ms)
        prev_end_ms = et_ms
        dur_s = round((et_ms - st_ms) / 1000.0, 3)
        if dur_s > 8.05:
            avisos_limite += 1
        blocos.append({
            "scene_index": len(blocos) + 1,
            "start": _ms_para_srt(st_ms),
            "end": _ms_para_srt(et_ms),
            "startMs": st_ms,
            "endMs": et_ms,
            "duration": dur_s,
            "text": txt,
        })

    if not blocos:
        raise ValueError("Nenhum bloco válido de legenda com timestamps (-->) foi encontrado no SRT.")

    active_sec = round(sum(b["duration"] for b in blocos), 3)
    total_sec = round(blocos[-1]["endMs"] / 1000.0, 3)
    return {
        "blocos": blocos,
        "total_blocos": len(blocos),
        "timing_errors": erros_timing,
        "blocks_over_8s": avisos_limite,
        "srt_end": blocos[-1]["end"],
        "total_duration_seconds": total_sec,
        "srt_active_seconds": active_sec,
        "srt_gaps_seconds": round(gaps_ms / 1000.0, 3),
        "min_block_seconds": min(b["duration"] for b in blocos),
        "max_block_seconds": max(b["duration"] for b in blocos),
    }


def _extrair_json_ia(texto):
    import json
    import re
    if not texto:
        return None
    t = texto.strip()
    m = re.search(r"```(?:json)?\s*([\s\S]*?)```", t)
    if m:
        t = m.group(1).strip()
    for ini_c, fim_c in (("{", "}"), ("[", "]")):
        i1 = t.find(ini_c)
        i2 = t.rfind(fim_c)
        if i1 != -1 and i2 != -1 and i2 > i1:
            cand = t[i1:i2 + 1]
            for s_try in (cand, re.sub(r",\s*([}\]])", r"\1", cand)):
                try:
                    return json.loads(s_try, strict=False)
                except Exception:
                    pass
    try:
        return json.loads(t, strict=False)
    except Exception:
        return None


def _extrair_dna_e_prompts_do_canal(prompts_canal, canal_nome=""):
    """Extrai TODOS os prompts do canal para uso conjunto após o roteiro (Skill 6 / Skill 5 + SRT + Estilo + Prompt Mestre + Edição):
    - Extrai verbatim `STYLE_DNA`, `CHARACTER_DNA`, `EXTRAS_DNA`, `NEGATIVE_DNA` (com ou sem aspas, ou `PROMPT BASE:` / `Preserve o estilo visual aprovado:`);
    - Reúne o conteúdo integral de Estilo, Prompt Mestre e Gerador de Edição do canal."""
    import re

    style_dna = ""
    character_dna = ""
    extras_dna = ""
    negative_dna = ""
    nomes_prompts = []
    blocos_unidos = []

    def _pegar_bloco_dna(texto, chave):
        # 1) Formato com aspas: STYLE_DNA:\n"..."
        m = re.search(rf'{chave}\s*:\s*\r?\n?"([^"]+)"', texto, flags=re.I)
        if m:
            return re.sub(r"\s+", " ", m.group(1)).strip()
        # 2) Formato na mesma linha ou linha seguinte sem aspas: STYLE_DNA: stylized 2D...
        m2 = re.search(rf"^{chave}\s*:\s*\r?\n?([^\r\n]+)", texto, flags=re.I | re.M)
        if m2:
            val = m2.group(1).strip().strip('"')
            # Ignora instruções meta como "incluir em TODOS os prompts"
            if val and not any(x in val.lower() for x in ("incluir em todos", "incluir apenas", "permanecem iguais", "copiados literalmente")):
                return re.sub(r"\s+", " ", val).strip()
        return ""

    # Prioriza prompts de Base YouTube vinculada (ytclone_*) na extração de DNA visual e de avatar
    prompts_ordenados_dna = sorted(
        list(prompts_canal or []),
        key=lambda p: 0 if (str(p.get("id") or "").startswith("ytclone_") or "base youtube" in str(p.get("nome") or p.get("title") or "").lower()) else 1,
    )

    for pm in (prompts_canal or []):
        nm = (pm.get("nome") or pm.get("title") or "").strip()
        cat = (pm.get("categoria") or pm.get("category") or "").strip()
        ct = (pm.get("conteudo") or pm.get("content") or "").strip()
        if not nm or not ct:
            continue
        label = f"{nm} ({cat})" if cat else nm
        nomes_prompts.append(label)
        blocos_unidos.append(f"==================================================================\nPROMPT DO CANAL: {label}\n==================================================================\n{ct}\n")

    for pm in prompts_ordenados_dna:
        ct = (pm.get("conteudo") or pm.get("content") or "").strip()
        if not ct:
            continue
        if not style_dna:
            style_dna = _pegar_bloco_dna(ct, "STYLE_DNA")
        if not style_dna:
            style_dna = _pegar_bloco_dna(ct, "PROMPT BASE")
        if not style_dna:
            m_aprov = re.search(r"Preserve o estilo visual aprovado\s*:\s*\r?\n([^\r\n]+)", ct, flags=re.I)
            if m_aprov:
                style_dna = re.sub(r"\s+", " ", m_aprov.group(1)).strip()
        if not character_dna:
            c_dna = _pegar_bloco_dna(ct, "CHARACTER_DNA")
            if c_dna and c_dna.upper() != "NENHUM":
                character_dna = c_dna
        if not extras_dna:
            extras_dna = _pegar_bloco_dna(ct, "EXTRAS_DNA")
        if not negative_dna:
            negative_dna = _pegar_bloco_dna(ct, "NEGATIVE_DNA")

    if not negative_dna:
        for pm in (prompts_canal or []):
            ct = (pm.get("conteudo") or pm.get("content") or "").strip()
            m_ev = re.search(r"^EVITAR\s*:\s*([^\r\n\-][^\r\n]+)", ct, flags=re.I | re.M)
            if m_ev:
                negative_dna = "No " + re.sub(r"\s+", " ", m_ev.group(1)).strip()
                break

    # Fallback inteligente por canal caso o prompt não tenha cabeçalho explícito STYLE_DNA
    cn_low = (canal_nome or "").lower()
    if "recomeco" in cn_low or "recomeço" in cn_low:
        vinc_iflord = _montar_vinculo_padrao_iflord_capitto_recomeco()
        if not style_dna or "minimalist 2d vector-like educational cartoon with near-black" in style_dna.lower():
            style_dna = vinc_iflord.get("style_dna") or style_dna
        if not character_dna or character_dna.upper() == "NENHUM":
            character_dna = vinc_iflord.get("character_dna") or character_dna
        if not extras_dna:
            extras_dna = vinc_iflord.get("extras_dna") or extras_dna
        if not negative_dna:
            negative_dna = vinc_iflord.get("negative_dna") or negative_dna
    elif not style_dna:
        if "catch-up" in cn_low or "catch up" in cn_low:
            style_dna = (
                "stylized 2D adult editorial cartoon animation, bold clean dark outlines, crisp vector-quality linework, "
                "flat readable color fills, restrained two-tone cel shading, mildly exaggerated expressive proportions, "
                "mature approachable character design, clear readable silhouettes, natural everyday environments, warm practical lighting, clean 16:9 cinematic composition."
            )
        elif "vital" in cn_low or "capittofin" in cn_low:
            style_dna = (
                "stylized cartoon animation style, bold clean outlines, flat vibrant color fills, exaggerated expressive proportions, "
                "Cartoon Network and Disney TVA aesthetic, clean vector-quality linework, dynamic cartoon poses, bright and energetic visual style."
            )
        elif "longevidad" in cn_low:
            style_dna = (
                "Original 2D medical editorial cartoon with clinical clarity linework: clean medium-weight dark outlines, "
                "simplified geometric shapes, crisp silhouettes, flat color fills, and restrained two-tone cel shading."
            )
        elif "estrategista" in cn_low:
            style_dna = (
                "2D digital editorial cartoon illustration with sand-blue chronicle linework: medium-thick near-black outlines, "
                "slightly irregular hand-drawn contours, simplified geometric forms, flat color fills, sparse interior marks, and limited two-tone cel shading."
            )
        elif "stormscope" in cn_low:
            style_dna = (
                "Cinematic photorealistic 8K broadcast documentary footage, authentic real-world meteorological and historical events, "
                "high-contrast natural lighting, 35mm documentary lens."
            )

    return {
        "style_dna": style_dna,
        "character_dna": character_dna,
        "extras_dna": extras_dna,
        "negative_dna": negative_dna,
        "nomes_prompts": nomes_prompts,
        "texto_unificado_prompts": "\n".join(blocos_unidos),
    }


