def _obter_perfil_padrao_canal_thumb(canal_id="", canal_nome=""):
    """Localiza o perfil completo pré-configurado do canal por ID ou nome."""
    cid = str(canal_id or "").strip()
    if cid in PERFIS_COMPLETOS_CANAIS_THUMB_E_ESTILO:
        return dict(PERFIS_COMPLETOS_CANAIS_THUMB_E_ESTILO[cid])
    cn = (canal_nome or "").strip().lower()
    for k_id, perf in PERFIS_COMPLETOS_CANAIS_THUMB_E_ESTILO.items():
        nm_p = (perf.get("nome_canal") or "").strip().lower()
        if cn and (cn == nm_p or cn in nm_p or nm_p in cn):
            return dict(perf)
    if "gta" in cn or "la une" in cn:
        return dict(PERFIS_COMPLETOS_CANAIS_THUMB_E_ESTILO["a8068857-d56f-4aba-baf3-ea2b7ebda5bb"])
    if "recome" in cn:
        return dict(PERFIS_COMPLETOS_CANAIS_THUMB_E_ESTILO["732eb8c6-56d8-4d30-b0a8-25929aa6614d"])
    if "catch" in cn:
        return dict(PERFIS_COMPLETOS_CANAIS_THUMB_E_ESTILO["cc6b6330-d7b4-4dde-b207-1c2b587f79f3"])
    if "longev" in cn or "longiv" in cn:
        return dict(PERFIS_COMPLETOS_CANAIS_THUMB_E_ESTILO["de8d4d79-9bd8-44db-b967-3086539f667c"])
    if "vital" in cn:
        return dict(PERFIS_COMPLETOS_CANAIS_THUMB_E_ESTILO["af61268b-3d6a-4e64-a6c4-9cd8a9d90cb0"])
    if "estrategista" in cn:
        return dict(PERFIS_COMPLETOS_CANAIS_THUMB_E_ESTILO["4afc5dba-eb73-470e-a0fb-07aa16c7d7a3"])
    if "storm" in cn or "weather" in cn:
        return dict(PERFIS_COMPLETOS_CANAIS_THUMB_E_ESTILO["17681e73-1ab9-412e-93e5-ca12739ece16"])
    if "capittofin" in cn or "cappittofin" in cn or "fin" in cn:
        return dict(PERFIS_COMPLETOS_CANAIS_THUMB_E_ESTILO["8e9fb1f4-0a9b-407c-a67d-c7fcd58f2d10"])
    return {}


def obter_avatar_thumb_canal(canal_id="", canal_nome=""):
    """Retorna a configuração completa do Avatar Principal + Estilo Fixo de Thumbnail do canal (`ch['avatar_thumb']`),
    já pré-carregada com todas as informações oficiais do canal (como sempre é feita a thumb, estilo visual,
    avatar/protagonista, paleta de cores e imagens de referência de estilo anexadas)."""
    db = storage.load()
    ch = None
    if canal_id:
        ch = next((c for c in (db.get("channels") or []) if str(c.get("id")) == str(canal_id)), None)
    if not ch and canal_nome:
        cn_l = canal_nome.strip().lower()
        ch = next((c for c in (db.get("channels") or []) if (c.get("nome") or "").strip().lower() == cn_l), None)
    ch = ch or {}
    cid_real = str(ch.get("id") or canal_id or "geral")
    cnome_real = (ch.get("nome") or canal_nome or "Canal").strip()

    perfil_padrao = _obter_perfil_padrao_canal_thumb(canal_id=cid_real, canal_nome=cnome_real)

    pasta_av = os.path.join(storage.DATA_DIR, "avatars_canais")
    os.makedirs(pasta_av, exist_ok=True)
    slug_cid = re.sub(r"[^a-zA-Z0-9_-]", "_", cid_real)

    cfg_av = dict(ch.get("avatar_thumb") or {})
    arq_padrao = os.path.join(pasta_av, f"{slug_cid}_avatar.png")
    avatar_path = (cfg_av.get("avatar_path") or "").strip().replace("/", os.sep)
    if (not avatar_path or not os.path.exists(avatar_path)) and os.path.exists(arq_padrao):
        avatar_path = arq_padrao

    eh_capitto_recomeco = (
        cid_real == "732eb8c6-56d8-4d30-b0a8-25929aa6614d"
        or "recomec" in cnome_real.lower()
        or "recomeç" in cnome_real.lower()
    )
    if eh_capitto_recomeco and (not avatar_path or not os.path.exists(avatar_path)):
        base_proj = os.path.dirname(storage.DATA_DIR)
        for cand_leo in (
            os.path.join(base_proj, "referencia", "LEONARDO_3D_MASTER.png"),
            os.path.join(pasta_av, "LEONARDO_3D_MASTER.png"),
            r"D:\AUTOMAÇÃO DARK\MAQUINA LEO\FabricaDark\referencia\LEONARDO_3D_MASTER.png",
            r"D:\ARQUIVOS DE VIDEOS\referencia\LEONARDO_3D_MASTER.png",
        ):
            if os.path.exists(cand_leo):
                avatar_path = cand_leo
                break

    # Procura imagens de referência de estilo de Thumbnail anexadas a este canal
    thumbs_estilo_paths = []
    for p_est in (cfg_av.get("thumbs_estilo_paths") or []):
        p_norm = str(p_est or "").replace("/", os.sep)
        if p_norm and os.path.exists(p_norm):
            thumbs_estilo_paths.append(p_norm)
    if not thumbs_estilo_paths:
        for p_glob in sorted(glob.glob(os.path.join(pasta_av, f"{slug_cid}_estilo_thumb_*.png"))):
            if os.path.exists(p_glob):
                thumbs_estilo_paths.append(p_glob)

    # Procura também o personagem [01] do pacote de ingredientes do canal no DarkPlanner como opção rápida
    ref_01_path = ""
    ref_01_nome = ""
    try:
        info_pk = _listar_pacotes_ingredientes_sem_recursao(canal_id=cid_real, canal_nome=cnome_real)
        pk_c = info_pk.get("pack_canal") or {}
        for it in (pk_c.get("items") or []):
            fp_it = (it.get("file_path") or "").replace("/", os.sep)
            if fp_it and os.path.exists(fp_it):
                ref_01_path = fp_it
                ref_01_nome = f"{pk_c.get('name', cnome_real)} — {it.get('tag', '[01]')}"
                break
    except Exception:
        pass

    # Se não tem avatar_path próprio mas o canal tem imagem [01] no pacote de ingredientes e nunca foi removido manualmente, usa [01] como preview/base
    origem_avatar = "anexado"
    if not (avatar_path and os.path.exists(avatar_path)) and ref_01_path and os.path.exists(ref_01_path) and not cfg_av.get("removido_manualmente"):
        avatar_path = ref_01_path
        origem_avatar = "pack_ingredientes_01"

    # Extrai STYLE_DNA e CHARACTER_DNA dos prompts do canal + perfil oficial do canal
    desc_dna_auto = perfil_padrao.get("descricao_avatar") or ""
    style_dna_auto = perfil_padrao.get("style_dna_canal") or (ch.get("estilo_visual") or "").strip()
    estilo_thumb_auto = perfil_padrao.get("estilo_thumb") or ""
    prompt_mestre_thumb_auto = perfil_padrao.get("prompt_mestre_thumb") or ""
    try:
        dp_info = ch.get("dp") or {}
        dna_c = _extrair_style_e_character_dna_canal(dp_info.get("prompts") or [])
        cdna = (dna_c.get("character_dna") or "").strip()
        sdna = (dna_c.get("style_dna") or "").strip()
        if cdna and cdna.upper() != "NENHUM" and not desc_dna_auto:
            desc_dna_auto = cdna[:500]
        if sdna and not style_dna_auto:
            style_dna_auto = sdna[:600]
    except Exception:
        pass

    tem_arq_anexado = bool(avatar_path and os.path.exists(avatar_path))
    default_usar_sempre = bool(tem_arq_anexado or perfil_padrao.get("usar_avatar_por_padrao", False))
    usar_sempre = bool(cfg_av.get("usar_sempre", default_usar_sempre))
    compositar_direto = bool(cfg_av.get("compositar_direto", False))

    # Para o Capitto Recomeço, garante sempre a Direção Visual V3 aprovada pelo usuário (Render 3D, Leonardo #40552A, Key Light Dourada + Ciano/Magenta)
    cfg_desc_av = (cfg_av.get("descricao_avatar") or "").strip()
    cfg_est_th = (cfg_av.get("estilo_thumb") or "").strip()
    if eh_capitto_recomeco:
        if not cfg_desc_av or "minimalist 2d" in cfg_desc_av.lower() or "#40552a" not in cfg_desc_av.lower():
            cfg_desc_av = desc_dna_auto
        if not cfg_est_th or "minimalist 2d" in cfg_est_th.lower() or "no excessive glow" in cfg_est_th.lower():
            cfg_est_th = estilo_thumb_auto

    descricao_avatar = (cfg_desc_av or desc_dna_auto or "").strip()
    estilo_thumb = (cfg_est_th or estilo_thumb_auto or style_dna_auto or "").strip()
    prompt_mestre_thumb = (
        PROMPT_MESTRE_THUMB_CAPITTO_RECOMECO_V3
        if eh_capitto_recomeco
        else (cfg_av.get("prompt_mestre_thumb") or prompt_mestre_thumb_auto or estilo_thumb)
    ).strip()
    paleta_hex = (
        perfil_padrao.get("paleta_hex")
        if eh_capitto_recomeco
        else (cfg_av.get("paleta_hex") or perfil_padrao.get("paleta_hex") or ["#0F172A", "#FFD400", "#38BDF8", "#FFFFFF"])
    )
    cor_destaque_padrao = (
        perfil_padrao.get("cor_destaque_padrao")
        if eh_capitto_recomeco
        else (cfg_av.get("cor_destaque") or perfil_padrao.get("cor_destaque_padrao") or "#FFD400")
    )

    def _img_para_data_uri_mini(caminho_img, max_wh=(160, 160)):
        if not caminho_img or not os.path.exists(caminho_img):
            return ""
        try:
            import base64 as _b64_m
            import io as _io_m
            from PIL import Image as _ImgM
            im_m = _ImgM.open(caminho_img).convert("RGBA")
            im_m.thumbnail(max_wh)
            buf_m = _io_m.BytesIO()
            im_m.save(buf_m, format="PNG")
            return "data:image/png;base64," + _b64_m.b64encode(buf_m.getvalue()).decode("ascii")
        except Exception:
            ts_m = int(os.path.getmtime(caminho_img) * 1000)
            return f"/api/antigravity/thumb-viral-img?path={urllib.parse.quote(caminho_img.replace(os.sep, '/'))}&t={ts_m}"

    # Personagens de Referência Opcionais para os Prompts do Vídeo (suporta até 5 personagens: [01] a [05])
    arq_pv_padrao = os.path.join(pasta_av, f"{slug_cid}_personagem_video.png")
    raw_pvs = list(cfg_av.get("personagens_video") or [])
    if not raw_pvs and not cfg_av.get("personagem_video_removido"):
        pv_legado = (cfg_av.get("personagem_video_path") or "").strip().replace("/", os.sep)
        if (not pv_legado or not os.path.exists(pv_legado)) and os.path.exists(arq_pv_padrao):
            pv_legado = arq_pv_padrao
        if pv_legado and os.path.exists(pv_legado):
            raw_pvs = [{
                "slot": 1,
                "nome": (cfg_av.get("personagem_video_nome") or os.path.basename(pv_legado)).strip(),
                "path": pv_legado,
                "dna": (cfg_av.get("personagem_video_dna") or descricao_avatar or "").strip(),
            }]

    personagens_video_norm = []
    for item_pv in raw_pvs[:5]:
        if not isinstance(item_pv, dict):
            continue
        p_pv = str(item_pv.get("path") or "").strip().replace("/", os.sep)
        if not p_pv or not os.path.exists(p_pv):
            continue
        slot_n = len(personagens_video_norm) + 1
        nm_pv = (item_pv.get("nome") or os.path.basename(p_pv) or f"personagem_{slot_n}.png").strip()
        dna_pv = (item_pv.get("dna") or cfg_av.get("personagem_video_dna") or descricao_avatar or "").strip()
        personagens_video_norm.append({
            "slot": slot_n,
            "tag": f"[{slot_n:02d}]",
            "nome": nm_pv,
            "path": p_pv.replace(os.sep, "/"),
            "url": _img_para_data_uri_mini(p_pv, (120, 120)),
            "dna": dna_pv,
        })

    tem_personagem_video = len(personagens_video_norm) > 0
    personagem_video_ativo = bool(cfg_av.get("personagem_video_ativo", False) and tem_personagem_video)
    pv_prim = personagens_video_norm[0] if tem_personagem_video else {}
    personagem_video_path = (pv_prim.get("path") or "").replace("/", os.sep) if tem_personagem_video else ""
    personagem_video_url = pv_prim.get("url") or ""
    personagem_video_nome = pv_prim.get("nome") or ""
    personagem_video_dna = " | ".join(
        f"{p['tag']} ({p['nome']}): {p['dna']}" for p in personagens_video_norm if p.get("dna")
    ) or (pv_prim.get("dna") or descricao_avatar or "")

    avatar_url = _img_para_data_uri_mini(avatar_path, (140, 140)) if tem_arq_anexado else ""
    ref_01_url = _img_para_data_uri_mini(ref_01_path, (140, 140)) if (ref_01_path and os.path.exists(ref_01_path)) else ""
    thumbs_estilo_urls = [
        _img_para_data_uri_mini(p, (200, 112))
        for p in thumbs_estilo_paths
        if os.path.exists(p)
    ]

    return {
        "ok": True,
        "canal_id": cid_real,
        "canal_nome": cnome_real,
        "formato_midia": perfil_padrao.get("formato_midia") or "",
        "sem_texto_na_thumb": bool(perfil_padrao.get("sem_texto_na_thumb", False)),
        "resumo_canal": perfil_padrao.get("resumo_canal") or f"Canal {cnome_real} — Estilo visual e Thumbnail sincronizados.",
        "tem_avatar": tem_arq_anexado,
        "tem_avatar_dna": bool(tem_arq_anexado or descricao_avatar),
        "origem": origem_avatar if tem_arq_anexado else ("dna_canal" if descricao_avatar else ""),
        "usar_sempre": usar_sempre,
        "sempre_incluir": usar_sempre,
        "ativo": bool(usar_sempre and (tem_arq_anexado or descricao_avatar) and not perfil_padrao.get("sem_texto_na_thumb")),
        "compositar_direto": compositar_direto,
        "compositar_canto": compositar_direto,
        "avatar_path": avatar_path.replace(os.sep, "/") if tem_arq_anexado else "",
        "avatar_url": avatar_url,
        "url_preview": avatar_url,
        "nome_avatar": cfg_av.get("nome_avatar") or (os.path.basename(avatar_path) if tem_arq_anexado else ("LEONARDO_3D_MASTER.png" if eh_capitto_recomeco else f"Avatar Oficial ({cnome_real})")),
        "referencia_master_avatar": perfil_padrao.get("referencia_master_avatar") or "",
        "descricao_avatar": descricao_avatar,
        "estilo_thumb": estilo_thumb,
        "prompt_mestre_thumb": prompt_mestre_thumb,
        "style_dna_canal": style_dna_auto,
        "paleta_hex": paleta_hex,
        "cor_destaque": cor_destaque_padrao,
        "thumbs_estilo_paths": [p.replace(os.sep, "/") for p in thumbs_estilo_paths],
        "thumbs_estilo_urls": thumbs_estilo_urls,
        "total_thumbs_estilo": len(thumbs_estilo_urls),
        "ref_01_disponivel": bool(ref_01_path and os.path.exists(ref_01_path)),
        "ref_01_path": ref_01_path.replace(os.sep, "/") if ref_01_path else "",
        "ref_01_url": ref_01_url,
        "ref_01_preview_url": ref_01_url,
        "ref_01_nome": ref_01_nome,
        "tem_personagem_video": tem_personagem_video,
        "personagem_video_ativo": personagem_video_ativo,
        "personagem_video_path": personagem_video_path.replace(os.sep, "/") if tem_personagem_video else "",
        "personagem_video_url": personagem_video_url,
        "personagem_video_nome": personagem_video_nome,
        "personagem_video_dna": personagem_video_dna,
        "personagens_video": personagens_video_norm,
        "total_personagens_video": len(personagens_video_norm),
        "max_personagens_video": 5,
    }


