                        prompts_filtrados = [
                            p for p in prompts_atuais
                            if isinstance(p, dict) and not str(p.get("id") or "").startswith("gta_fr_")
                        ]
                        dp_bloco["prompts"] = list(PROMPTS_OFICIAIS_GTA_A_LA_UNE_FR) + prompts_filtrados
