                    av_gta["paleta_hex"] = perf_gta.get("paleta_hex") or ["#0A0D18", "#FF2E93", "#00E5FF", "#FF9500", "#FFD400"]
                    av_gta["cor_destaque"] = perf_gta.get("cor_destaque_padrao") or "#FFD400"
