def _buscar_wikipedia_api(termo, limit=3):
    """Busca imagens e vídeos documentais diretamente na API da Wikipédia/Wikimedia Commons."""
    if not termo:
        return []
    out = []
    try:
        r = requests.get(
            "https://en.wikipedia.org/w/api.php",
            params={
                "action": "query",
                "generator": "search",
                "gsrsearch": str(termo).strip()[:80],
                "gsrlimit": max(1, min(6, int(limit))),
                "prop": "pageimages|info",
                "piprop": "original|thumbnail",
                "pithumbsize": 1280,
                "inprop": "url",
                "format": "json",
            },
            headers={"User-Agent": "FabricaDarkStudio/2.0 (Documentary Research)"},
            timeout=5,
        )
        if r.ok:
            pages = ((r.json() or {}).get("query") or {}).get("pages") or {}
            for pid, pg in pages.items():
                orig = ((pg.get("original") or {}).get("source") or "").strip()
                thumb = ((pg.get("thumbnail") or {}).get("source") or orig).strip()
                dl = orig or thumb
                if not dl or dl.lower().endswith(".svg"):
                    continue
                out.append({
                    "id_unico": f"wiki_page:{pid}",
                    "fonte": "Wikipédia / Wikimedia (Tier 3)",
                    "banco_id": "wikipedia",
                    "tier": "Tier 3 (Wikipédia)",
                    "tipo": "foto",
                    "preview": thumb or dl,
                    "download": dl,
                    "url": dl,
                    "titulo": pg.get("title") or termo,
                    "pagina": pg.get("fullurl") or f"https://en.wikipedia.org/?curid={pid}",
                    "licenca": "CC BY-SA / Public Domain (Wikipédia)",
                    "autor": "Wikipedia Contributors",
                })
                if len(out) >= limit:
                    break
    except Exception:
        pass
    return out


def _buscar_google_earth_satelite(termo, limit=2):
    """Busca imagens de satélite/Globo estilo Google Earth (via NASA Earth Observatory / Landsat)."""
    if not termo:
        return []
    out = []
    q_sat = f"{termo} satellite earth aerial"
    try:
        for r in _buscar_nasa_api(q_sat, limit=limit):
            r_ge = dict(r)
            r_ge["id_unico"] = f"google_earth:{r.get('id_unico') or r.get('url') or termo}"
            r_ge["fonte"] = "Google Earth / Satélite (Tier 1)"
            r_ge["banco_id"] = "google_earth"
            r_ge["tier"] = "Tier 1 (Google Earth / Satélite)"
            r_ge["pagina"] = f"https://earth.google.com/web/search/{requests.utils.quote(termo)}"
            out.append(r_ge)
    except Exception:
        pass
    return out


