def _chave_canal_historico(canal_id="", canal_nome=""):
    """Normaliza a chave canônica do canal para cruzar todos os vídeos anteriores do mesmo canal."""
    cid = str(canal_id or "").strip()
    cn = str(canal_nome or "").strip().lower()
    if cid == "a8068857-d56f-4aba-baf3-ea2b7ebda5bb" or "gta" in cn or "à la une" in cn or "a la une" in cn:
        return "a8068857-d56f-4aba-baf3-ea2b7ebda5bb"
    if cid == "0d5d4e55-c8e2-4a45-8754-2c6eb4f9bf92" or "stormscope" in cn or "severe weather" in cn:
        return "0d5d4e55-c8e2-4a45-8754-2c6eb4f9bf92"
    if cid:
        return cid
    if cn:
        import re as _re_ck
        return "nome:" + _re_ck.sub(r"[^a-z0-9]+", "_", cn).strip("_")[:50]
    return "geral_video_real"


def _normalizar_titulo_comparacao(t):
    import re as _re_tc
    return _re_tc.sub(r"[^a-zA-ZÀ-ÿ0-9]+", "", str(t or "").lower())[:64]


def _extrair_frame_bytes_para_ia(caminho_arq):
    """Extrai bytes JPEG/PNG de uma imagem ou do 1º segundo de um vídeo .mp4 para análise visual e dHash."""
    if not caminho_arq or not os.path.isfile(caminho_arq):
        return None, "image/jpeg"
    low = caminho_arq.lower()
    if low.endswith((".jpg", ".jpeg", ".png", ".webp")):
        try:
            with open(caminho_arq, "rb") as f:
                b = f.read()
            if b and len(b) > 500:
                mime = "image/png" if low.endswith(".png") else ("image/webp" if low.endswith(".webp") else "image/jpeg")
                return b, mime
        except Exception:
            return None, "image/jpeg"
    if low.endswith((".mp4", ".mov", ".webm", ".mkv")):
        import shutil as _sh_fr
        import subprocess as _sp_fr
        ff_bin = _sh_fr.which("ffmpeg")
        if not ff_bin:
            try:
                import imageio_ffmpeg
                ff_bin = imageio_ffmpeg.get_ffmpeg_exe()
            except Exception:
                ff_bin = "ffmpeg"
        for ss_pos in ("1.0", "0.0"):
            try:
                r = _sp_fr.run(
                    [
                        ff_bin, "-v", "error", "-ss", ss_pos, "-i", caminho_arq,
                        "-frames:v", "1", "-vf", "scale='min(640,iw)':-2",
                        "-f", "image2pipe", "-vcodec", "mjpeg", "-q:v", "5", "-",
                    ],
                    capture_output=True,
                    timeout=6,
                    creationflags=0x08000000 if os.name == "nt" else 0,
                )
                if r.returncode == 0 and r.stdout and len(r.stdout) > 500:
                    return r.stdout, "image/jpeg"
            except Exception:
                pass
    return None, "image/jpeg"


def _calcular_dhash_visual_bytes(img_bytes):
    """Calcula dHash perceptual de 64 bits (16 hex chars) a partir de bytes de imagem."""
    if not img_bytes:
        return ""
    try:
        from io import BytesIO
        from PIL import Image
        resamp = getattr(Image, "Resampling", Image).BILINEAR
        im = Image.open(BytesIO(img_bytes)).convert("L").resize((9, 8), resamp)
        px = list(im.getdata())
        bits = 0
        for row in range(8):
            off = row * 9
            for col in range(8):
                bits = (bits << 1) | (1 if px[off + col] > px[off + col + 1] else 0)
        return f"{bits:016x}"
    except Exception:
        return ""


def _calcular_dhash_visual_arquivo(caminho_arq):
    """Calcula dHash perceptual de 64 bits para qualquer imagem ou vídeo (.mp4) em disco."""
    b, _ = _extrair_frame_bytes_para_ia(caminho_arq)
    return _calcular_dhash_visual_bytes(b)


def _dhash_repetido(h1, conjunto_hashes, max_dist=4):
    """Verifica se um dHash visual é idêntico ou quase idêntico (distância de Hamming <= max_dist) a algum já usado."""
    if not h1 or not conjunto_hashes:
        return False
    if h1 in conjunto_hashes:
        return True
    try:
        v1 = int(h1, 16)
        for h2 in conjunto_hashes:
            if not h2:
                continue
            if (v1 ^ int(h2, 16)).bit_count() <= max_dist:
                return True
    except Exception:
        pass
    return False


def _resolver_canal_de_vid_ou_pasta(vid="", titulo="", pasta_midias="", canal_id="", canal_nome=""):
    """Descobre automaticamente `canal_id` e `canal_nome` a partir do `vid`, título ou manifesto do projeto."""
    cid = str(canal_id or "").strip()
    cnome = str(canal_nome or "").strip()
    if cid and cnome and cnome.lower() not in ("canal", "canal darkplanner"):
        return cid, cnome
    try:
        db = storage.load()
        if vid:
            v_obj = storage.find(db.get("videos") or [], vid) or {}
            cid = cid or str(v_obj.get("channel_id") or v_obj.get("canal_id") or "").strip()
        if not cid and titulo:
            tnorm = _normalizar_titulo_comparacao(titulo)
            for v_it in (db.get("videos") or []):
                if _normalizar_titulo_comparacao(v_it.get("titulo")) == tnorm:
                    cid = str(v_it.get("channel_id") or v_it.get("canal_id") or "").strip()
                    break
        if pasta_midias:
            p_pai = os.path.dirname(os.path.abspath(pasta_midias))
            p_res = os.path.join(p_pai, "00_RESUMO_PROJETO_CRIADO.json")
            if os.path.exists(p_res):
                with open(p_res, "r", encoding="utf-8") as fr:
                    d_res = json.load(fr) or {}
                cid = cid or str(d_res.get("canal_id") or "").strip()
                cnome = cnome or str(d_res.get("canal_nome") or "").strip()
        if cid and (not cnome or cnome.lower() in ("canal", "canal darkplanner")):
            ch_obj = next((c for c in (db.get("channels") or []) if str(c.get("id") or "") == cid), {})
            cnome = str(ch_obj.get("nome") or cnome).strip()
        elif cnome and not cid:
            cn_l = cnome.lower()
            for c in (db.get("channels") or []):
                if (c.get("nome") or "").strip().lower() == cn_l:
                    cid = str(c.get("id") or "").strip()
                    break
    except Exception:
        pass
    return cid, cnome


def obter_historico_midias_canal(canal_id="", canal_nome="", excluir_titulo="", excluir_pasta="", pasta_atual=""):
    """Olha TODOS os vídeos anteriores do canal (tanto no registro persistente `historico_midias_canais.json`
    quanto varrendo as pastas de projetos anteriores em disco e `db['videos']`) para garantir ZERO repetição
    da mesma imagem ou vídeo real entre vídeos diferentes do mesmo canal."""
    import hashlib

    cid, cnome = _resolver_canal_de_vid_ou_pasta(canal_id=canal_id, canal_nome=canal_nome)
    ch_canal = _chave_canal_historico(cid, cnome)
    t_excl = _normalizar_titulo_comparacao(excluir_titulo)
    pasta_ref_excl = excluir_pasta or pasta_atual or ""
    p_excl_set = set()
    if pasta_ref_excl:
        p_abs = os.path.abspath(pasta_ref_excl)
        p_excl_set.add(p_abs)
        p_excl_set.add(os.path.abspath(os.path.join(p_abs, "midias")))
        if os.path.basename(p_abs).lower() == "midias":
            p_excl_set.add(os.path.abspath(os.path.dirname(p_abs)))

    chaves_usadas = set()
    md5s_usados = set()
    dhashes_usados = set()
    titulos_anteriores = set()

    def _add_url_ou_chave(val):
        s = str(val or "").strip()
        if not s:
            return
        chaves_usadas.add(s.lower())
        if s.startswith("http"):
            chaves_usadas.add(s.split("?")[0].split("#")[0].strip().lower())
            ch_m = _chave_unica_midia({"url": s, "download": s})
            if ch_m:
                chaves_usadas.add(ch_m)

    # 1. Lê o arquivo persistente `historico_midias_canais.json`
    with _LOCK_HIST_MIDIAS:
        if os.path.exists(HISTORICO_MIDIAS_CANAIS_PATH):
            try:
                with open(HISTORICO_MIDIAS_CANAIS_PATH, "r", encoding="utf-8") as fh:
                    dados_h = json.load(fh) or {}
                canal_reg = (dados_h.get("canais") or {}).get(ch_canal) or {}
                for vid_entry in (canal_reg.get("videos") or []):
                    t_v = str(vid_entry.get("titulo") or "").strip()
                    p_v = str(vid_entry.get("pasta_midias") or "").strip()
                    if t_excl and _normalizar_titulo_comparacao(t_v) == t_excl:
                        continue
                    if p_excl_set and p_v and os.path.abspath(p_v) in p_excl_set:
                        continue
                    if t_v:
                        titulos_anteriores.add(t_v)
                    for ch_it in (vid_entry.get("chaves") or []):
                        _add_url_ou_chave(ch_it)
                    for m_it in (vid_entry.get("md5s") or []):
                        if m_it:
                            md5s_usados.add(str(m_it).lower())
                    for dh_it in (vid_entry.get("dhashes") or []):
                        if dh_it:
                            dhashes_usados.add(str(dh_it).lower())
            except Exception:
                pass

    # 2. Varre também db["videos"] e pastas de vídeos já criados do mesmo canal (retrocompatível com vídeos antigos!)
    try:
        db = storage.load()
        for v_db in (db.get("videos") or []):
            v_cid = str(v_db.get("channel_id") or v_db.get("canal_id") or "").strip()
            if _chave_canal_historico(v_cid, "") != ch_canal:
                continue
            v_tit = str(v_db.get("titulo") or v_db.get("id") or "").strip()
            if t_excl and _normalizar_titulo_comparacao(v_tit) == t_excl:
                continue
            cenas_v = v_db.get("cenas") or []
            if not cenas_v:
                continue
            teve_midia = False
            for c_it in cenas_v:
                m_it = (c_it or {}).get("midia")
                if isinstance(m_it, dict):
                    ch_u = _chave_unica_midia(m_it)
                    if ch_u:
                        chaves_usadas.add(ch_u)
                        teve_midia = True
                    _add_url_ou_chave(m_it.get("download") or m_it.get("url"))
                    if m_it.get("md5"):
                        md5s_usados.add(str(m_it["md5"]).lower())
            if teve_midia and v_tit:
                titulos_anteriores.add(v_tit)
    except Exception:
        pass

    try:
        pastas_raiz = []
        base_dl = obter_pasta_downloads_darkplanner()
        for sub in ("studio", "creator"):
            p_s = os.path.join(base_dl, sub)
            if os.path.isdir(p_s):
                pastas_raiz.append(p_s)
        p_av_root = os.path.dirname(_obter_pasta_arquivos_video("teste_ref_dir", criar=False))
        if p_av_root and os.path.isdir(p_av_root):
            pastas_raiz.append(p_av_root)

        for raiz in pastas_raiz:
            for nm_dir in os.listdir(raiz):
                p_proj = os.path.join(raiz, nm_dir)
                if not os.path.isdir(p_proj):
                    continue
                if p_excl_set and (os.path.abspath(p_proj) in p_excl_set or os.path.abspath(os.path.join(p_proj, "midias")) in p_excl_set):
                    continue
                if t_excl and _normalizar_titulo_comparacao(nm_dir) == t_excl:
                    continue
                p_res = os.path.join(p_proj, "00_RESUMO_PROJETO_CRIADO.json")
                if not os.path.exists(p_res):
                    continue
                try:
                    with open(p_res, "r", encoding="utf-8") as fr:
                        d_r = json.load(fr) or {}
                except Exception:
                    continue
                proj_ch = _chave_canal_historico(d_r.get("canal_id") or "", d_r.get("canal_nome") or "")
                if proj_ch != ch_canal:
                    continue
                tit_ant = str(d_r.get("titulo") or nm_dir).strip()
                if t_excl and _normalizar_titulo_comparacao(tit_ant) == t_excl:
                    continue
                titulos_anteriores.add(tit_ant)

                p_cjson = os.path.join(p_proj, "05_MIDIAS_REAIS_POR_CENA.json")
                if os.path.exists(p_cjson):
                    try:
                        with open(p_cjson, "r", encoding="utf-8") as fc:
                            lst_c = json.load(fc) or []
                        for c_old in lst_c:
                            m_old = (c_old or {}).get("midia")
                            if isinstance(m_old, dict):
                                ch_o = _chave_unica_midia(m_old)
                                if ch_o:
                                    chaves_usadas.add(ch_o)
                                _add_url_ou_chave(m_old.get("download") or m_old.get("url"))
                                if m_old.get("md5"):
                                    md5s_usados.add(str(m_old["md5"]).lower())
                    except Exception:
                        pass

                p_mdir = os.path.join(p_proj, "midias")
                if os.path.isdir(p_mdir):
                    for fn_m in os.listdir(p_mdir):
                        if not fn_m.lower().endswith((".mp4", ".jpg", ".jpeg", ".png", ".webp")):
                            continue
                        fp_m = os.path.join(p_mdir, fn_m)
                        try:
                            sz_m = os.path.getsize(fp_m)
                            if sz_m < 4000:
                                continue
                            with open(fp_m, "rb") as fm_in:
                                if sz_m <= 15 * 1024 * 1024:
                                    md5s_usados.add(hashlib.md5(fm_in.read()).hexdigest())
                                else:
                                    mm = hashlib.md5()
                                    mm.update(fm_in.read(2 * 1024 * 1024))
                                    fm_in.seek(sz_m // 2)
                                    mm.update(fm_in.read(2 * 1024 * 1024))
                                    md5s_usados.add(mm.hexdigest())
                        except Exception:
                            pass
    except Exception:
        pass

    return {
        "chave_canal": ch_canal,
        "canal_id": cid,
        "canal_nome": cnome,
        "chaves_usadas": chaves_usadas,
        "md5s_usados": md5s_usados,
        "dhashes_usados": dhashes_usados,
        "videos_anteriores_analisados": len(titulos_anteriores),
        "titulos_anteriores": sorted(titulos_anteriores),
        "total_midias_bloqueadas": len(chaves_usadas) + len(md5s_usados),
    }


def registrar_midias_usadas_no_canal(
    canal_id="",
    canal_nome="",
    titulo_projeto="",
    pasta_midias="",
    cenas_reais=None,
    arquivos_ordenados=None,
):
    """Registra permanentemente em `data/historico_midias_canais.json` todas as fotos e vídeos usados neste projeto
    (chaves de URL/ID, hashes MD5 binários e dHashes visuais) para que NUNCA se repitam nos próximos vídeos do canal."""
    import hashlib

    cid, cnome = _resolver_canal_de_vid_ou_pasta(
        titulo=titulo_projeto,
        pasta_midias=pasta_midias,
        canal_id=canal_id,
        canal_nome=canal_nome,
    )
    ch_canal = _chave_canal_historico(cid, cnome)
    tit_limpo = str(titulo_projeto or os.path.basename(os.path.dirname(pasta_midias or "")) or "Video").strip()
    tnorm = _normalizar_titulo_comparacao(tit_limpo)

    chaves_proj = set()
    md5s_proj = set()
    dhashes_proj = set()

    for c_it in (cenas_reais or []):
        m = (c_it or {}).get("midia")
        if isinstance(m, dict):
            ch_u = _chave_unica_midia(m)
            if ch_u:
                chaves_proj.add(ch_u)
            for kid in ("id_unico", "id"):
                idv = str(m.get(kid) or "").strip().lower()
                if idv:
                    chaves_proj.add(idv)
            for ku in ("download", "download_url", "url", "page_url", "src"):
                uv = str(m.get(ku) or "").strip()
                if uv.startswith("http"):
                    chaves_proj.add(uv.lower())
                    chaves_proj.add(uv.split("?")[0].split("#")[0].strip().lower())
            if m.get("md5"):
                md5s_proj.add(str(m["md5"]).lower())
            if m.get("dhash"):
                dhashes_proj.add(str(m["dhash"]).lower())

    lista_arqs = list(arquivos_ordenados or [])
    if not lista_arqs and pasta_midias and os.path.isdir(pasta_midias):
        lista_arqs = [
            os.path.join(pasta_midias, f)
            for f in sorted(os.listdir(pasta_midias))
            if f.lower().endswith((".mp4", ".jpg", ".jpeg", ".png", ".webp"))
        ]

    # Calcula MD5 de todos os arquivos e dHash visual (até 40 cenas em paralelo leve ou direto p/ fotos)
    for idx_a, fp in enumerate(lista_arqs):
        if not fp or not os.path.isfile(fp):
            continue
        try:
            sz = os.path.getsize(fp)
            if sz < 512:
                continue
            with open(fp, "rb") as fi:
                if sz <= 15 * 1024 * 1024:
                    md5s_proj.add(hashlib.md5(fi.read()).hexdigest())
                else:
                    mm = hashlib.md5()
                    mm.update(fi.read(2 * 1024 * 1024))
                    fi.seek(sz // 2)
                    mm.update(fi.read(2 * 1024 * 1024))
                    md5s_proj.add(mm.hexdigest())
            if fp.lower().endswith((".jpg", ".jpeg", ".png", ".webp")) or idx_a < 24:
                dh = _calcular_dhash_visual_arquivo(fp)
                if dh:
                    dhashes_proj.add(dh)
        except Exception:
            pass

    if not chaves_proj and not md5s_proj:
        return {"ok": False, "motivo": "Nenhuma mídia para registrar"}

    with _LOCK_HIST_MIDIAS:
        dados = {"atualizado_em": time.time(), "canais": {}}
        if os.path.exists(HISTORICO_MIDIAS_CANAIS_PATH):
            try:
                with open(HISTORICO_MIDIAS_CANAIS_PATH, "r", encoding="utf-8") as fh:
                    dados = json.load(fh) or dados
            except Exception:
                dados = {"atualizado_em": time.time(), "canais": {}}
        canais_map = dados.setdefault("canais", {})
        c_entry = canais_map.setdefault(ch_canal, {"canal_id": cid, "canal_nome": cnome, "videos": []})
        if cid:
            c_entry["canal_id"] = cid
        if cnome:
            c_entry["canal_nome"] = cnome

        vids_exist = [
            v for v in (c_entry.get("videos") or [])
            if _normalizar_titulo_comparacao(v.get("titulo")) != tnorm
        ]
        vids_exist.append({
            "titulo": tit_limpo,
            "pasta_midias": os.path.abspath(pasta_midias) if pasta_midias else "",
            "registrado_em": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
            "total_chaves": len(chaves_proj),
            "total_md5s": len(md5s_proj),
            "chaves": sorted(chaves_proj)[:600],
            "md5s": sorted(md5s_proj)[:600],
            "dhashes": sorted(dhashes_proj)[:400],
        })
        c_entry["videos"] = vids_exist[-250:]
        dados["atualizado_em"] = time.time()
        os.makedirs(os.path.dirname(HISTORICO_MIDIAS_CANAIS_PATH), exist_ok=True)
        with open(HISTORICO_MIDIAS_CANAIS_PATH, "w", encoding="utf-8") as fw:
            json.dump(dados, fw, indent=2, ensure_ascii=False)

    return {
        "ok": True,
        "chave_canal": ch_canal,
        "videos_registrados_no_canal": len(c_entry["videos"]),
        "chaves_registradas": len(chaves_proj),
        "md5s_registrados": len(md5s_proj),
        "dhashes_registrados": len(dhashes_proj),
    }


