            def _view_pauta_marcar_tema():
                from core import pauta as _pa_m
                from core import storage as _st_m
                d = request.get_json(silent=True) or {}
                cid = (d.get("canal") or d.get("canal_id") or d.get("channel_id") or d.get("canal_nome") or "").strip()
                titulo = (d.get("titulo") or "").strip()
                acao = (d.get("acao") or "concluir").strip().lower()
                if not titulo:
                    return jsonify({"ok": False, "erro": "Informe o título do tema."}), 400
                t_norm = re.sub(r"\W+", "", _pa_m._sem_acentos(titulo.lower()))
                with _st_m.Tx() as db_m:
                    ch = _st_m.find(db_m["channels"], cid)
                    if not ch and cid:
                        ch = next((c for c in db_m.get("channels", []) if (c.get("nome") or "").strip().lower() == cid.lower()), None)
                    if not ch and db_m.get("channels"):
                        ch = db_m["channels"][0]
                    if not ch:
                        return jsonify({"ok": False, "erro": "Canal não encontrado."}), 404
                    cid_real = str(ch.get("id") or cid)
                    cfg_s = db_m.setdefault("settings", {})
                    mapa_conc = cfg_s.setdefault("temas_concluidos_por_canal", {})
                    mapa_ocul = cfg_s.setdefault("temas_ocultos_por_canal", {})
                    concluidos = list(ch.get("temas_concluidos_manual") or [])
                    for x_extra in (mapa_conc.get(cid_real) or []):
                        if x_extra and not any(re.sub(r"\W+", "", _pa_m._sem_acentos(x.lower())) == re.sub(r"\W+", "", _pa_m._sem_acentos(x_extra.lower())) for x in concluidos):
                            concluidos.append(x_extra)
                    ocultos = list(ch.get("temas_ocultos_manual") or [])
                    for x_oc in (mapa_ocul.get(cid_real) or []):
                        if x_oc and not any(re.sub(r"\W+", "", _pa_m._sem_acentos(x.lower())) == re.sub(r"\W+", "", _pa_m._sem_acentos(x_oc.lower())) for x in ocultos):
                            ocultos.append(x_oc)
                    if acao in ("concluir", "feito"):
                        if not any(re.sub(r"\W+", "", _pa_m._sem_acentos(x.lower())) == t_norm for x in concluidos):
                            concluidos.append(titulo)
                    elif acao in ("reabrir", "desmarcar"):
                        concluidos = [x for x in concluidos if re.sub(r"\W+", "", _pa_m._sem_acentos(x.lower())) != t_norm]
                        ocultos = [x for x in ocultos if re.sub(r"\W+", "", _pa_m._sem_acentos(x.lower())) != t_norm]
                    elif acao in ("ocultar", "apagar", "excluir"):
                        if not any(re.sub(r"\W+", "", _pa_m._sem_acentos(x.lower())) == t_norm for x in ocultos):
                            ocultos.append(titulo)
                        if not any(re.sub(r"\W+", "", _pa_m._sem_acentos(x.lower())) == t_norm for x in concluidos):
                            concluidos.append(titulo)
                    elif acao == "mostrar_todos":
                        ocultos = []
                    ch["temas_concluidos_manual"] = concluidos
                    ch["temas_ocultos_manual"] = ocultos
                    mapa_conc[cid_real] = list(concluidos)
                    mapa_ocul[cid_real] = list(ocultos)
                return jsonify({"ok": True, "acao": acao, "titulo": titulo, "total_concluidos": len(concluidos)})


            def _view_pauta_ver():
                import datetime as _dt_pv
                from core import claude as _cl_pv
                from core import pauta as _pa_pv
                from core import storage as _st_pv
                db = _st_pv.load()
                if _pa_pv.sincronizar_perfis_editoriais_no_banco(db):
                    with _st_pv.Tx() as db_sync:
                        _pa_pv.sincronizar_perfis_editoriais_no_banco(db_sync)
                    db = _st_pv.load()
                cid = request.args.get("canal") or ((db["channels"] or [{}])[0]).get("id")
                ch = _st_pv.find(db["channels"], cid)
                if not ch:
                    return jsonify({"erro": "Cadastre um canal primeiro."}), 400
                perfil_canal = _pa_pv.obter_perfil_editorial_canal(ch)
                atual = (db.get("pautas") or {}).get(cid)
                hoje = _dt_pv.date.today().isoformat()
                pediu_novo = bool(request.args.get("novo"))
                atual_inst, mudou_inst = _pa_pv.garantir_pauta_instantanea_hoje(
                    db,
                    ch,
                    atual=atual,
                    perfil=perfil_canal,
                    forcar_rotacao=pediu_novo,
                )
                if mudou_inst and atual_inst:
                    with _st_pv.Tx() as db_p:
                        db_p.setdefault("pautas", {})[cid] = atual_inst
                    atual = atual_inst
                else:
                    atual = atual_inst or atual
                if pediu_novo and _cl_pv.tem_ia():
                    def _bg_pauta(cid_local=cid, ch_local=ch):
                        try:
                            db_fresh = _st_pv.load()
                            ch_fresh = _st_pv.find(db_fresh["channels"], cid_local) or ch_local
                            r_new = _pa_pv.gerar(db_fresh, ch_fresh)
                            with _st_pv.Tx() as db2:
                                db2.setdefault("pautas", {})[cid_local] = r_new
                        except Exception:
                            pass
                    threading.Thread(target=_bg_pauta, daemon=True).start()
                atual_enriq, perfil_enriq, diag_canal = _pa_pv.enriquecer_pauta_e_diagnostico_canal(db, ch, atual, perfil_canal)
                return jsonify({
                    "canal": cid,
                    "pauta": _cl_pv.corrigir_mojibake_ptbr(atual_enriq or atual),
                    "perfil_editorial": _cl_pv.corrigir_mojibake_ptbr(perfil_enriq),
                    "diagnostico_canal": _cl_pv.corrigir_mojibake_ptbr(diag_canal),
                    "hoje": hoje,
                    "rodando": False,
                    "erro": "",
                    "tem_ia": _cl_pv.tem_ia(),
                })

