def _resolver_contexto_projeto_chat_op(dados):
    """Localiza automaticamente o projeto ativo/recente (na memória, no disco do DarkPlanner Studio, em D:\\ARQUIVOS DE VIDEOS ou no banco)
    para que o Chat Operacional do aplicativo consiga regularizar qualquer detalhe com 1 comando."""
    import glob

    d = dados if isinstance(dados, dict) else {}
    sp_id = str(d.get("sp_id") or d.get("projeto_id") or "").strip()
    nome_proj = str(d.get("nome_projeto") or d.get("titulo") or "").strip()
    canal_id = str(d.get("canal_id") or "").strip()
    canal_nome = str(d.get("canal_nome") or "").strip()
    vid = str(d.get("vid") or "").strip()
    job_id = str(d.get("job_id") or "").strip()
    srt_texto_req = str(d.get("srt_texto") or "").strip()
    chat_modelo_opcao = str(d.get("chat_modelo_opcao") or "flash_high").strip()

    tarefa_mem = None
    with _LOCK_ETAPA7_DP:
        for chv in (sp_id, nome_proj.lower()):
            if chv and chv in _TAREFAS_ETAPA7_DP:
                tarefa_mem = _TAREFAS_ETAPA7_DP[chv]
                break
        if tarefa_mem is None and _TAREFAS_ETAPA7_DP:
            tarefa_mem = max(_TAREFAS_ETAPA7_DP.values(), key=lambda x: float(x.get("atualizado_em") or 0))

    if tarefa_mem:
        sp_id = sp_id or str(tarefa_mem.get("sp_id") or "")
        nome_proj = nome_proj or str(tarefa_mem.get("nome_projeto") or "")
        canal_id = canal_id or str(tarefa_mem.get("canal_id") or "")
        canal_nome = canal_nome or str(tarefa_mem.get("canal_nome") or "")
        vid = vid or str(tarefa_mem.get("vid") or "")
        job_id = job_id or str(tarefa_mem.get("job_id") or "")
        chat_modelo_opcao = str(d.get("chat_modelo_opcao") or tarefa_mem.get("chat_modelo_opcao") or chat_modelo_opcao)

    pasta_creator = str((tarefa_mem or {}).get("pasta_creator") or "").strip()
    pasta_arquivos_video = str((tarefa_mem or {}).get("pasta_arquivos_video") or "").strip()
    mensagem_chat = str((tarefa_mem or {}).get("mensagem_chat") or "").strip()
    srt_mem_txt = str((tarefa_mem or {}).get("srt_texto") or "").strip()

    # Procura no disco em Downloads/DarkPlanner/studio/* e em D:\ARQUIVOS DE VIDEOS\* caso não esteja em memória
    pasta_dl_dp = obter_pasta_downloads_darkplanner()
    pasta_st_root = os.path.join(pasta_dl_dp, "studio")
    if (not pasta_creator or not os.path.isdir(pasta_creator)) and os.path.isdir(pasta_st_root):
        subpastas = [
            os.path.join(pasta_st_root, fn)
            for fn in os.listdir(pasta_st_root)
            if os.path.isdir(os.path.join(pasta_st_root, fn))
        ]
        subpastas.sort(key=lambda p: os.path.getmtime(p), reverse=True)
        if nome_proj:
            slug_alvo = re.sub(r"[^\w\- ]", "", nome_proj).strip().lower()[:28]
            slug_under = re.sub(r"[^\w]+", "_", nome_proj).strip("_").lower()[:28]
            for sp_dir in subpastas:
                bn_low = os.path.basename(sp_dir).lower()
                bn_under = re.sub(r"[^\w]+", "_", bn_low).strip("_")
                if (slug_alvo and slug_alvo in bn_low) or (slug_under and slug_under[:20] in bn_under):
                    pasta_creator = sp_dir
                    break
        elif subpastas:
            pasta_creator = subpastas[0]
            nome_proj = nome_proj or os.path.basename(pasta_creator)

    raiz_arq_vid_win = r"D:\ARQUIVOS DE VIDEOS"
    if (not pasta_arquivos_video or not os.path.isdir(pasta_arquivos_video)) and os.path.isdir(raiz_arq_vid_win):
        try:
            sub_av = [
                os.path.join(raiz_arq_vid_win, fn)
                for fn in os.listdir(raiz_arq_vid_win)
                if os.path.isdir(os.path.join(raiz_arq_vid_win, fn))
            ]
            sub_av.sort(key=lambda p: os.path.getmtime(p), reverse=True)
            if nome_proj:
                slug_av = re.sub(r"[^\w]+", "_", nome_proj).strip("_").lower()[:24]
                for av_dir in sub_av:
                    if slug_av and slug_av in re.sub(r"[^\w]+", "_", os.path.basename(av_dir)).strip("_").lower():
                        pasta_arquivos_video = av_dir
                        break
            elif sub_av:
                pasta_arquivos_video = sub_av[0]
        except Exception:
            pass

    srt_path = str((tarefa_mem or {}).get("srt_destino") or "").strip()
    mp3_path = str((tarefa_mem or {}).get("mp3_destino") or "").strip()
    srt_texto = ""
    if srt_path and os.path.isfile(srt_path):
        try:
            with open(srt_path, "r", encoding="utf-8", errors="ignore") as fs0:
                srt_texto = fs0.read().strip()
        except Exception:
            srt_texto = ""
    else:
        srt_path = ""
    if mp3_path and not os.path.isfile(mp3_path):
        mp3_path = ""

    pastas_busca_arquivos = [p for p in (pasta_creator, pasta_arquivos_video) if p and os.path.isdir(p)]
    if job_id:
        p_aud_j = os.path.join(storage.DATA_DIR, "audios_dp", job_id)
        if os.path.isdir(p_aud_j):
            pastas_busca_arquivos.append(p_aud_j)

    for p_dir_b in pastas_busca_arquivos:
        if not srt_texto:
            # 1) Nomes prioritários
            for fn_srt in ("03_LEGENDA_SINCRONIZADA_VEO.srt", "srtsynctempo_editado.srt", "legenda.srt"):
                p_cand = os.path.join(p_dir_b, fn_srt)
                if os.path.isfile(p_cand) and os.path.getsize(p_cand) > 50:
                    try:
                        with open(p_cand, "r", encoding="utf-8", errors="ignore") as fs:
                            txt_c = fs.read().strip()
                        if txt_c:
                            srt_path = p_cand
                            srt_texto = txt_c
                            break
                    except Exception:
                        pass
            # 2) Qualquer *.srt na pasta (ex.: <slug>_srtsynctempo.srt gerado pelo criar_projeto_darkplanner_desktop!)
            if not srt_texto:
                try:
                    cands_srt = [
                        p for p in glob.glob(os.path.join(p_dir_b, "*.srt"))
                        if os.path.isfile(p) and os.path.getsize(p) > 50
                    ]
                    if cands_srt:
                        cands_srt.sort(
                            key=lambda p: (1 if "srtsynctempo" in os.path.basename(p).lower() else 0, os.path.getsize(p)),
                            reverse=True,
                        )
                        with open(cands_srt[0], "r", encoding="utf-8", errors="ignore") as fs_any:
                            txt_any = fs_any.read().strip()
                        if txt_any:
                            srt_path = cands_srt[0]
                            srt_texto = txt_any
                except Exception:
                    pass

        if not mp3_path:
            for fn_mp3 in ("02_AUDIO_NARRACAO_OFICIAL.mp3", "audio.mp3"):
                p_cand_m = os.path.join(p_dir_b, fn_mp3)
                if os.path.isfile(p_cand_m) and os.path.getsize(p_cand_m) > 1000:
                    mp3_path = p_cand_m
                    break
            if not mp3_path:
                try:
                    cands_mp3 = [
                        p for p in glob.glob(os.path.join(p_dir_b, "*.mp3"))
                        if os.path.isfile(p) and os.path.getsize(p) > 1000
                    ]
                    if cands_mp3:
                        cands_mp3.sort(key=lambda p: os.path.getsize(p), reverse=True)
                        mp3_path = cands_mp3[0]
                except Exception:
                    pass

        pediu_nova_conv_ctx = bool(d.get("nova_conversa", False)) or str(d.get("acao_rapida") or "").strip().lower() == "criar_conversa_dp"
        if not mensagem_chat and pediu_nova_conv_ctx:
            for fn_pr in ("09_INSTRUCOES_IA_DARKPLANNER.txt", "09_PROMPT_EDICAO_STUDIO.txt", "04_PROMPT_EDICAO_STUDIO.txt"):
                p_prompt_ed = os.path.join(p_dir_b, fn_pr)
                if os.path.isfile(p_prompt_ed):
                    try:
                        with open(p_prompt_ed, "r", encoding="utf-8", errors="ignore") as fp:
                            txt_pr = fp.read().strip()
                        if txt_pr:
                            mensagem_chat = txt_pr
                            break
                    except Exception:
                        pass

    if not srt_texto and srt_texto_req:
        srt_texto = srt_texto_req
    if not srt_texto and srt_mem_txt:
        srt_texto = srt_mem_txt

    # Fallback para banco db.json (canal GTA à la Une ou último vídeo gerado)
    try:
        db = storage.load()
        if not srt_texto and db.get("videos"):
            vids_ord = sorted(
                db.get("videos") or [],
                key=lambda v: str(v.get("updated_at") or v.get("created_at") or ""),
                reverse=True,
            )
            for v_it in vids_ord:
                t_v = str(v_it.get("titulo") or "").strip()
                if (vid and v_it.get("id") == vid) or (nome_proj and t_v.lower()[:28] == nome_proj.lower()[:28]) or (not nome_proj):
                    nome_proj = nome_proj or t_v
                    vid = vid or str(v_it.get("id") or "")
                    canal_id = canal_id or str(v_it.get("channel_id") or v_it.get("canal_id") or "")
                    job_id = job_id or str(v_it.get("dp_job_id") or v_it.get("job_id") or "")
                    srt_texto = srt_texto or str(v_it.get("srt_veo") or v_it.get("srt") or "")
                    break
        if canal_id and not canal_nome:
            ch_db = storage.find(db.get("channels") or [], canal_id)
            if ch_db:
                canal_nome = str(ch_db.get("nome") or "")
        msg_usr_low = str(d.get("mensagem") or "").lower()
        if ("gta" in msg_usr_low or "gta" in nome_proj.lower() or "rockstar" in msg_usr_low) and not canal_nome:
            for ch_it in (db.get("channels") or []):
                if "gta" in str(ch_it.get("nome") or "").lower() or ch_it.get("id") == "a8068857-d56f-4aba-baf3-ea2b7ebda5bb":
                    canal_id = str(ch_it.get("id") or "a8068857-d56f-4aba-baf3-ea2b7ebda5bb")
                    canal_nome = str(ch_it.get("nome") or "GTA à la Une")
                    break
            if not canal_nome:
                canal_id = canal_id or "a8068857-d56f-4aba-baf3-ea2b7ebda5bb"
                canal_nome = "GTA à la Une"
    except Exception:
        pass

    if not sp_id:
        sp_id = f"sp_op_{int(time.time())}"

    return {
        "sp_id": sp_id,
        "nome_projeto": nome_proj or "Projeto Atual",
        "canal_id": canal_id,
        "canal_nome": canal_nome,
        "vid": vid,
        "job_id": job_id,
        "pasta_creator": pasta_creator,
        "pasta_arquivos_video": pasta_arquivos_video,
        "srt_path": srt_path,
        "mp3_path": mp3_path,
        "srt_texto": srt_texto,
        "mensagem_chat": mensagem_chat,
        "chat_modelo_opcao": chat_modelo_opcao,
        "tarefa_mem": tarefa_mem,
    }


def _localizar_canal_flexivel_db(canais_lista, canal_id="", canal_nome=""):
    """Localiza canal por ID exato ou nome flexível (ignorando acentos e variações como capitto/cappito)."""
    lista = canais_lista or []
    cid_s = str(canal_id or "").strip()
    cn_s = str(canal_nome or "").strip()
    if cid_s:
        achou = storage.find(lista, cid_s)
        if achou:
            return achou
    if cn_s:
        import unicodedata

        def _norm_c(s):
            t = unicodedata.normalize("NFKD", str(s or "")).encode("ascii", "ignore").decode("ascii").lower()
            t = t.replace("cappito", "capitto")
            return re.sub(r"[^a-z0-9]+", "", t)

        alvo_n = _norm_c(cn_s)
        if alvo_n:
            for c in lista:
                cn_c = _norm_c(c.get("nome") or "")
                if cn_c and (alvo_n == cn_c or alvo_n in cn_c or cn_c in alvo_n):
                    return c
    return None


def sincronizar_diretrizes_chat_no_darkplanner(
    canal_id="",
    canal_nome="",
    campos=None,
    edicao_patch=None,
    nome_projeto="",
    pasta_creator="",
    srt_texto="",
    aplicar_studio_agora=False,
    **_kwargs,
):
    """Salva na automação `Fábrica Dark` os novos formatos, estilos, proporções de mídia, funções especiais e presets de edição do canal:
    1. Salva no `db.json` local para que todas as Etapas 1–6 da `Fábrica Dark` já sigam o novo formato/estilo;
    2. Atualiza os metadados do canal (`/canais/{id}` + `/prompts`) e `09_PROMPT_EDICAO_STUDIO.txt` para levar tudo pronto ao DarkPlanner no final (Etapa 7);
    3. Só aciona a Ponte `/studio` ao vivo se `aplicar_studio_agora=True` (quando o projeto já estiver na Etapa 7)."""
    campos_in = dict(campos or {}) if isinstance(campos, dict) else {}
    ed_in = dict(edicao_patch or {}) if isinstance(edicao_patch, dict) else {}

    canal_info = {}
    edicao_final = {}
    prompt_dp_existente_id = None
    payload_canal_dp = None

    with storage.Tx() as db_w:
        canais_w = db_w.get("channels") or []
        ch_w = _localizar_canal_flexivel_db(canais_w, canal_id=canal_id, canal_nome=canal_nome)
        if not ch_w and canais_w:
            ch_w = canais_w[0]
        if not ch_w:
            return {"ok": False, "erro": "Nenhum canal encontrado para vincular as diretrizes."}

        chaves_diretas = (
            "idioma",
            "tese",
            "evitar",
            "diretriz_pauta",
            "estilo_visual",
            "cta",
            "modo_midia_custom",
            "proporcao_midia",
            "formato_video_custom",
            "veo_faixas_padrao",
        )
        for k_c in chaves_diretas:
            if k_c in campos_in and campos_in[k_c] not in (None, ""):
                ch_w[k_c] = campos_in[k_c]

        # Funções especiais de vídeo (acumula sem duplicar ou substitui se vier lista completa)
        if "funcoes_especiais_video" in campos_in and campos_in["funcoes_especiais_video"] not in (None, ""):
            val_fn = campos_in["funcoes_especiais_video"]
            atuais_fn = list(ch_w.get("funcoes_especiais_video") or []) if isinstance(ch_w.get("funcoes_especiais_video"), list) else (
                [str(ch_w.get("funcoes_especiais_video"))] if ch_w.get("funcoes_especiais_video") else []
            )
            novas_fn = [str(x).strip() for x in val_fn if str(x).strip()] if isinstance(val_fn, list) else [str(val_fn).strip()]
            if campos_in.get("substituir_funcoes"):
                atuais_fn = novas_fn
            else:
                for fn_item in novas_fn:
                    if fn_item and fn_item.lower() not in {x.lower() for x in atuais_fn}:
                        atuais_fn.append(fn_item)
            ch_w["funcoes_especiais_video"] = atuais_fn[-12:]

        # Regras customizadas vindas do Chat
        if campos_in.get("regras_custom_chat"):
            nova_regra = str(campos_in["regras_custom_chat"]).strip()
            ant_regra = str(ch_w.get("regras_custom_chat") or "").strip()
            if campos_in.get("substituir_regras") or not ant_regra or nova_regra.lower() in ant_regra.lower():
                ch_w["regras_custom_chat"] = nova_regra
            else:
                ch_w["regras_custom_chat"] = (ant_regra + "\n• " + nova_regra)[-2400:]

        # Preset padrão de edição do Studio do canal
        ed_atual = dict(ch_w.get("edicao_padrao") or {}) if isinstance(ch_w.get("edicao_padrao"), dict) else {}
        if isinstance(campos_in.get("edicao_padrao"), dict):
            ed_atual.update({k: v for k, v in campos_in["edicao_padrao"].items() if v not in (None, "")})
        if ed_in:
            ed_atual.update({k: v for k, v in ed_in.items() if v not in (None, "")})
        if ed_atual:
            ch_w["edicao_padrao"] = ed_atual
        edicao_final = dict(ed_atual)

        dp_sub = ch_w.setdefault("dp", {})
        prompts_lista = dp_sub.setdefault("prompts", [])
        for pr_it in prompts_lista:
            if isinstance(pr_it, dict):
                nm_p = str(pr_it.get("nome") or "")
                cat_p = str(pr_it.get("categoria") or "")
                if nm_p.startswith("[CHAT VINCULADO]") or cat_p == "chat_vinculado_estilo":
                    prompt_dp_existente_id = pr_it.get("id")
                    break

        canal_info = {
            "id": str(ch_w.get("id") or ""),
            "nome": str(ch_w.get("nome") or ""),
            "idioma": str(ch_w.get("idioma") or "pt"),
            "email": str(ch_w.get("email") or dp_sub.get("email") or ""),
            "horario_postagem": dp_sub.get("horario_postagem") or ["19:00"],
            "frequencia_postagem": str(dp_sub.get("frequencia_postagem") or ""),
            "videos_ja_postados": int(dp_sub.get("videos_ja_postados") or 0),
            "tese": str(ch_w.get("tese") or ""),
            "modo_midia_custom": ch_w.get("modo_midia_custom") or "",
            "proporcao_midia": ch_w.get("proporcao_midia") or "",
            "estilo_visual": str(ch_w.get("estilo_visual") or ""),
            "formato_video_custom": str(ch_w.get("formato_video_custom") or ""),
            "funcoes_especiais_video": list(ch_w.get("funcoes_especiais_video") or []) if isinstance(ch_w.get("funcoes_especiais_video"), list) else [],
            "regras_custom_chat": str(ch_w.get("regras_custom_chat") or ""),
            "anotacoes_orig": str(dp_sub.get("anotacoes") or ch_w.get("tese") or ""),
        }

    # Monta o documento mestre salvo na automação e pronto para o pacote final da Etapa 7
    linhas_md = [
        f"# [CHAT FÁBRICA DARK] Formato, Estilo e Funções — {canal_info['nome']}",
        f"Atualizado na automação Fábrica Dark em {time.strftime('%d/%m/%Y %H:%M:%S')}.",
        "",
    ]
    if canal_info["modo_midia_custom"] or canal_info["proporcao_midia"]:
        linhas_md.append(f"- **Modo / Proporção de Mídia**: `{canal_info['modo_midia_custom'] or 'auto'}` | `{json.dumps(canal_info['proporcao_midia'], ensure_ascii=False) if isinstance(canal_info['proporcao_midia'], dict) else canal_info['proporcao_midia']}`")
    if canal_info["formato_video_custom"]:
        linhas_md.append(f"- **Formato dos Vídeos**: {canal_info['formato_video_custom']}")
    if canal_info["estilo_visual"]:
        linhas_md.append(f"- **Estilo Visual**: {canal_info['estilo_visual']}")
    if canal_info["funcoes_especiais_video"]:
        linhas_md.append("- **Funções Especiais Ativas nos Vídeos**:\n" + "\n".join(f"  - {fn}" for fn in canal_info["funcoes_especiais_video"]))
    if edicao_final:
        linhas_md.append(f"- **Direção / Edição Padrão para Etapa 7**: `{json.dumps(edicao_final, ensure_ascii=False)}`")
    if canal_info["regras_custom_chat"]:
        linhas_md.append(f"\n## Diretrizes Diretas Definidas no Chat da Fábrica Dark\n{canal_info['regras_custom_chat']}")
    conteudo_prompt_dp = "\n".join(linhas_md).strip()

    sincronizado_dp_cloud = False
    prompt_dp_id_salvo = prompt_dp_existente_id
    cid_alvo = canal_info["id"]
    if cid_alvo:
        body_prompt = {
            "canal_id": cid_alvo,
            "nome": "[CHAT VINCULADO] Formato, Estilo e Funções dos Vídeos",
            "categoria": "chat_vinculado_estilo",
            "conteudo": conteudo_prompt_dp,
        }
        try:
            if prompt_dp_existente_id:
                res_pr = req("PUT", f"/prompts/{prompt_dp_existente_id}", json_body=body_prompt, timeout=6)
            else:
                res_pr = req("POST", "/prompts", json_body=body_prompt, timeout=6)
            if isinstance(res_pr, dict) and (res_pr.get("id") or prompt_dp_existente_id):
                prompt_dp_id_salvo = res_pr.get("id") or prompt_dp_existente_id
                sincronizado_dp_cloud = True
                with storage.Tx() as db_up:
                    ch_up = storage.find(db_up.get("channels") or [], cid_alvo)
                    if ch_up:
                        prs_up = ch_up.setdefault("dp", {}).setdefault("prompts", [])
                        atualizou_item = False
                        for idx_p, p_old in enumerate(prs_up):
                            if isinstance(p_old, dict) and (
                                p_old.get("id") == prompt_dp_id_salvo
                                or str(p_old.get("nome") or "").startswith("[CHAT VINCULADO]")
                                or p_old.get("categoria") == "chat_vinculado_estilo"
                            ):
                                prs_up[idx_p] = {
                                    "id": prompt_dp_id_salvo,
                                    "canal_id": cid_alvo,
                                    "nome": body_prompt["nome"],
                                    "categoria": body_prompt["categoria"],
                                    "conteudo": conteudo_prompt_dp,
                                }
                                atualizou_item = True
                                break
                        if not atualizou_item:
                            prs_up.append({
                                "id": prompt_dp_id_salvo,
                                "canal_id": cid_alvo,
                                "nome": body_prompt["nome"],
                                "categoria": body_prompt["categoria"],
                                "conteudo": conteudo_prompt_dp,
                            })
        except Exception:
            pass

        try:
            bloco_resumo_anot = (
                f"[CHAT VINCULADO] Estilo={canal_info['estilo_visual'] or 'padrão'} | "
                f"Formato={canal_info['formato_video_custom'][:120] or 'padrão'} | "
                f"Mídia={canal_info['modo_midia_custom'] or canal_info['proporcao_midia'] or 'padrão'}"
            )
            anot_base = re.sub(r"\[CHAT VINCULADO\][^\n]*", "", canal_info["anotacoes_orig"] or "").strip()
            nova_anot = (f"{anot_base}\n{bloco_resumo_anot}" if anot_base else bloco_resumo_anot).strip()[:2000]
            payload_canal_dp = {
                "nome": canal_info["nome"],
                "idioma": _idioma_dp_nome(canal_info["idioma"]),
                "email": canal_info["email"],
                "horario_postagem": canal_info["horario_postagem"] if isinstance(canal_info["horario_postagem"], list) else ["19:00"],
                "frequencia_postagem": canal_info["frequencia_postagem"],
                "videos_ja_postados": canal_info["videos_ja_postados"],
                "anotacoes": nova_anot,
            }
            req("PUT", f"/canais/{cid_alvo}", json_body=payload_canal_dp, timeout=6)
            sincronizado_dp_cloud = True
        except Exception:
            pass

    # Atualiza 09_PROMPT_EDICAO_STUDIO.txt no projeto aberto (se houver pasta local) para levar pronto na Etapa 7
    pasta_proj = pasta_creator
    if not pasta_proj and nome_projeto and nome_projeto != "Projeto Atual":
        cand_av = _obter_pasta_arquivos_video(nome_projeto, criar=False)
        if cand_av and os.path.isdir(cand_av):
            pasta_proj = cand_av
    if pasta_proj and os.path.isdir(pasta_proj):
        try:
            txt_ed_novo = gerar_prompt_edicao_studio_completo(
                titulo=nome_projeto or canal_info["nome"],
                canal_nome=canal_info["nome"],
                canal_id=cid_alvo,
                total_cenas=0,
                edicao_config=edicao_final,
            )
            with open(os.path.join(pasta_proj, "09_PROMPT_EDICAO_STUDIO.txt"), "w", encoding="utf-8") as f_ed9:
                f_ed9.write(txt_ed_novo)
        except Exception:
            pass

    # Só aplica ao vivo na Ponte /studio se o projeto JÁ estiver na Etapa 7 (nunca durante Etapas 1-6!)
    studio_ao_vivo_aplicado = False
    if aplicar_studio_agora:
        ponte_live = _ler_ponte_local_dp()
        if ponte_live and ponte_live.get("DARKPLANNER_PONTE_PORT") and nome_projeto and nome_projeto != "Projeto Atual":
            try:
                url_st_live = f"http://127.0.0.1:{ponte_live['DARKPLANNER_PONTE_PORT']}/studio"
                hdr_st_live = {"content-type": "application/json", "x-deleg-token": ponte_live.get("DARKPLANNER_PONTE_TOKEN") or ""}
                conv_st_live = ponte_live.get("DARKPLANNER_CONVERSA") or ""
                predef_alvo = str(edicao_final.get("predef") or "sys_tudo").strip() or "sys_tudo"
                r_ap = requests.post(
                    url_st_live,
                    headers=hdr_st_live,
                    json={"acao": "aplicar_direcao", "args": {"projeto": nome_projeto, "predef": predef_alvo}, "conversaId": conv_st_live},
                    timeout=8,
                )
                studio_ao_vivo_aplicado = bool(r_ap.ok)
            except Exception:
                studio_ao_vivo_aplicado = False

    return {
        "ok": True,
        "canal_id": cid_alvo,
        "canal_nome": canal_info["nome"],
        "sincronizado_dp_cloud": sincronizado_dp_cloud,
        "prompt_dp_id": prompt_dp_id_salvo,
        "studio_ao_vivo_aplicado": studio_ao_vivo_aplicado,
        "edicao_padrao": edicao_final,
        "canal_atualizado": canal_info,
        "conteudo_prompt_dp": conteudo_prompt_dp,
    }


def obter_contexto_vivo_darkplanner_para_chat(nome_projeto="", canal_id="", canal_nome="", sp_id=""):
    """Lê o estado ao vivo do DarkPlanner (Chat CDP, erros visíveis, Ponte Studio, API 7812 e Prompts vinculados do canal)
    para que o Chat do nosso app responda e corrija problemas diretamente conectado ao DarkPlanner."""
    res_vivo = {
        "modo_execucao": "windows_local" if os.name == "nt" else "remoto_vinculado_nuvem",
        "cdp_chat": {},
        "studio": {"ponte_ativa": False, "cenas": 0, "midias": 0, "duracao_s": 0.0},
        "api_7812_ativa": False,
        "tarefa_ativa": {},
        "canal_diretrizes": _obter_override_chat_canal(canal_nome=canal_nome, canal_id=canal_id),
    }
    try:
        with _LOCK_ETAPA7_DP:
            tm = _TAREFAS_ETAPA7_DP.get(sp_id) or (
                _TAREFAS_ETAPA7_DP.get(str(nome_projeto or "").strip().lower()) if nome_projeto else None
            )
            if isinstance(tm, dict):
                res_vivo["tarefa_ativa"] = {
                    "em_andamento": bool(tm.get("em_andamento")),
                    "concluido_dp": bool(tm.get("concluido_dp")),
                    "progresso_pct": tm.get("progresso_pct"),
                    "cenas_prontas": tm.get("cenas_prontas"),
                    "total_cenas": tm.get("total_cenas"),
                    "jobs_erros": tm.get("jobs_erros"),
                    "erro": tm.get("erro") or "",
                    "etapa_atual": tm.get("etapa_atual") or "",
                }
    except Exception:
        pass

    if os.name == "nt":
        try:
            res_vivo["cdp_chat"] = _ler_ultima_resposta_e_erros_chat_dp_cdp(nome_projeto)
        except Exception:
            res_vivo["cdp_chat"] = {}
        try:
            r_h = requests.get("http://127.0.0.1:7812/api/health", timeout=1.2)
            res_vivo["api_7812_ativa"] = bool(r_h.ok)
        except Exception:
            res_vivo["api_7812_ativa"] = False
        ponte_l = _ler_ponte_local_dp()
        if ponte_l and ponte_l.get("DARKPLANNER_PONTE_PORT"):
            res_vivo["studio"]["ponte_ativa"] = True
            if nome_projeto and nome_projeto != "Projeto Atual":
                try:
                    r_st = requests.post(
                        f"http://127.0.0.1:{ponte_l['DARKPLANNER_PONTE_PORT']}/studio",
                        headers={"content-type": "application/json", "x-deleg-token": ponte_l.get("DARKPLANNER_PONTE_TOKEN") or ""},
                        json={"acao": "estado", "args": {"projeto": nome_projeto, "nivel": "resumo"}, "conversaId": ponte_l.get("DARKPLANNER_CONVERSA") or ""},
                        timeout=2.5,
                    )
                    if r_st.ok:
                        d_st = r_st.json() or {}
                        cnt = d_st.get("contagens") or {}
                        res_vivo["studio"]["cenas"] = int(cnt.get("cena") or cnt.get("cenas") or 0)
                        res_vivo["studio"]["midias"] = int(d_st.get("midiasNoProjeto") or cnt.get("midias") or 0)
                        res_vivo["studio"]["duracao_s"] = float(d_st.get("duracaoS") or 0.0)
                except Exception:
                    pass
    return res_vivo


def diagnosticar_e_corrigir_erro_automacao_local(dados):
    """Diagnostica, interrompe e repara erros DIRETAMENTE dentro da nossa automação `Fábrica Dark`
    (Etapas 1–6: análise de canal, estrutura, roteiro completo, pacote viral/thumb, áudio MP3 + SRT e prompts/mídias),
    SEM NUNCA enviar comandos prematuros para o Chat do DarkPlanner Desktop."""
    import importlib
    import sys

    d = dados if isinstance(dados, dict) else {}
    sp_id = str(d.get("sp_id") or "").strip()
    nome_proj = str(d.get("nome_projeto") or "Projeto Atual").strip() or "Projeto Atual"
    canal_id = str(d.get("canal_id") or "").strip()
    canal_nome = str(d.get("canal_nome") or "").strip()
    parar_esteira = bool(d.get("parar_esteira", True))
    auto_reexecutar = bool(d.get("auto_reexecutar", False))
    etapas_raw = d.get("etapas_app")
    logs_raw = d.get("logs_recentes_app") or []

    # 1. Se pediu para parar o projeto, marca qualquer rotina em memória como pausada na Fábrica Dark (sem abrir nem mexer no DarkPlanner Desktop)
    if parar_esteira:
        try:
            pausar_processo_etapa7_dp(sp_id=sp_id, nome_projeto=nome_proj, pausar_chat_dp=False)
        except Exception:
            _marcar_cancelado_etapa7(sp_id=sp_id, nome_projeto=nome_proj, limpar=False)

    # 2. Normaliza etapas vindas do frontend (aceita tanto dict quanto lista de objetos S.estLiveSteps)
    mapa_passo_chave = {
        "p1": ("p1_estruturar", "Passo 1 (Estruturar Roteiro)"),
        "p1_estruturar": ("p1_estruturar", "Passo 1 (Estruturar Roteiro)"),
        "p2": ("p2_roteiro", "Passo 2 (Escrever Roteiro Completo)"),
        "p2_roteiro": ("p2_roteiro", "Passo 2 (Escrever Roteiro Completo)"),
        "p3": ("p4_pacote_viral", "Passo 3 (Descrição + Tags + Thumbnail)"),
        "p3_viral": ("p4_pacote_viral", "Passo 3 (Descrição + Tags + Thumbnail)"),
        "p4_pacote_viral": ("p4_pacote_viral", "Passo 3 (Descrição + Tags + Thumbnail)"),
        "p4": ("p5_audio_srt", "Passo 4/5 (Áudio MP3 + SRT Tempo VEO)"),
        "p5": ("p5_audio_srt", "Passo 4/5 (Áudio MP3 + SRT Tempo VEO)"),
        "p5_audio_srt": ("p5_audio_srt", "Passo 4/5 (Áudio MP3 + SRT Tempo VEO)"),
        "p6": ("p6_cenas", "Passo 6 (Prompts Flow / Mídias 1:1)"),
        "p6_cenas": ("p6_cenas", "Passo 6 (Prompts Flow / Mídias 1:1)"),
    }
    ordem_prioridade = ["p1", "p2", "p3_viral", "p3", "p4", "p5", "p6"]

    erros_detectados = []
    etapas_rodando = []
    if isinstance(etapas_raw, dict):
        for k_ord in ordem_prioridade + [k for k in etapas_raw.keys() if k not in ordem_prioridade]:
            v_st = etapas_raw.get(k_ord)
            if not isinstance(v_st, dict):
                continue
            st_val = str(v_st.get("status") or v_st.get("st") or "").strip().lower()
            msg_val = str(v_st.get("msg") or v_st.get("detalhe") or "").strip()
            if st_val == "erro":
                erros_detectados.append((k_ord, msg_val))
            elif st_val == "rodando":
                etapas_rodando.append((k_ord, msg_val))
    elif isinstance(etapas_raw, list):
        for item_st in etapas_raw:
            if not isinstance(item_st, dict):
                continue
            k_id = str(item_st.get("id") or item_st.get("step") or "").strip()
            st_val = str(item_st.get("status") or item_st.get("st") or "").strip().lower()
            msg_val = str(item_st.get("msg") or item_st.get("detalhe") or "").strip()
            if st_val == "erro":
                erros_detectados.append((k_id, msg_val))
            elif st_val == "rodando":
                etapas_rodando.append((k_id, msg_val))

    logs_lista = [str(x).strip() for x in logs_raw if str(x).strip()] if isinstance(logs_raw, list) else (
        [ln.strip() for ln in str(logs_raw).splitlines() if ln.strip()]
    )
    linhas_erro_log = [
        ln for ln in logs_lista
        if any(tok in ln.lower() for tok in ("✕", "erro", "unexpected keyword", "quota", "429", "401", "traceback", "failed"))
    ]

    texto_diag_total = " | ".join([m for _, m in erros_detectados if m] + linhas_erro_log[-5:])

    # 3. Auto-Reparo real dentro da Fábrica Dark (sincronização rápida + hot-reload de módulos + failover de IA + regras de canais)
    reparos_feitos = []
    try:
        from core import atualizador
        res_upd = atualizador.sincronizar_da_nuvem_darkplanner(auto_reiniciar=False)
        if isinstance(res_upd, dict) and res_upd.get("arquivos_atualizados"):
            reparos_feitos.append(f"código local atualizado da nuvem ({len(res_upd['arquivos_atualizados'])} módulo(s) recarregado(s))")
    except Exception:
        pass

    modulos_recarregados = 0
    for nome_m in ("storage", "prompts", "gemini", "claude", "pauta", "thumb"):
        fq_m = f"core.{nome_m}"
        if fq_m in sys.modules:
            try:
                importlib.reload(sys.modules[fq_m])
                modulos_recarregados += 1
            except Exception:
                pass
    if modulos_recarregados:
        reparos_feitos.append("módulos internos da Fábrica Dark recarregados em memória")

    try:
        with storage.Tx() as db_cfg:
            st_cfg = db_cfg.setdefault("settings", {})
            st_cfg["failover_automatico_ativo"] = True
        reparos_feitos.append("failover automático `Gemini → Antigravity → Codex → GPT` garantido sem travar por cota")
    except Exception:
        pass

    if any(tok in texto_diag_total.lower() for tok in ("401", "unauthorized", "token", "sessao", "sessão")):
        try:
            _renovar_token_automatico()
            reparos_feitos.append("token de sessão renovado automaticamente")
        except Exception:
            pass

    try:
        garantir_regras_canais_padrao()
    except Exception:
        pass

    # 4. Define qual etapa da Fábrica Dark deve ser reexecutada
    chave_reexec = "p1_estruturar"
    nome_etapa_humana = "Passo 1 (Estruturar Roteiro)"
    detalhe_erro_curto = ""
    if erros_detectados:
        k_falha, msg_falha = erros_detectados[0]
        chave_reexec, nome_etapa_humana = mapa_passo_chave.get(k_falha, ("p1_estruturar", f"Etapa {k_falha.upper()}"))
        detalhe_erro_curto = msg_falha[:180]
    elif etapas_rodando:
        k_rod, _ = etapas_rodando[0]
        chave_reexec, nome_etapa_humana = mapa_passo_chave.get(k_rod, ("p1_estruturar", f"Etapa {k_rod.upper()}"))
    elif linhas_erro_log:
        detalhe_erro_curto = linhas_erro_log[-1][:180]
        low_l = detalhe_erro_curto.lower()
        if "roteiro_completo" in low_l or "passo 2" in low_l:
            chave_reexec, nome_etapa_humana = ("p2_roteiro", "Passo 2 (Escrever Roteiro Completo)")
        elif "pacote viral" in low_l or "thumb" in low_l or "passo 3" in low_l:
            chave_reexec, nome_etapa_humana = ("p4_pacote_viral", "Passo 3 (Descrição + Tags + Thumbnail)")
        elif "audio" in low_l or "áudio" in low_l or "srt" in low_l:
            chave_reexec, nome_etapa_humana = ("p5_audio_srt", "Passo 4/5 (Áudio MP3 + SRT Tempo VEO)")
        elif "skill6" in low_l or "flow" in low_l or "cenas" in low_l:
            chave_reexec, nome_etapa_humana = ("p6_cenas", "Passo 6 (Prompts Flow / Mídias 1:1)")

    rotulo_btn = f"▶️ Reexecutar {nome_etapa_humana} na Fábrica Dark"
    linhas_resp = []
    if parar_esteira:
        linhas_resp.append(
            f"⏹️ **Projeto `{nome_proj}` interrompido imediatamente aqui na automação Fábrica Dark!** "
            f"*(Nada foi enviado ao DarkPlanner.)*"
        )
    else:
        linhas_resp.append(
            f"🛠️ **Diagnóstico e correção aplicados direto na automação Fábrica Dark (`{nome_proj}`)!**"
        )

    if detalhe_erro_curto:
        linhas_resp.append(f"• **Falha identificada em {nome_etapa_humana}**: `{detalhe_erro_curto}`")
    elif etapas_rodando and parar_esteira:
        linhas_resp.append(f"• **Etapa em execução travada/parada**: **{nome_etapa_humana}** foi abortada na hora para não girar em falso.")

    linhas_resp.append(
        f"• **Correção local concluída na Fábrica Dark**: {', '.join(reparos_feitos[:3])}."
    )
    if auto_reexecutar:
        linhas_resp.append(f"• Reiniciando **{nome_etapa_humana}** automaticamente aqui na Fábrica Dark agora!")
    else:
        linhas_resp.append(
            f"• Clique no botão abaixo para rodar **{nome_etapa_humana}** corrigido aqui na Fábrica Dark "
            f"(só levaremos ao Chat do DarkPlanner no final, na Etapa 7)."
        )

    return {
        "ok": True,
        "parar_automacao_app": bool(parar_esteira),
        "pausado": bool(parar_esteira),
        "em_andamento": False,
        "enviado_direto_chat_dp": False,
        "limpar_erros_etapas": True,
        "reparo_aplicado": True,
        "sp_id": sp_id,
        "nome_projeto": nome_proj,
        "canal_id": canal_id,
        "canal_nome": canal_nome,
        "reexecutar_etapa_app": chave_reexec if auto_reexecutar else "",
        "etapa_sugerida_botao": {
            "chave": chave_reexec,
            "rotulo": rotulo_btn,
        },
        "acoes_executadas": reparos_feitos,
        "resposta": "\n".join(linhas_resp),
    }


def executar_comando_chat_operacional(dados):
    """Chat Oficial da Automação `Fábrica Dark` (`#fd-dp-live-drawer`):
    Atua 100% DENTRO da nossa automação `Fábrica Dark` durante a criação do projeto:
    -1. Excluir completamente um projeto vinculado pelo Chat (`excluir_projeto`);
     0. Parar / pausar imediatamente a esteira e qualquer etapa rodando na `Fábrica Dark` (`parar_automacao_app`);
     1. Diagnosticar e corrigir erros das Etapas 1–6 dentro da `Fábrica Dark` (`diagnosticar_e_corrigir_erro_automacao_local`);
     2. Analisar canais, ajustar estrutura/roteiro na mesma conversa e configurar formatos, estilos, proporções e funções dos vídeos na `Fábrica Dark`;
     3. Somente no final (Etapa 7) — ou quando o usuário pedir explicitamente — levar o pacote completo para o Chat do DarkPlanner Desktop."""
    d = dados if isinstance(dados, dict) else {}
    msg_user = str(d.get("mensagem") or "").strip()
    acao_rapida = str(d.get("acao_rapida") or "").strip().lower()
    modo_agente = str(d.get("modo_agente") or "").strip().lower()
    nova_conversa_req = bool(d.get("nova_conversa", False))
    origem_nuvem = bool(d.get("_origem_fila_nuvem"))
    ja_na_etapa7 = bool(d.get("ja_na_etapa7", False))
    msg_low = msg_user.lower().strip()

    ctx = _resolver_contexto_projeto_chat_op(d)
    sp_id = ctx["sp_id"]
    nome_proj = ctx["nome_projeto"]
    canal_id = ctx["canal_id"]
    canal_nome = ctx["canal_nome"]
    srt_texto = ctx["srt_texto"]
    pasta_creator = ctx["pasta_creator"]
    pasta_midias = os.path.join(pasta_creator, "midias") if pasta_creator else ""
    chat_modelo_opcao = ctx["chat_modelo_opcao"]

    # CASO -2: PROTEÇÃO ANTI-COLAGEM DE PACOTE DA ETAPA 7 NO CHAT DA FÁBRICA DARK
    # Se por qualquer motivo o texto completo da Etapa 7 cair aqui, NUNCA pausa a esteira — envia direto ao DarkPlanner Desktop!
    if (
        "# produção automática no darkplanner desktop" in msg_low
        or "# montagem e edição imediata no darkplanner studio" in msg_low
    ):
        _marcar_cancelado_etapa7(sp_id=sp_id, nome_projeto=nome_proj, limpar=True)
        if os.name == "nt":
            res_dp_redir = abrir_chat_darkplanner_e_colar(
                mensagem_chat=msg_user,
                auto_enviar=True,
                nova_conversa=True,
                chat_modelo_opcao=chat_modelo_opcao or "flash_high",
                forcar_reenvio=True,
                titulo_conversa=nome_proj,
                auto_reconectar_cdp=True,
                focar_janela=True,
            )
            return {
                "ok": True,
                "parar_automacao_app": False,
                "pausado": False,
                "enviado_direto_chat_dp": True,
                "conversa_criada_real_dp": bool((res_dp_redir or {}).get("cdp_enviou")),
                "sp_id": sp_id,
                "nome_projeto": nome_proj,
                "resposta": (
                    f"🎯 **Pacote da Etapa 7 encaminhado diretamente para o `Dark Planner.exe`** "
                    f"(`C:\\Users\\leona\\AppData\\Local\\Programs\\darkplanner\\Dark Planner.exe`)!"
                ),
            }
        sp_rem = sp_id or f"sp_op_{int(time.time())}"
        enfileirar_etapa7_remoto_nuvem({
            "sp_id": sp_rem,
            "nome_projeto": nome_proj,
            "titulo": nome_proj,
            "chat_modelo_opcao": chat_modelo_opcao or "flash_high",
            "pausado": False,
            "comando_chat_operacional": {
                "mensagem": msg_user,
                "acao_rapida": "criar_conversa_dp",
                "nome_projeto": nome_proj,
                "chat_modelo_opcao": chat_modelo_opcao or "flash_high",
                "nova_conversa": True,
            },
            "acao_tecnica": "aguardando_comando_pc",
            "progresso_pct": 25,
            "etapa_atual": f"🎯 Encaminhando pacote para `Dark Planner.exe` no seu PC ('{nome_proj}')...",
        })
        return {
            "ok": True,
            "parar_automacao_app": False,
            "pausado": False,
            "enviado_direto_chat_dp": True,
            "modo_remoto_vinculado_pc": True,
            "sp_id": sp_rem,
            "nome_projeto": nome_proj,
            "resposta": f"🎯 **Pacote da Etapa 7 encaminhado para o `Dark Planner.exe` no seu PC!**",
        }

    # CASO -1: EXCLUIR PROJETO VINCULADO DIRETAMENTE PELO CHAT
    pediu_excluir_proj = (
        acao_rapida in ("excluir_projeto", "apagar_projeto", "deletar_projeto", "remover_projeto")
        or any(
            frase in msg_low
            for frase in (
                "excluir projeto",
                "apagar projeto",
                "deletar projeto",
                "remover projeto",
                "excluir este projeto",
                "apagar este projeto",
                "excluir o projeto",
                "apagar o projeto",
            )
        )
    )
    if pediu_excluir_proj:
        res_del = deletar_projeto_criado_completo(
            titulo=nome_proj if nome_proj != "Projeto Atual" else "",
            vid=ctx["vid"],
            sp_id=sp_id,
            pasta=pasta_creator or ctx["pasta_arquivos_video"],
            apagar_arquivos_disco=True,
        )
        return {
            "ok": True,
            "projeto_excluido": True,
            "sp_id": sp_id,
            "vid": ctx["vid"],
            "nome_projeto": nome_proj,
            "removidos": res_del.get("removidos") or [],
            "resposta": (
                f"🗑️ **Projeto `{nome_proj}` excluído por completo da Fábrica Dark!**\n"
                f"• Removido do painel do Chat, da fila de produção, do banco de dados e das pastas locais.\n"
                f"• Você já pode selecionar outro projeto ou iniciar uma **➕ Nova Conversa** limpa."
            ),
        }

    # CASO 0: PAUSAR / PARAR PROJETO IMEDIATAMENTE NA FÁBRICA DARK (SEM ENVIAR AO DARKPLANNER!)
    pediu_pausa = (
        acao_rapida in ("pausar", "pausar_processo", "parar", "cancelar")
        or msg_low in (
            "pausar",
            "parar",
            "cancelar",
            "interromper",
            "parar projeto",
            "pausar projeto",
            "pausar conversa",
            "pausar processo",
            "parar conversa",
            "parar processo",
            "cancelar processo",
        )
    )
    if pediu_pausa:
        res_p = pausar_processo_etapa7_dp(sp_id=sp_id, nome_projeto=nome_proj, pausar_chat_dp=bool(ja_na_etapa7))
        res_p["parar_automacao_app"] = True
        res_p["enviado_direto_chat_dp"] = False
        res_p["resposta"] = (
            f"⏹️ **Projeto `{nome_proj}` pausado imediatamente aqui na automação Fábrica Dark!**\n"
            f"• Todas as etapas em andamento na tela foram interrompidas *(nada foi enviado ao DarkPlanner)*.\n"
            f"• Escreva o ajuste que deseja fazer ou clique em continuar quando quiser."
        )
        return res_p

    # Atalho rápido de Parar e Corrigir Erro na Fábrica Dark
    if acao_rapida in ("parar_e_corrigir_app", "corrigir_erro_app"):
        return diagnosticar_e_corrigir_erro_automacao_local({
            **d,
            "sp_id": sp_id,
            "nome_projeto": nome_proj,
            "canal_id": canal_id,
            "canal_nome": canal_nome,
            "parar_esteira": acao_rapida == "parar_e_corrigir_app" or any(p in msg_low for p in ("parar", "pausar", "interromper")),
        })

    # Limpa eventual flag anterior de pausa apenas quando não for comando de parar
    if not any(p in msg_low for p in ("parar", "pausar", "interromper", "cancelar")):
        _marcar_cancelado_etapa7(sp_id=sp_id, nome_projeto=nome_proj, limpar=True)

    # Classificação de botões rápidos explícitos da Etapa 7
    pediu_gta_explicito = acao_rapida == "regularizar_gta_rockstar" or (
        any(k in msg_low for k in ("regularizar cenas gta", "substituir cenas rockstar", "baixar trailers rockstar"))
        and bool(srt_texto or (pasta_midias and os.path.isdir(pasta_midias)))
    )
    pediu_conversa_explicita = acao_rapida == "criar_conversa_dp" or (nova_conversa_req and not msg_user)
    pediu_edicao_studio_explicita = acao_rapida == "reaplicar_edicao_studio"
    pediu_auditoria_pura = acao_rapida == "auditar_status" or (
        ja_na_etapa7 and msg_low in ("status", "verificar status", "auditar status")
    )

    # ==========================================================================
    # AGENTE DA FÁBRICA DARK (CORREÇÃO LOCAL DE ERROS, ROTEIROS, CANAIS, ESTILOS, FORMATOS E FUNÇÕES)
    # ==========================================================================
    if (
        msg_user
        and not acao_rapida
        and not pediu_gta_explicito
        and not pediu_conversa_explicita
        and not pediu_edicao_studio_explicita
        and not pediu_auditoria_pura
    ):
        try:
            from core import antigravity_codex

            dp_vivo = obter_contexto_vivo_darkplanner_para_chat(
                nome_projeto=nome_proj,
                canal_id=canal_id,
                canal_nome=canal_nome,
                sp_id=sp_id,
            ) if ja_na_etapa7 else {
                "modo_execucao": "automacao_fabrica_dark",
                "canal_diretrizes": _obter_override_chat_canal(canal_nome=canal_nome, canal_id=canal_id),
            }
            res_ag = antigravity_codex.conversar_agente_antigravity_codex(
                mensagem=msg_user,
                historico=d.get("historico") or [],
                contexto_projeto={
                    "sp_id": sp_id,
                    "nome_projeto": nome_proj,
                    "canal_id": canal_id,
                    "canal_nome": canal_nome,
                    "vid": ctx["vid"],
                    "job_id": ctx["job_id"],
                    "srt_texto": srt_texto,
                    "pasta_creator": pasta_creator,
                    "roteiro_atual": d.get("roteiro_atual") or "",
                    "estrutura_atual": d.get("estrutura_atual") or "",
                    "titulo_atual": d.get("titulo_atual") or nome_proj,
                    "etapas_app": d.get("etapas_app") or [],
                    "logs_recentes_app": d.get("logs_recentes_app") or [],
                    "esteira_rodando": bool(d.get("esteira_rodando", False)),
                    "ja_na_etapa7": ja_na_etapa7,
                    "chat_modelo_opcao": chat_modelo_opcao,
                    "nova_conversa": nova_conversa_req,
                    "origem_nuvem": origem_nuvem,
                    "modo_agente": modo_agente,
                    "dp_vivo": dp_vivo,
                },
            )
            if isinstance(res_ag, dict) and res_ag.get("ok"):
                if res_ag.get("disparar_regularizacao_midias"):
                    acao_rapida = str(res_ag.get("disparar_regularizacao_midias"))
                else:
                    res_ag.setdefault("sp_id", sp_id)
                    res_ag.setdefault("nome_projeto", nome_proj)
                    res_ag.setdefault("mesma_conversa", not bool(nova_conversa_req))
                    return res_ag
        except Exception as e_chat_ag:
            print("Aviso conversar_agente_antigravity_codex:", e_chat_ag)

    # TRAVA DE SEGURANÇA: Se NÃO for uma ação explícita da Etapa 7 no DarkPlanner Desktop, NUNCA abre nem envia nada ao DarkPlanner!
    acoes_explicitas_dp7 = {"regularizar_gta_rockstar", "criar_conversa_dp", "reaplicar_edicao_studio", "auditar_status"}
    pediu_explicitamente_dp = (
        acao_rapida in acoes_explicitas_dp7
        or pediu_gta_explicito
        or pediu_conversa_explicita
        or pediu_edicao_studio_explicita
        or pediu_auditoria_pura
        or any(f in msg_low for f in ("enviar para o darkplanner", "mandar pro darkplanner", "no chat do darkplanner"))
    )
    if not pediu_explicitamente_dp and not ja_na_etapa7:
        return diagnosticar_e_corrigir_erro_automacao_local({
            **d,
            "sp_id": sp_id,
            "nome_projeto": nome_proj,
            "canal_id": canal_id,
            "canal_nome": canal_nome,
            "parar_esteira": any(p in msg_low for p in ("parar", "pausar", "interromper", "cancelar")),
        })

    # Classificação inteligente para os fluxos operacionais explícitos da Etapa 7 (GTA Rockstar / Nova Conversa DP / Reaplicar Studio)
    pediu_gta = (
        acao_rapida == "regularizar_gta_rockstar"
        or any(
            k in msg_low
            for k in (
                "rockstar",
                "copyhite",
                "copyright",
                "mascara",
                "máscara",
                "gta",
                "canal em frances",
                "canal em francês",
                "canalem frances",
                "trailer",
            )
        )
    )
    pediu_conversa = (
        acao_rapida == "criar_conversa_dp"
        or nova_conversa_req
        or any(
            k in msg_low
            for k in (
                "nova conversa",
                "criar conversa",
                "abrir nova conversa",
                "nao criou",
                "não criou",
                "reconectar",
            )
        )
    )
    pediu_edicao_studio = (
        acao_rapida == "reaplicar_edicao_studio"
        or any(
            k in msg_low
            for k in (
                "transiç",
                "transic",
                "reaplicar",
                "remontar",
                "sincroniz",
                "importados",
                "117",
                "93",
                "90",
                "114",
                "faltando",
                "completar cenas",
            )
        )
    )

    acoes_executadas = []

    # Sempre garante as regras atualizadas dos canais (incluindo GTA à la Une fr-FR e Cappito Vital 70% Vídeo / 30% Imagem)
    if pediu_gta or "gta" in canal_nome.lower() or canal_id == "a8068857-d56f-4aba-baf3-ea2b7ebda5bb" or "vital" in canal_nome.lower():
        try:
            garantir_regras_canais_padrao()
            if pediu_gta or "gta" in canal_nome.lower():
                acoes_executadas.append("Canal `GTA à la Une` migrado e travado em Francês (`fr-FR`) + Modo Oficial Rockstar Anti-Copyright (`gta_rockstar_real`).")
        except Exception:
            pass

    # Se estivermos no Modo Remoto (Linux VM) e o comando exigir manipular explicitamente o DarkPlanner Desktop (Etapa 7):
    if os.name != "nt" and not origem_nuvem:
        res_noticias_fr = []
        if pediu_gta:
            try:
                from core import gta_rockstar_media
                res_noticias_fr = gta_rockstar_media.buscar_noticias_gta_frances_ao_vivo(limite=3)
            except Exception:
                res_noticias_fr = []

        sp_op_rem = sp_id if sp_id and not sp_id.startswith("sp_op_") else f"sp_op_{int(time.time())}"
        _marcar_cancelado_etapa7(sp_id=sp_op_rem, nome_projeto=nome_proj, limpar=True)
        enfileirar_etapa7_remoto_nuvem({
            "sp_id": sp_op_rem,
            "nome_projeto": nome_proj,
            "titulo": nome_proj,
            "canal_id": canal_id or ("a8068857-d56f-4aba-baf3-ea2b7ebda5bb" if pediu_gta else ""),
            "canal_nome": canal_nome or ("GTA à la Une" if pediu_gta else ""),
            "vid": ctx["vid"],
            "job_id": ctx["job_id"],
            "srt_texto": srt_texto,
            "chat_modelo_opcao": chat_modelo_opcao,
            "pausado": False,
            "comando_chat_operacional": {
                "mensagem": msg_user,
                "acao_rapida": acao_rapida or ("regularizar_gta_rockstar" if pediu_gta else ("criar_conversa_dp" if pediu_conversa else ("reaplicar_edicao_studio" if pediu_edicao_studio else "auditar_status"))),
                "nome_projeto": nome_proj,
                "canal_id": canal_id,
                "canal_nome": canal_nome,
                "chat_modelo_opcao": chat_modelo_opcao,
                "nova_conversa": bool(nova_conversa_req),
            },
            "acao_tecnica": "aguardando_comando_pc",
            "progresso_pct": 22,
            "etapa_atual": f"🌐 Comando Etapa 7 enviado para o Chat do DarkPlanner no seu PC ('{nome_proj}')...",
        })
        extra_gta = ""
        if pediu_gta:
            manchetes = "; ".join(n.get("titulo", "")[:65] for n in res_noticias_fr[:2]) if res_noticias_fr else "Rockstar Games FR / GTA VI Novembre"
            extra_gta = (
                f"\n• **Canal `GTA à la Une` (`fr-FR`) atualizado**: busca direta em `rockstargames.com/fr/VI` + `@RockstarGames` YouTube + notícias francesas ({manchetes})."
                f"\n• **Anti-Copyright Fair-Use ativo**: cortes curtos (3.8s–5.6s), 0% áudio original, zoom assimétrico 110%, máscara óptica + barra neon GTA e transições fade."
            )
        resp_rem = (
            f"✅ **Comando da Etapa 7 enviado para o Chat do DarkPlanner {'(nova conversa)' if nova_conversa_req else '(mesma conversa)'} no seu PC Windows!**{extra_gta}\n"
            f"• **Roteiro, ponto de vista, narração MP3 e SRT existentes foram 100% preservados** (nada será regerado do zero).\n"
            f"• Ação vinculada no DarkPlanner: **{('substituição das cenas por clipes oficiais Rockstar mascarados + edição Studio' if pediu_gta else ('abertura de nova conversa no Chat do DarkPlanner' if nova_conversa_req else 'ajuste pontual direto no Chat e Studio do DarkPlanner'))}**."
        )
        return {
            "ok": True,
            "modo_remoto_vinculado_pc": True,
            "mesma_conversa": not bool(nova_conversa_req),
            "em_andamento": True,
            "sp_id": sp_op_rem,
            "nome_projeto": nome_proj,
            "acoes_executadas": acoes_executadas,
            "resposta": resp_rem,
        }

    # ==========================================================================
    # EXECUÇÃO LOCAL NO PC WINDOWS DO USUÁRIO (SOMENTE PARA AÇÕES EXPLÍCITAS DA ETAPA 7 NO DARKPLANNER.EXE)
    # ==========================================================================
    info_dp = _garantir_darkplanner_desktop_aberto(abrir_exe=True, aguardar_api_s=6.0, focar_janela=True)
    ponte_st = _ler_ponte_local_dp()
    chk_cdp_live = _verificar_chat_dp_gerando_projeto_cdp(nome_proj)

    # Lê o estado REAL do projeto aberto no DarkPlanner Studio
    cenas_studio_real = 0
    midias_studio_real = 0
    duracao_studio_s = 0.0
    if ponte_st and ponte_st.get("DARKPLANNER_PONTE_PORT"):
        try:
            r_est = requests.post(
                f"http://127.0.0.1:{ponte_st['DARKPLANNER_PONTE_PORT']}/studio",
                headers={"content-type": "application/json", "x-deleg-token": ponte_st.get("DARKPLANNER_PONTE_TOKEN") or ""},
                json={"acao": "estado", "args": {"projeto": nome_proj, "nivel": "resumo"}, "conversaId": ponte_st.get("DARKPLANNER_CONVERSA") or ""},
                timeout=4,
            )
            if r_est.ok:
                d_est = r_est.json() or {}
                cnt = d_est.get("contagens") or {}
                cenas_studio_real = int(cnt.get("cena") or cnt.get("cenas") or 0)
                midias_studio_real = int(d_est.get("midiasNoProjeto") or cnt.get("midias") or 0)
                duracao_studio_s = float(d_est.get("duracaoS") or 0.0)
        except Exception:
            pass

    blocos_srt = []
    if srt_texto:
        try:
            blocos_srt = validar_srt_skill6(srt_texto).get("blocos") or []
        except Exception:
            blocos_srt = []
    total_esperado = len(blocos_srt) or int((ctx["tarefa_mem"] or {}).get("total_cenas") or 0)

    # CASO 1 OU 3: REGULARIZAR CENAS GTA/ROCKSTAR COM MÁSCARA ANTI-COPYRIGHT OU COMPLETAR EDIÇÃO STUDIO (1:1 exato, sem sobrar 117/93!)
    if (pediu_gta or pediu_edicao_studio) and (srt_texto or (pasta_midias and os.path.isdir(pasta_midias))):
        agora_op = time.time()
        est_op = {
            "ok": True,
            "sp_id": sp_id,
            "nome_projeto": nome_proj,
            "canal_id": canal_id or ("a8068857-d56f-4aba-baf3-ea2b7ebda5bb" if pediu_gta else ""),
            "canal_nome": canal_nome or ("GTA à la Une" if pediu_gta else ""),
            "eh_video_real": True,
            "eh_gta_rockstar": bool(pediu_gta),
            "chat_modelo_opcao": chat_modelo_opcao,
            "modelo_resumo": _resolver_modelo_chat_dp(chat_modelo_opcao)["resumo"],
            "em_andamento": True,
            "pausado": False,
            "concluido_dp": False,
            "erro": "",
            "progresso_pct": 18,
            "cenas_prontas": min(midias_studio_real or 0, total_esperado or 9999),
            "total_cenas": total_esperado or 114,
            "jobs_rodando": max(1, (total_esperado or 114) - min(midias_studio_real or 0, total_esperado or 114)),
            "jobs_erros": 0,
            "segundos_decorridos": 0,
            "srt_texto": srt_texto,
            "srt_destino": ctx["srt_path"],
            "mp3_destino": ctx["mp3_path"],
            "pasta_creator": pasta_creator,
            "pasta_arquivos_video": ctx["pasta_arquivos_video"],
            "acao_tecnica": "regularizar_gta_rockstar" if pediu_gta else "reaplicar_edicao_studio",
            "etapa_atual": (
                f"🎮 Substituindo cenas por clipes oficiais Rockstar Games + máscara anti-copyright em '{nome_proj}' (preservando narração e SRT)..."
                if pediu_gta
                else f"🎬 Ajustando mídias 1:1 ({total_esperado or 114} blocos SRT) e reaplicando edição na mesma conversa..."
            ),
            "historico_acoes": [
                {
                    "ts": int(agora_op),
                    "hora": time.strftime("%H:%M:%S"),
                    "acao": "chat_operacional",
                    "texto": f"Comando recebido no Chat (mesma conversa): {msg_user or acao_rapida}",
                    "ok": True,
                }
            ],
            "iniciado_em": agora_op,
            "atualizado_em": agora_op,
        }
        with _LOCK_ETAPA7_DP:
            _TAREFAS_ETAPA7_DP[sp_id] = est_op
            if nome_proj:
                _TAREFAS_ETAPA7_DP[nome_proj.strip().lower()] = est_op

        def _bg_regularizar_projeto():
            def _foi_pausado_op():
                return _foi_cancelado_etapa7(sp_id=sp_id, nome_projeto=nome_proj)

            def _up_op(**kw):
                if _foi_pausado_op() and kw.get("acao_tecnica") != "pausado_usuario":
                    return
                t_now = time.time()
                with _LOCK_ETAPA7_DP:
                    msg_prev = est_op.get("etapa_atual") or ""
                    est_op.update(kw)
                    est_op["atualizado_em"] = t_now
                    est_op["segundos_decorridos"] = max(0, int(t_now - agora_op))
                    if kw.get("etapa_atual") and kw["etapa_atual"] != msg_prev:
                        h_l = list(est_op.get("historico_acoes") or [])
                        h_l.append({
                            "ts": int(t_now),
                            "hora": time.strftime("%H:%M:%S"),
                            "acao": est_op.get("acao_tecnica") or "progresso",
                            "texto": kw["etapa_atual"],
                            "ok": not bool(est_op.get("erro")),
                        })
                        est_op["historico_acoes"] = h_l[-45:]
                if origem_nuvem:
                    atualizar_status_etapa7_nuvem(
                        sp_id=sp_id,
                        nome_projeto=nome_proj,
                        em_andamento=est_op.get("em_andamento"),
                        concluido_dp=est_op.get("concluido_dp"),
                        pausado=est_op.get("pausado", False),
                        progresso_pct=est_op.get("progresso_pct"),
                        cenas_prontas=est_op.get("cenas_prontas"),
                        total_cenas=est_op.get("total_cenas"),
                        jobs_rodando=est_op.get("jobs_rodando"),
                        acao_tecnica=est_op.get("acao_tecnica"),
                        etapa_atual=est_op.get("etapa_atual"),
                        historico_acoes=list(est_op.get("historico_acoes") or [])[-25:],
                    )

            try:
                if _foi_pausado_op():
                    return
                p_proj_dir = pasta_creator or os.path.join(
                    obter_pasta_downloads_darkplanner(),
                    "studio",
                    re.sub(r"[^\w\- ]", "", nome_proj).strip() or "Projeto_GTA",
                )
                p_mid_dir = os.path.join(p_proj_dir, "midias")
                os.makedirs(p_mid_dir, exist_ok=True)
                stamp_gta = os.path.join(p_mid_dir, ".gta_anticopyright_stamp.json")

                if pediu_gta and not os.path.exists(stamp_gta):
                    _up_op(
                        progresso_pct=22,
                        acao_tecnica="limpar_stock_generico",
                        etapa_atual="Removendo clipes stock genéricos antigos para baixar cenas oficiais Rockstar Games + GTA...",
                    )
                    for fn_old in os.listdir(p_mid_dir):
                        if fn_old.lower().endswith((".mp4", ".jpg", ".jpeg", ".png", ".webp")):
                            try:
                                os.remove(os.path.join(p_mid_dir, fn_old))
                            except Exception:
                                pass

                cid_efetivo = "a8068857-d56f-4aba-baf3-ea2b7ebda5bb" if pediu_gta else canal_id
                cnome_efetivo = "GTA à la Une" if pediu_gta else canal_nome

                cenas_novas = []
                if srt_texto and not _foi_pausado_op():
                    qtd_bl_ef = len(blocos_srt) or total_esperado or 114
                    _up_op(
                        progresso_pct=28,
                        acao_tecnica="buscar_rockstar_oficial" if pediu_gta else "buscar_midias_reais",
                        etapa_atual=(
                            f"🌐 Buscando trailers/cenas em `rockstargames.com/fr/VI` + `@RockstarGames` YouTube para {qtd_bl_ef} cenas..."
                            if pediu_gta
                            else f"Conferindo mídias 1:1 sem repetição para {qtd_bl_ef} cenas..."
                        ),
                    )
                    res_busca = buscar_midias_reais_por_srt(
                        srt_texto=srt_texto,
                        titulo=nome_proj,
                        vid=ctx["vid"],
                        max_blocos_busca=max(500, qtd_bl_ef + 20),
                        canal_id=cid_efetivo,
                        canal_nome=cnome_efetivo,
                    )
                    cenas_novas = res_busca.get("cenas") or []

                if _foi_pausado_op():
                    return

                qtd_alvo_dl = len(blocos_srt) or len(cenas_novas) or total_esperado or 114
                _up_op(
                    progresso_pct=42,
                    acao_tecnica="baixar_mascarar_anticopyright",
                    etapa_atual=f"🎬 Sincronizando exatamente {qtd_alvo_dl} cenas (1:1 com o SRT existente)...",
                )
                verif_res = verificar_e_corrigir_midias_sem_repeticao(
                    pasta_midias=p_mid_dir,
                    cenas_reais=cenas_novas,
                    total_cenas_esperadas=qtd_alvo_dl,
                    srt_texto=srt_texto,
                    titulo=nome_proj,
                    priorizar_videos=True,
                    canal_id=cid_efetivo,
                    canal_nome=cnome_efetivo,
                )
                if _foi_pausado_op() or verif_res.get("pausado"):
                    return

                arqs_finais = (verif_res.get("arquivos_ordenados") or [])[:len(blocos_srt)] if blocos_srt else (verif_res.get("arquivos_ordenados") or [])
                # Remove arquivos sobressalentes não-canônicos da pasta midias/ para NUNCA acontecer "117 de 93"!
                if arqs_finais and os.path.isdir(p_mid_dir):
                    set_canon = {os.path.normcase(os.path.abspath(p)) for p in arqs_finais if p}
                    for fn_ex in os.listdir(p_mid_dir):
                        if fn_ex.lower().endswith((".mp4", ".jpg", ".jpeg", ".png", ".webp", ".mov", ".mkv")):
                            p_ex = os.path.join(p_mid_dir, fn_ex)
                            if os.path.normcase(os.path.abspath(p_ex)) not in set_canon:
                                try:
                                    os.remove(p_ex)
                                except Exception:
                                    pass

                if pediu_gta and arqs_finais:
                    try:
                        with open(stamp_gta, "w", encoding="utf-8") as fst:
                            json.dump({"ok": True, "ts": int(time.time()), "total": len(arqs_finais)}, fst)
                    except Exception:
                        pass

                conv_real_ok = False
                conv_id_op = (ctx["tarefa_mem"] or {}).get("conversa_id") or ""
                prompt_chat_dp = (
                    f"[CONTINUAÇÃO NA MESMA CONVERSA — NÃO RECRIE ROTEIRO, PONTO DE VISTA NEM NARRAÇÃO!]\n"
                    f"Projeto Studio '{nome_proj}': atualize apenas a timeline V1 com as {len(arqs_finais)} cenas 1:1 já sincronizadas "
                    f"com a narração e o SRT existentes (`acao=\"abrir\"`, `projeto=\"{nome_proj}\"`)."
                )
                if msg_user:
                    prompt_chat_dp += f"\nPedido específico do usuário: {msg_user}"
                _up_op(
                    progresso_pct=76,
                    cenas_prontas=len(arqs_finais),
                    jobs_rodando=1,
                    acao_tecnica="atualizar_mesma_conversa_dp",
                    etapa_atual=f"Enviando ajuste na mesma conversa do DarkPlanner com {len(arqs_finais)} cenas 1:1...",
                )
                res_chat_op = abrir_chat_darkplanner_e_colar(
                    mensagem_chat=prompt_chat_dp,
                    auto_enviar=True,
                    nova_conversa=bool(nova_conversa_req),
                    chat_modelo_opcao=chat_modelo_opcao,
                    forcar_reenvio=True,
                    titulo_conversa=nome_proj,
                    auto_reconectar_cdp=True,
                    focar_janela=True,
                ) or {}
                conv_real_ok = bool(res_chat_op.get("cdp_enviou") or res_chat_op.get("enviado_direto_chat"))
                conv_id_op = res_chat_op.get("conversa_id") or conv_id_op
                if conv_real_ok:
                    time.sleep(2.2)

                if _foi_pausado_op():
                    return

                _up_op(
                    progresso_pct=82,
                    cenas_prontas=len(arqs_finais),
                    jobs_rodando=0,
                    acao_tecnica="montar_timeline_studio",
                    etapa_atual=f"Importando exatamente {len(arqs_finais)} cenas no DarkPlanner Studio 1:1 com o SRT...",
                )
                cfg_ed_op = {"predef": "sys_tudo", "densidade_destaques": "dinamico" if pediu_gta else "equilibrado"}
                res_st_op = aplicar_midias_reais_no_studio_ao_vivo(
                    nome_projeto=nome_proj,
                    arqs_midia_baixados=arqs_finais,
                    blocos_srt=blocos_srt,
                    canal_nome=cnome_efetivo,
                    mp3_destino=ctx["mp3_path"],
                    srt_destino=ctx["srt_path"],
                    edicao_config=cfg_ed_op,
                    job_id=ctx["job_id"],
                    pular_auditoria=True,
                    mensagem_chat_wake=("" if conv_real_ok else prompt_chat_dp),
                    tentar_despertar_cdp=(not conv_real_ok),
                ) or {}
                if _foi_pausado_op():
                    return

                if not res_st_op.get("ok") and conv_real_ok:
                    for _ in range(10):
                        if _foi_pausado_op():
                            return
                        time.sleep(2.0)
                        if _ler_ponte_local_dp():
                            res_st_op = aplicar_midias_reais_no_studio_ao_vivo(
                                nome_projeto=nome_proj,
                                arqs_midia_baixados=arqs_finais,
                                blocos_srt=blocos_srt,
                                canal_nome=cnome_efetivo,
                                mp3_destino=ctx["mp3_path"],
                                srt_destino=ctx["srt_path"],
                                edicao_config=cfg_ed_op,
                                job_id=ctx["job_id"],
                                pular_auditoria=True,
                                tentar_despertar_cdp=False,
                            ) or {}
                            if res_st_op.get("ok"):
                                break

                for _ in range(90):
                    if _foi_pausado_op():
                        return
                    chk_w = _verificar_chat_dp_gerando_projeto_cdp(nome_proj)
                    if not chk_w.get("gerando"):
                        break
                    _up_op(
                        progresso_pct=95,
                        acao_tecnica="gerando_edicao_darkplanner",
                        etapa_atual=f"⏳ Aguardando DarkPlanner concluir ajuste na mesma conversa ({chk_w.get('ultimo_status') or 'em execução'})...",
                    )
                    time.sleep(3.0)

                if _foi_pausado_op():
                    return

                if not res_st_op.get("ok") and conv_real_ok:
                    res_st_op = {"ok": True, "cenas_no_studio": len(arqs_finais), "via_chat_cdp": True}

                vigiando_ponte_op = False
                if not res_st_op.get("ok") and arqs_finais:
                    _vigiar_ponte_studio_e_montar_assim_que_abrir(
                        sp_id=sp_id,
                        nome_projeto=nome_proj,
                        arqs_midia_baixados=arqs_finais,
                        blocos_srt=blocos_srt,
                        canal_nome=cnome_efetivo,
                        mp3_destino=ctx["mp3_path"],
                        srt_destino=ctx["srt_path"],
                        edicao_config=cfg_ed_op,
                        job_id=ctx["job_id"],
                    )
                    vigiando_ponte_op = True

                cenas_st_fim = int((res_st_op or {}).get("cenas_no_studio") or len(arqs_finais))
                if blocos_srt:
                    cenas_st_fim = min(len(blocos_srt), cenas_st_fim)
                ok_final_op = bool(res_st_op.get("ok") or vigiando_ponte_op)
                _up_op(
                    em_andamento=False,
                    concluido_dp=ok_final_op,
                    erro="",
                    progresso_pct=100 if ok_final_op else 80,
                    cenas_prontas=cenas_st_fim,
                    total_cenas=len(blocos_srt) or len(arqs_finais),
                    conversa_id=conv_id_op,
                    conversa_criada_real_dp=conv_real_ok,
                    studio_sincronizado=bool(res_st_op.get("ok")),
                    modo_pacote_7812_matriz=vigiando_ponte_op,
                    acao_tecnica="concluido" if res_st_op.get("ok") else "concluido_pacote_vigiando_studio",
                    etapa_atual=(
                        f"✅ Regularização 100% concluída na mesma conversa: {cenas_st_fim}/{len(blocos_srt) or len(arqs_finais)} cenas 1:1 no Studio!"
                        if res_st_op.get("ok")
                        else f"✅ {cenas_st_fim}/{len(blocos_srt) or len(arqs_finais)} cenas prontas 1:1 (Vigia Studio ativo)!"
                    ),
                )
            except Exception as e_bg_op:
                if _foi_pausado_op():
                    return
                _up_op(
                    em_andamento=False,
                    concluido_dp=False,
                    acao_tecnica="erro_regularizacao",
                    erro=str(e_bg_op),
                    etapa_atual=f"⚠️ Erro durante a regularização no DarkPlanner: {str(e_bg_op)[:160]}",
                )

        threading.Thread(target=_bg_regularizar_projeto, daemon=True).start()
        return {
            "ok": True,
            "mesma_conversa": not bool(nova_conversa_req),
            "em_andamento": True,
            "sp_id": sp_id,
            "nome_projeto": nome_proj,
            "status_etapa7": est_op,
            "acoes_executadas": acoes_executadas,
            "resposta": (
                f"🚀 **Regularização iniciada {'em nova conversa' if nova_conversa_req else 'NA MESMA CONVERSA'} no Chat do DarkPlanner para `{nome_proj}`!**\n"
                f"• **Roteiro, ponto de vista e narração MP3 originais mantidos intactos** (sem recriar do zero);\n"
                + (
                    f"• Substituindo apenas as cenas por **{total_esperado or 'todas as'} cenas oficiais `rockstargames.com/fr/VI` + `@RockstarGames`** mascaradas;\n"
                    if pediu_gta
                    else f"• Ajustando exatamente **{total_esperado or 114} cenas 1:1** (removendo mídias duplicadas/extras);\n"
                )
                + "• Enviando diretamente no Chat e na timeline V1 do DarkPlanner sem fechar o aplicativo."
            ),
        }

    # CASO 2: CRIAR NOVA CONVERSA SOMENTE QUANDO O USUÁRIO SOLICITOU EXPLICITAMENTE ("➕ Nova Conversa" / acao_rapida == "criar_conversa_dp")
    if pediu_conversa:
        rec_res = reconectar_cdp_darkplanner_seguro(forcar=False, permitir_com_jobs=False)
        prompt_conv = ctx["mensagem_chat"] or (
            f"Abra e verifique o projeto Studio \"{nome_proj}\". Mantenha o roteiro, a narração e o SRT já prontos e confirme "
            f"se todas as {total_esperado or cenas_studio_real} cenas estão sincronizadas 1:1."
        )
        if msg_user and len(msg_user) > 12 and not acao_rapida:
            prompt_conv = f"[Projeto Studio: \"{nome_proj}\"]\n{msg_user}"

        env_res = abrir_chat_darkplanner_e_colar(
            mensagem_chat=prompt_conv,
            auto_enviar=True,
            nova_conversa=True,
            chat_modelo_opcao=chat_modelo_opcao,
            forcar_reenvio=True,
            titulo_conversa=nome_proj,
            auto_reconectar_cdp=True,
            focar_janela=True,
        )
        criou_real = bool(env_res.get("cdp_enviou") or env_res.get("enviado_direto_chat"))
        conv_id_salvo = env_res.get("conversa_id") or ""
        if ctx["tarefa_mem"] is not None:
            with _LOCK_ETAPA7_DP:
                ctx["tarefa_mem"]["conversa_id"] = conv_id_salvo or ctx["tarefa_mem"].get("conversa_id") or ""
                ctx["tarefa_mem"]["conversa_criada_real_dp"] = criou_real
                ctx["tarefa_mem"]["precisa_reconectar_cdp"] = not criou_real

        if criou_real:
            return {
                "ok": True,
                "nova_conversa_criada": True,
                "conversa_criada_real_dp": True,
                "conversa_id": conv_id_salvo,
                "sp_id": sp_id,
                "nome_projeto": nome_proj,
                "resposta": (
                    f"✅ **Nova conversa aberta e enviada diretamente no Chat do DarkPlanner Desktop!**\n"
                    f"• Projeto: `{nome_proj}`"
                ),
            }
        if rec_res.get("preservado_aberto"):
            return {
                "ok": True,
                "conversa_criada_real_dp": False,
                "conversa_id": conv_id_salvo,
                "preservado_aberto": True,
                "sp_id": sp_id,
                "nome_projeto": nome_proj,
                "resposta": (
                    f"🛡️ **DarkPlanner Desktop trazido para frente intacto** e mensagem copiada pronta no Chat (`{conv_id_salvo or nome_proj}`)!"
                ),
            }
        motivo_nc = rec_res.get("motivo") or str((env_res.get("cdp_detalhe") or {}).get("erro") or "DarkPlanner não respondeu")
        return {
            "ok": False,
            "conversa_criada_real_dp": False,
            "sp_id": sp_id,
            "nome_projeto": nome_proj,
            "resposta": f"⚠️ **Conversa salva em `Histórico de conversas`, mas não foi possível colar automaticamente no Chat**: {motivo_nc}",
        }

    # CASO 4: CORREÇÃO CIRÚRGICA NA MESMA CONVERSA (SEM GERAR NOVO ROTEIRO / NOVA NARRAÇÃO / NOVO PONTO DE VISTA!)
    em_edicao_real = bool(chk_cdp_live.get("gerando")) or (total_esperado > 0 and 0 < midias_studio_real < total_esperado)
    if em_edicao_real and ctx["tarefa_mem"] is not None:
        with _LOCK_ETAPA7_DP:
            ctx["tarefa_mem"]["em_andamento"] = True
            ctx["tarefa_mem"]["pausado"] = False
            ctx["tarefa_mem"]["concluido_dp"] = False
            ctx["tarefa_mem"]["cenas_prontas"] = min(midias_studio_real or cenas_studio_real, total_esperado or 9999)
            ctx["tarefa_mem"]["progresso_pct"] = min(95, int(((midias_studio_real or cenas_studio_real) / max(1, total_esperado)) * 92))
            ctx["tarefa_mem"]["acao_tecnica"] = "gerando_edicao_darkplanner"
            ctx["tarefa_mem"]["etapa_atual"] = (
                f"⏳ Em andamento real no DarkPlanner: {min(midias_studio_real, total_esperado or midias_studio_real)}/{total_esperado} mídias, {cenas_studio_real} cenas na timeline"
                + (f" ({chk_cdp_live.get('ultimo_status')})" if chk_cdp_live.get("ultimo_status") else "")
            )

    enviou_instrucao_extra = False
    if msg_user and not acao_rapida and not any(k in msg_low for k in ("status", "verifi", "como esta", "como está")):
        res_dir = abrir_chat_darkplanner_e_colar(
            mensagem_chat=(
                f"[CONTINUAÇÃO NA MESMA CONVERSA DO PROJETO \"{nome_proj}\" — "
                f"PROIBIDO GERAR NOVO ROTEIRO, NOVO PONTO DE VISTA OU NOVA NARRAÇÃO!]\n"
                f"Corrija pontualmente no projeto atual apenas o que foi solicitado abaixo:\n{msg_user}"
            ),
            auto_enviar=True,
            nova_conversa=bool(nova_conversa_req),
            chat_modelo_opcao=chat_modelo_opcao,
            forcar_reenvio=True,
            titulo_conversa=nome_proj[:55],
            auto_reconectar_cdp=True,
            focar_janela=True,
        )
        enviou_instrucao_extra = bool(res_dir.get("cdp_enviou") or res_dir.get("enviado_direto_chat"))

    midias_exib = f"{min(midias_studio_real, total_esperado)}" if (total_esperado and midias_studio_real > total_esperado) else f"{midias_studio_real}"
    linhas_diag = [
        f"📊 **Diagnóstico Real do Projeto — `{nome_proj}`**:",
        f"• **API Creator (7812)**: {'🟢 Online' if info_dp.get('api_ativa') else '🟡 Modo Ponte/Matriz'} | **Ponte Studio**: {'🟢 Conectada' if ponte_st else '🔴 Desconectada'} | **Chat CDP (9229)**: {'🟢 Conectado' if chk_cdp_live.get('cdp_ativo') else '🟡 Preservado aberto'}",
        f"• **Mídias sincronizadas**: `{midias_exib}`" + (f" de `{total_esperado}` esperadas" if total_esperado else "") + f" | **Cenas na timeline V1**: `{cenas_studio_real}` | **Duração**: `{duracao_studio_s:.1f}s`",
    ]
    if em_edicao_real:
        linhas_diag.append("• 🔄 **Status real atualizado**: o projeto continua em edição no Studio.")
    if enviou_instrucao_extra:
        linhas_diag.append("• ✅ **Correção enviada NA MESMA CONVERSA (roteiro, ponto de vista e narração mantidos 100% intactos)!**")
    elif msg_user and not any(k in msg_low for k in ("status", "verifi", "como esta", "como está")):
        try:
            from core import antigravity_codex

            res_ag_fb = antigravity_codex.conversar_agente_antigravity_codex(
                mensagem=msg_user,
                historico=d.get("historico") or [],
                contexto_projeto={"sp_id": sp_id, "nome_projeto": nome_proj, "canal_id": canal_id, "canal_nome": canal_nome, "vid": ctx["vid"]},
            )
            if res_ag_fb.get("resposta"):
                linhas_diag.append(f"\n🤖 **Agente Antigravity + Codex**:\n{res_ag_fb['resposta']}")
        except Exception:
            pass

    return {
        "ok": True,
        "mesma_conversa": not bool(nova_conversa_req),
        "sp_id": sp_id,
        "nome_projeto": nome_proj,
        "em_andamento": em_edicao_real,
        "cenas_no_studio": cenas_studio_real,
        "midias_no_studio": min(midias_studio_real, total_esperado) if total_esperado else midias_studio_real,
        "total_esperado": total_esperado,
        "cdp_ativo": bool(chk_cdp_live.get("cdp_ativo")),
        "status_etapa7": ctx["tarefa_mem"],
        "resposta": "\n".join(linhas_diag),
    }


_registrar_rotas_dinamicas_flask()




